window.DOSIK=window.DOSIK||{};DOSIK.english={"ebs27sd_t3_22":[{"t":"tree","title":"감각 기억","root":"애트킨슨과 쉬프린(Atkinson & Shiffrin, 1968)의 모형은 기억을 나눈다","branches":[["감각 기억(sensory memory)"],["단기 기억"],["장기 기억"]]},{"t":"tree","title":"감각 기억의 종류","root":"감각 기억","branches":[["영상 기억(iconic memory)","스펄링(Sperling, 1960)은 시각 감각 기억인 영상 기억이 아주 짧게 지속됨을 보였다"],["잔향 기억(echoic memory)","청각에는 잔향 기억이 있다"]]}],"ebs27sd_t3_23":[{"t":"def","term":"평균으로의 회귀(regression to the mean)","text":"통계학에서 프랜시스 골턴(Francis Galton, 1886)이 키 유전 연구에서 발견했으며 극단적인 값 다음에는 평균에 가까운 값이 나오기 쉬운 현상이다"},{"t":"tree","title":"평균으로의 회귀와 관련 개념","root":"평균으로의 회귀","branches":[["카너먼(Kahneman)","사람들이 이를 인과로 잘못 설명한다고 지적했다"],["착각적 상관(illusory correlation)과 도박사의 오류(gambler's fallacy)","관련 개념이다"]]}],"ebs27sd_t3_24":[{"t":"def","term":"하이퍼인플레이션(hyperinflation)","text":"경제학에서 물가가 월 50퍼센트 이상 급등하는 상황을 가리킨다","ex":["1923년 독일 바이마르 공화국","2008년 짐바브웨"]},{"t":"cause","title":"통화량 증가","causes":["정부가 세입 없이 화폐를 발행한다"],"result":"통화량(money supply)이 늘어 통화 가치가 떨어진다","effects":["중앙은행(central bank)의 통화 정책(monetary policy)이 관련된다"]}],"ebs27sd_t3_25":[{"t":"def","term":"하이퍼인플레이션(hyperinflation)","text":"경제학에서 물가가 월 50퍼센트 이상 급등하는 상황을 가리킨다","ex":["1923년 독일 바이마르 공화국","2008년 짐바브웨"]},{"t":"cause","title":"통화량 증가","causes":["정부가 세입 없이 화폐를 발행한다"],"result":"통화량(money supply)이 늘어 통화 가치가 떨어진다","effects":["중앙은행(central bank)의 통화 정책(monetary policy)이 관련된다"]}],"ebs27ws_c01_1":[{"t":"tree","title":"걱정과 불안","root":"걱정과 불확실성","branches":[["걱정(worry)","심리학에서 미래의 불확실한 위협을 예상하며 반복적으로 생각하는 인지 과정이다"],["불안(anxiety)","위협에 대비하게 하는 적응적 반응이지만 지나치면 불안 장애(anxiety disorder)로 이어질 수 있다"],["불확실성 불내성(intolerance of uncertainty)","걱정을 키우는 요인으로 연구된다"]]}],"ebs27ws_c01_2":[{"t":"tree","title":"발견의 서사와 과학","root":"과학철학","branches":[["귀납적 설명","증거를 모아 논리적으로 추론한다는 이야기는 실제 연구 과정과 다르다는 비판이 있다"],["쿤(Kuhn)","과학 발전이 패러다임(paradigm) 전환을 통해 일어난다고 보았다"],["구분","발견의 맥락(context of discovery)과 정당화의 맥락(context of justification)의 구분과도 관련된다"]]}],"ebs27ws_c01_4":[{"t":"def","term":"매체(medium)","text":"정보와 의미를 전달하는 수단으로, 미디어 이론에서 중요한 개념이다"},{"t":"tree","title":"매체의 이론과 구분","root":"매체","branches":[["맥루언(McLuhan)","매체 자체가 메시지라고 주장하며 매체가 사회와 인식을 바꾼다고 보았다"],["구분","문자, 인쇄, 전자 매체 등 물질적 형식에 따라 구분된다"]]}],"ebs27ws_c01_5":[{"t":"def","term":"알고리즘 편향(algorithmic bias)","text":"인공지능(AI) 윤리에서 과거 데이터에 담긴 편견이 모델 결과에 되풀이되는 문제다"},{"t":"cause","title":"학습 데이터의 대표성","causes":["학습 데이터(training data)의 대표성이 부족하다"],"result":"특정 집단에 불리한 결과가 나올 수 있다"},{"t":"def","term":"개인정보 보호와 동의","text":"데이터 윤리의 기본 쟁점이다"}],"ebs27ws_c01_6":[{"t":"tree","title":"민족음악학","root":"민족음악학(ethnomusicology)","branches":[["정의","음악을 문화와 사회 맥락 속에서 연구하는 분야다"],["콜린 맥피(Colin McPhee)","발리 가믈란(gamelan) 음악을 서양에 소개한 작곡가이자 연구자다"],["민족중심주의(ethnocentrism)","서양 음악 개념으로 다른 문화의 음악을 평가하는 민족중심주의를 경계하는 것이 이 분야의 중요한 시각이다"]]}],"ebs27ws_c02_1":[{"t":"tree","title":"옥타브와 주파수","root":"음악 음향학","branches":[["옥타브(octave)","같은 이름의 음이 되풀이되는 간격이다"],["도-레-미 이름","서양 음악에서 도-레-미 이름이 옥타브마다 반복되는 것은 지각적 유사성 때문이다"],["음높이(pitch)","주파수에 대한 지각이며 음의 이름은 이를 기호화한 것이다"]]}],"ebs27ws_c02_2":[{"t":"tree","title":"서사 구조와 인물","root":"극작과 소설 창작론","branches":[["인물(character)","이야기에서 구체적 기능을 맡아야 한다고 본다"],["같은 역할을 하는 인물","하나로 합치는 것이 이야기의 밀도를 높인다는 것이 창작 교본의 일반적 조언이다"],["서사학(narratology)","인물과 사건의 구조를 분석한다"]]}],"ebs27ws_c02_3":[{"t":"def","term":"단순 노출 효과(mere exposure effect)","text":"사회심리학에서 자잔(Zajonc)이 정리한 개념으로, 접촉이 반복될수록 호감이 높아지는 현상이다"},{"t":"tree","title":"브랜드","root":"브랜드","branches":[["친숙성(familiarity)","브랜드는 이런 친숙성을 통해 선호를 키운다"],["소비자 행동 연구","브랜드를 소비자의 경험과 인식의 총합으로 정의한다"]]}],"ebs27ws_c02_4":[{"t":"def","term":"재현(representation)","text":"예술철학에서 예술 작품이 어떤 대상을 나타내거나 닮는 것을 뜻한다"},{"t":"vs","title":"모방론과 표현론","cols":[{"name":"모방론(mimesis)","items":["예술의 본질을 현실의 모방으로 본다"]},{"name":"표현론","items":["예술이 감정을 표현한다고 본다"]}]},{"t":"def","term":"초상화(portrait)","text":"닮음(likeness)과 예술적 가치가 어떻게 연결되는지를 묻는 사례로 자주 쓰인다"}],"ebs27ws_c02_5":[{"t":"def","term":"잊힐 권리(right to be forgotten)","text":"개인이 인터넷에 있는 자신의 정보를 삭제해 달라고 요구할 권리다"},{"t":"tree","title":"잊힐 권리의 쟁점","root":"잊힐 권리","branches":[["2014년 유럽사법재판소","구글 스페인 사건에서 검색 결과 삭제 요구를 인정했다"],["프라이버시(privacy)","이 권리는 프라이버시와 관련해 법과 정책에서 논쟁된다"]]}],"ebs27ws_c02_6":[{"t":"vs","title":"집단 지성과 집단사고","cols":[{"name":"집단 지성(collective intelligence)","items":["구성원의 의견을 모을 때 개인보다 나은 판단이 나온다는 개념이다","서로위키(Surowiecki)의 『대중의 지혜』는 의견의 다양성과 독립성이 조건이라고 설명했다"]},{"name":"집단사고(groupthink)","items":["팀 의사결정에서 반대 사례로 연구된다"]}]}],"ebs27ws_c03_1":[{"t":"vs","title":"전기와 자서전","cols":[{"name":"전기(biography)","items":["문학 연구에서 타인의 삶을 기록한다","전기 작가는 문서, 인터뷰, 가족 기록 같은 자료를 비교해 신뢰성을 평가한다"]},{"name":"자서전(autobiography)","items":["본인이 쓰는 삶의 기록이다","삶의 서술자(life narrator)는 자서전 연구에서 자기 삶을 이야기하는 사람을 가리킨다"]}]}],"ebs27ws_c03_2":[{"t":"tree","title":"학문적 정직성","root":"학문적 정직성(academic integrity)","branches":[["원칙","연구와 학습에서 정직, 신뢰, 공정, 책임을 지키는 원칙이다"],["위반","표절(plagiarism)과 연구 부정행위(research misconduct)는 대표적 위반이며 대학은 이를 예방하기 위한 윤리 교육을 한다"],["생성형 AI","최근에는 생성형 AI 사용에 관한 기준도 논의된다"]]}],"ebs27ws_c03_3":[{"t":"def","term":"사회적 존재감(social presence)","text":"원격 교육에서 학습자가 온라인 환경에서 상대를 실제 사람으로 느끼는 정도다"},{"t":"def","term":"탐구 공동체 모델(Community of Inquiry)","text":"사회적 존재감을 효과적 학습의 핵심 요소로 본다"},{"t":"cause","title":"존재감과 학습","causes":["존재감이 낮다"],"result":"고립감이 커진다","effects":["학습 동기와 중도 탈락에 영향을 준다고 연구된다"]}],"ebs27ws_c03_4":[{"t":"vs","title":"암묵지와 형식지","cols":[{"name":"암묵지(tacit knowledge)","items":["폴라니(Polanyi)가 말한 우리는 말할 수 있는 것보다 더 많이 안다는 개념으로, 말이나 글로 표현하기 어려운 경험적 지식이다","인공지능이 전문가의 직관을 대체할 수 있는지 논의할 때 자주 쓰인다"]},{"name":"형식지(explicit knowledge)","items":["암묵지와 대비된다"]}]}],"ebs27ws_c03_5":[{"t":"tree","title":"침묵과 리듬","root":"침묵(silence)","branches":[["음악학","소리의 부재가 아니라 음악의 의미를 만드는 요소로 여겨진다"],["존 케이지(John Cage)","「4분 33초」는 침묵과 주변 소리를 음악으로 들려 준 작품이다"],["말하기 분야","연설과 협상 같은 말하기 분야에서도 침묵의 활용이 연구된다"]]}],"ebs27ws_c03_6":[{"t":"cause","title":"손의 해방과 도구","causes":["직립 보행(bipedalism)"],"result":"인류 진화에서 손의 쓰임을 크게 바꾼 요인으로 논의된다","effects":["대립 가능한 엄지(opposable thumb)는 정교한 쥐기를 가능하게 했다","도구 사용(tool use)은 뇌 발달과 상호작용하며 인류 진화에 영향을 준 것으로 논의된다"]}],"ebs27ws_c04_1":[{"t":"tree","title":"음식과 식문화","root":"음식과 식문화의 변화","branches":[["음식","생존의 필수 조건이면서 농업, 가공, 유통, 외식으로 이어지는 큰 산업이다"],["식문화(food culture)","음식을 만들고 먹는 방식에 담긴 사회적 의미를 가리킨다"],["브리야사바랭(Brillat-Savarin)","프랑스의 미식가로 『미식 예찬』으로 알려져 있다"]]}],"ebs27ws_c04_2":[{"t":"flow","title":"가설 연역적 방법","steps":["가설을 세운다","그로부터 검증 가능한 예측을 연역한다","관찰로 시험한다"]},{"t":"tree","title":"과학적 방법과 전문직","root":"가설 연역적 방법(hypothetico-deductive method)","branches":[["포퍼(Popper)","반증 가능성(falsifiability)을 과학의 기준으로 제시했다"],["쇤(Schön)","『성찰하는 실천가』에서 전문직 실천이 기술적 합리성만으로 설명되지 않는다고 비판했다"]]}],"ebs27ws_c04_3":[{"t":"tree","title":"도덕의 기원","root":"진화 윤리학(evolutionary ethics)","branches":[["진화의 관점","도덕의 기원을 진화의 관점에서 설명하려 한다"],["프란스 드 발(Frans de Waal)","영장류의 사회적 행동을 오래 연구해 왔다"],["핵심 개념","이타주의(altruism)와 호혜성(reciprocity)이 핵심 개념이다"]]}],"ebs27ws_c04_5":[{"t":"def","term":"균형(equilibrium)","text":"경제학에서 수요와 공급이 일치하는 상태다"},{"t":"vs","title":"기업가의 역할","cols":[{"name":"커즈너(Kirzner)","items":["오스트리아학파 경제학자로 기업가(entrepreneur)의 역할을 시장 과정의 관점에서 설명했다"]},{"name":"슘페터(Schumpeter)","items":["기업가의 혁신을 강조했다"]}]}],"ebs27ws_c04_6":[{"t":"tree","title":"합리적 선택 이론","root":"합리적 선택 이론(rational choice theory)","branches":[["가정","개인이 이익을 극대화하는 최적 대안을 고른다고 가정하는 경제학의 표준 모형이다"],["인간상","호모 에코노미쿠스(Homo economicus)라 불리며 행동경제학의 비판을 받는다"],["사이먼(Simon)","제한된 합리성(bounded rationality)을 제안했다"]]}],"ebs27ws_c05_1":[{"t":"tree","title":"매체와 정서적 거리","root":"미디어 심리학","branches":[["연구 주제","TV 같은 매체가 시청자의 감정에 미치는 영향을 연구한다"],["유사 사회적 관계(parasocial interaction)","시청자가 방송 인물과 일방적인 친밀감을 느끼는 현상이다"],["정서적 거리(emotional distance)","대상을 가깝게 또는 멀게 느끼는 정도를 말한다"]]}],"ebs27ws_c05_2":[{"t":"def","term":"기후변화(climate change)","text":"영향은 지역에 따라 불균등하게 나타난다"},{"t":"vs","title":"지역별 영향","cols":[{"name":"고위도 지역","items":["난방 에너지 감소와 농업 가능 기간 증가 같은 일부 이점이 있을 수 있다"]},{"name":"저위도와 해안 지역","items":["폭염과 해수면 상승에 취약하다"]}]},{"t":"def","term":"기후 정의(climate justice)","text":"책임이 적은 지역이 더 큰 피해를 입는 불평등을 다룬다"}],"ebs27ws_c05_3":[{"t":"def","term":"개념 팽창(concept creep)","text":"호주 심리학자 닉 해슬럼(Nick Haslam)이 2016년 제안한 개념으로, 학대, 트라우마, 편견 같은 해악 관련 개념의 의미가 점점 넓어지는 현상이다"},{"t":"tree","title":"개념 팽창의 형태","root":"개념 팽창","branches":[["수직적 팽창"],["수평적 팽창"]]},{"t":"vs","title":"해석과 비판","cols":[{"name":"해석","items":["사회 규범 변화와 민감성 증가를 반영한다"]},{"name":"비판","items":["개념의 모호성을 낳는다"]}]}],"ebs27ws_c05_4":[{"t":"tree","title":"모어 화자 특권 비판","root":"응용언어학","branches":[["모어 화자(native speaker)","이상적 모델로 보는 관점은 비판받아 왔다"],["쿡(Cook)","다중 언어 능력(multicompetence)이라는 개념으로 이중 언어 사용자의 능력을 고유한 것으로 보았다"],["세계 영어(World Englishes)","영어가 여러 지역에서 정당한 변종으로 쓰인다는 관점이다"]]}],"ebs27ws_c05_5":[{"t":"flow","title":"이성과 서양 사상","steps":["데카르트(Descartes)는 이성을 지식의 확실한 기반으로 삼은 근대 합리론(rationalism)의 대표 철학자다","계몽주의는 이성을 인간의 핵심 능력으로 보았다","이후 이성에 대한 비판이 문학 이론과 철학에서 제기되었고, 데리다(Derrida)는 해체주의로 알려진 프랑스 철학자다"]}],"ebs27ws_c05_6":[{"t":"tree","title":"진정성의 지각","root":"진정성(authenticity)","branches":[["정의","사회심리학에서 겉으로 드러나는 모습이 내면과 일치하는 정도다"],["판단 단서","사람들은 상대의 표정과 행동 같은 단서로 진정성을 판단한다"],["관점","이 글은 진정성을 적응적 판단의 근거로 보는 관점이다"]]}],"ebs27ws_c06_2":[{"t":"vs","title":"연속성과 비연속성","cols":[{"name":"연속성(continuity)","items":["발달심리학에서 발달이 점진적 양적 변화라는 관점이다"]},{"name":"비연속성(discontinuity)","items":["질적으로 다른 단계로 이동한다는 관점이다","피아제(Piaget)의 인지 발달 단계설은 비연속적 입장의 대표적 이론이다"]}]},{"t":"def","term":"발달을 보는 관점","text":"발달을 어떻게 볼지는 발달심리학의 오랜 논쟁이다"}],"ebs27ws_c06_3":[{"t":"vs","title":"영원주의와 현재주의","cols":[{"name":"영원주의(eternalism)","items":["철학의 시간론에서 과거, 현재, 미래의 모든 사건이 똑같이 실재한다고 본다","블록 우주(block universe) 관점은 특수 상대성 이론과 관련해 논의된다"]},{"name":"현재주의(presentism)","items":["현재만 실재한다고 본다"]}]},{"t":"def","term":"시간의 표상","text":"심리학은 사람이 시간을 어떻게 표상하는지를 인지적 관점에서 연구한다"}],"ebs27ws_c06_4":[{"t":"tree","title":"신호와 잡음","root":"신호 탐지 이론(signal detection theory)","branches":[["분석 대상","잡음(noise) 속에서 신호(signal)를 찾아내는 과정을 분석한다"],["칵테일파티 효과(cocktail party effect)","시끄러운 환경에서도 원하는 소리에 선택적으로 주의를 기울이는 현상이다"],["동물 의사소통 연구","많은 종이 잡음 속에서도 소통하는 방법을 진화시켰다고 본다"]]}],"ebs27ws_c06_6":[{"t":"def","term":"지속 사냥(persistence hunting) 가설","text":"인류학에서 초기 인류가 사냥감이 지칠 때까지 오래 추적해 잡았다고 보는 이론이다"},{"t":"cause","title":"지구력 달리기 가설","causes":["인간은 땀샘이 많고 털이 적으며 장거리 달리기에 적합한 신체 구조를 가졌다"],"result":"근거로 제시되며 이를 지구력 달리기 가설(endurance running hypothesis)이라 한다"}],"ebs27ws_c07_1":[{"t":"tree","title":"동물의 지각 조작","root":"감각 생태학(sensory ecology)","branches":[["지각 편향(perceptual bias)","동물은 포식자나 짝의 지각 편향을 이용하는 형질을 진화시켰다"],["위장(camouflage)과 의태(mimicry)","포식자의 지각을 속이는 방어 방식이다"],["바우어새(bowerbird)","정자(bower)를 꾸며 짝에게 인상을 주는 것으로 알려져 있다"]]}],"ebs27ws_c07_2":[{"t":"tree","title":"도덕 추론","root":"도덕 심리학","branches":[["쟁점","도덕 판단이 이성적 추론에서 나오는지 직관에서 나오는지는 쟁점이다"],["하이트(Haidt)","도덕 판단이 직관 중심이라는 사회적 직관주의(social intuitionism)를 제안했다"],["비교문화 심리학","권리에 대한 태도가 문화마다 어떻게 다른지도 주제다"]]}],"ebs27ws_c07_3":[{"t":"tree","title":"사회적 자본의 쇠퇴","root":"로버트 퍼트넘(Robert Putnam)의 『나 홀로 볼링』(2000)","branches":[["분석","미국에서 시민 참여와 공동체 활동이 줄어드는 현상을 분석했다"],["사회적 자본(social capital)","신뢰, 규범, 네트워크가 만드는 협력 자원이다"],["볼링 리그 감소","사회 참여 쇠퇴의 상징으로 제시되었다"]]}],"ebs27ws_c07_4":[{"t":"tree","title":"앙상블 집단 역학","root":"앙상블(ensemble)","branches":[["정의","음악 심리학에서 여러 연주자가 함께 연주하는 집단이며 집단 역학(group dynamics)이 연구된다"],["편성","현악 사중주나 목관 오중주 같은 편성은 역할 분담과 상호 조율 방식이 다르다"],["리더 없는 앙상블","눈 맞춤과 신체 신호로 소통한다고 알려져 있다"]]}],"ebs27ws_c07_5":[{"t":"tree","title":"아동의 탐구","root":"발달심리학","branches":[["연구 주제","아동이 어떤 상황에서 탐구를 시작하고 이어 가는지를 연구한다"],["호기심(curiosity)","정보의 격차(information gap)를 메우려는 동기라는 이론이 있다"],["탐구 기반 학습(inquiry-based learning)","아동의 호기심과 실험을 교육에 활용한다"]]}],"ebs27ws_c07_6":[{"t":"tree","title":"맥락과 해석","root":"화용론(pragmatics)","branches":[["정의","맥락 속에서 말의 의미를 연구하는 언어학 분야다"],["문장의 해석","발화 상황과 청자의 배경 지식과 관련된다"],["비판적 사고(critical thinking)","논증을 평가할 때 문장을 어떻게 읽는지는 기본 주제다"]]}],"ebs27ws_c08_1":[{"t":"def","term":"주의(attention)","text":"인지심리학에서 한정된 인지 자원을 선택적으로 할당하는 과정이다"},{"t":"cause","title":"터널 시야","causes":["스트레스나 위협 상황"],"result":"주의의 폭이 달라지는 터널 시야(tunnel vision) 현상이 보고된다","effects":["주의의 폭과 수행의 관계는 인지 연구의 주제다"]}],"ebs27ws_c08_2":[{"t":"tree","title":"슬픈 음악의 역설","root":"음악 심리학","branches":[["슬픈 음악의 역설(paradox of sad music)","연구 주제가 있다"],["아리스토텔레스(Aristotle)","비극이 카타르시스(catharsis)를 준다고 설명했다"],["감정 조절(mood regulation)","연구는 음악이 정서를 다루는 도구로 쓰이는지 살핀다"]]}],"ebs27ws_c08_3":[{"t":"tree","title":"진실과 글쓰기","root":"논픽션 글쓰기와 진실의 관계","branches":[["논쟁","오래된 논쟁거리다"],["포스트모더니즘(postmodernism)","서술의 객관성에 의문을 제기했다"],["대응 이론(correspondence theory)","진리를 현실과의 일치로 정의하는 입장이다"]]}],"ebs27ws_c08_4":[{"t":"tree","title":"과학적 합의 형성","root":"과학사회학","branches":[["과학적 합의(scientific consensus)","연구자 공동체 안에서 형성되는 다수의 견해를 가리킨다"],["쿤(Kuhn)","과학자 공동체가 패러다임을 공유한다고 설명했다"],["연구 대상","합의가 어떻게 만들어지고 이에 대한 비판이 어떻게 받아들여지는지도 과학사회학의 연구 대상이다"]]}],"ebs27ws_c08_5":[{"t":"flow","title":"과학적 방법","steps":["질문과 가설(hypothesis)을 세운다","실험이나 관찰로 검증한다"]},{"t":"tree","title":"과학의 구분 기준","root":"과학철학","branches":[["포퍼(Popper)","반증 가능성(falsifiability)을 과학의 구분 기준으로 제시했다"],["논쟁","과학이 이런 정형화된 방법으로만 설명되는지 논쟁이 있다"]]}],"ebs27ws_c08_6":[{"t":"tree","title":"신호 효과와 시장","root":"신호 이론(signaling)","branches":[["정의","경제학에서 정보가 비대칭일 때 한쪽이 자신의 특성을 알리는 행동을 하는 것이다"],["식당 사례","식당이 창가에 손님을 앉히는 것처럼 행동이 품질이나 인기의 신호로 작용한다"],["사회적 증거(social proof)","다른 사람의 행동을 따라 판단하는 심리 현상이다"]]}],"ebs27ws_c09_2":[{"t":"def","term":"접두사 self-","text":"언어학과 심리학에서 접두사 self-가 붙는 단어는 자존감(self-esteem), 자기 조절(self-control) 등 자기 개념을 나타낸다"},{"t":"vs","title":"자기관","cols":[{"name":"서양 개인주의 문화","items":["자기를 독립된 개체로 보는 경향과 연결된다고 논의된다"]},{"name":"동아시아 문화","items":["상호의존적 자기(interdependent self)가 강조되는 자기관이다"]}]}],"ebs27ws_c09_3":[{"t":"vs","title":"공동 창조","cols":[{"name":"공동 창조(co-creation)","items":["경영학에서 기업이 고객을 제품과 서비스 개발 과정에 참여시켜 함께 가치를 만드는 방식이다","소셜미디어는 고객과 기업의 양방향 소통을 가능하게 해 이런 협업을 쉽게 한다"]},{"name":"전통적 모델","items":["기업이 일방적으로 제품을 만든다"]}]}],"ebs27ws_c09_4":[{"t":"def","term":"선택적 주의(selective attention)","text":"많은 자극 중 일부에만 주의를 두는 인지 과정이다"},{"t":"cause","title":"무주의 맹시","causes":["한 과제에 집중한다"],"result":"눈앞의 뜻밖의 대상을 놓치는 무주의 맹시(inattentional blindness)","effects":["시몬스(Simons)와 차브리스(Chabris)의 보이지 않는 고릴라(invisible gorilla) 실험이 이를 보여 준다","이는 주의가 한정된 자원임을 뜻한다"]}],"ebs27ws_c09_6":[{"t":"tree","title":"철새의 이동","root":"철새의 이동(migration)","branches":[["정의","조류학에서 번식지와 월동지 사이를 오가는 계절적 이동이다"],["번식지 선택","철새가 어디에서 번식할지는 여러 환경 요인과 진화적 비용과 이득의 균형으로 설명된다"],["번식 성공","철새 연구에서 핵심 지표로 쓰인다"]]}],"ebs27ws_c10_2":[{"t":"vs","title":"호르메시스","cols":[{"name":"소량일 때","items":["독성 물질이나 스트레스가 오히려 유익한 반응을 일으킨다"]},{"name":"다량일 때","items":["해로운 현상이다"]}]},{"t":"tree","title":"용량-반응 곡선","root":"호르메시스(hormesis)","branches":[["곡선","용량-반응 곡선(dose-response curve)은 J자나 역U자 형태를 띨 수 있다"],["사례","운동, 간헐적 단식, 방사선 소량 노출 등이 사례로 연구된다"]]}],"ebs27ws_c10_3":[{"t":"tree","title":"결정론과 자유의지","root":"결정론(determinism)","branches":[["정의","모든 사건이 앞선 원인과 자연 법칙에 의해 필연적으로 정해진다는 철학적 입장이다"],["라플라스의 악마(Laplace's demon)","현재 상태를 모두 알면 미래를 완전히 예측할 수 있다는 사고 실험이다"],["자유의지(free will)","양자역학(quantum mechanics)의 비결정성과 자유의지 논쟁이 이어진다"]]}],"ebs27ws_c10_4":[{"t":"tree","title":"동물의 미래 계획","root":"비교인지학","branches":[["미래 예측 사고(prospection)","앞으로 일어날 일을 상상하고 대비하는 능력으로 인간 고유하다고 여겨졌다"],["연구 대상","까마귀과 새(corvids)와 유인원은 비교인지 연구에서 자주 쓰이는 동물이다"],["마음 시간 여행(mental time travel)","이는 마음 시간 여행 논쟁과 연결된다"]]}],"ebs27ws_c10_5":[{"t":"vs","title":"간헐적 강화","cols":[{"name":"간헐적 강화(intermittent reinforcement)","items":["행동주의 심리학에서 스키너(Skinner)가 연구한 보상 방식의 하나다","도박과 소셜미디어의 알림이 중독적인 이유로 자주 거론된다"]},{"name":"연속 강화(continuous reinforcement)","items":["간헐적 강화와 대비된다"]}]}],"ebs27ws_c10_6":[{"t":"tree","title":"도덕의 구속력","root":"도덕","branches":[["규범적 성격","윤리학에서 도덕은 해야 한다(ought)는 규범적 성격을 가진다"],["칸트(Kant)","정언명령(categorical imperative)으로 도덕이 조건 없이 구속한다고 보았다"],["심리학","도덕이 어떻게 형성되고 개인에게 내면화되는지를 다룬다"]]}],"ebs27ws_c11_1":[{"t":"flow","title":"낙엽의 노쇠 과정","steps":["식물 생리학에서 낙엽은 나무가 겨울을 나는 방식과 관련된 현상이다","이 과정을 노쇠(senescence)라 하며 호르몬이 조절한다","엽록소(chlorophyll)가 분해되면서 단풍 색이 드러난다"]}],"ebs27ws_c11_2":[{"t":"tree","title":"이상화 모델","root":"이상화(idealization)","branches":[["정의","과학철학에서 현실의 복잡한 요소를 다루기 쉽게 만드는 모형화 방식이다"],["구분","이 글은 이상화를 아리스토텔레스식과 갈릴레이식으로 나누는 논의를 다룬다"],["맥뮬린(McMullin)","이 구분은 맥뮬린 등이 정리한 것으로 알려져 있다"]]}],"ebs27ws_c11_3":[{"t":"tree","title":"인과와 법칙","root":"인과(causation)","branches":[["정의","철학에서 원인과 결과의 관계다"],["흄(Hume)","인과를 우리가 관찰하는 규칙적 연접(constant conjunction)으로 분석했다"],["논점","우연의 일치(coincidence)와 인과를 구별하는 기준이 논점이다"]]}],"ebs27ws_c11_4":[{"t":"tree","title":"일상 속 산술","root":"수학 교육","branches":[["산술(arithmetic)","사칙연산을 다루는 기본 영역이다"],["어림 계산(estimation)","정확한 값 대신 가까운 값을 구하는 방법이다"],["수 감각(number sense)","수량을 직관적으로 이해하는 능력이다"],["기술의 사용","계산기 같은 기술의 사용이 수학 학습에 미치는 영향은 교육 연구의 쟁점이다"]]}],"ebs27ws_c11_5":[{"t":"tree","title":"소크라테스의 무지","root":"플라톤의 대화편","branches":[["소크라테스적 무지(Socratic ignorance)","소크라테스(Socrates)는 자신이 아무것도 모른다고 말하는데, 이를 소크라테스적 무지라 한다"],["소크라테스식 아이러니(Socratic irony)","소크라테스의 대화 방식을 가리키는 말이다"],["논쟁","학자들은 이 말이 진심인지 전략인지를 논쟁해 왔다"]]}],"ebs27ws_c11_6":[{"t":"tree","title":"청소년기의 애착과 자율","root":"발달심리학","branches":[["애착(attachment)","볼비(Bowlby)가 제안한 양육자와의 정서적 유대 이론이다"],["청소년기","부모와의 관계에서 애착과 자율성(autonomy)의 새로운 균형을 찾는다"],["분리-개별화(separation-individuation)","이 과정을 설명하는 개념이다"]]}],"ebs27ws_c12_1":[{"t":"tree","title":"기술 변화와 노동","root":"기술 변화와 노동","branches":[["기술적 실업(technological unemployment)","경제학에서 기술 발전이 일자리를 줄이는 현상이다"],["러다이트 운동(Luddite movement)","19세기 영국에서 기계가 일자리를 빼앗는다고 본 노동자들의 저항이다"],["노동의 의미","사회학과 철학에서 논의된다"]]}],"ebs27ws_c12_2":[{"t":"tree","title":"인지과학과 통념","root":"인지과학","branches":[["연구","사고, 기억, 감정이 어떻게 작동하는지를 실험으로 연구한다"],["이중 과정 이론(dual-process theory)","카너먼(Kahneman)의 이론은 빠른 직관(System 1)과 느린 숙고(System 2)로 사고를 구분한다"],["전망과 회고","미래 예측과 과거 회상은 각각 전망(prospection)과 회고(retrospection)라 불린다"]]}],"ebs27ws_c12_3":[{"t":"def","term":"속어(slang)","text":"사회언어학에서 비공식적이고 집단 정체성을 드러내는 언어 표현이다"},{"t":"vs","title":"규범 문법과 기술 언어학","cols":[{"name":"규범 문법(prescriptivism)","items":["올바른 언어 사용을 규정한다"]},{"name":"기술 언어학(descriptivism)","items":["실제 사용을 관찰한다"]}]},{"t":"cause","title":"표현의 확산","causes":["인터넷"],"result":"새로운 표현의 확산 속도를 크게 높였다"}],"ebs27ws_c12_4":[{"t":"tree","title":"대화의 공유 맥락","root":"대화 분석","branches":[["공통 기반(common ground)","대화 참여자들이 공유한다고 가정하는 지식이다"],["플래널프(Planalp)","플래널프 등은 대화를 듣고 화자들의 관계를 판단하는 연구를 했다"],["화용론","대화에서 정보를 어떻게 다루는지는 화용론의 주제다"]]}],"ebs27ws_c12_5":[{"t":"vs","title":"프리모템과 사후 검토","cols":[{"name":"프리모템(premortem)","items":["게리 클라인(Gary Klein)이 제안한 기법으로, 프로젝트가 이미 실패했다고 가정하고 그 이유를 역으로 찾는 방법이다","프로젝트 계획과 의사결정 연구에서 거론된다"]},{"name":"사후 검토(postmortem)","items":["실패 뒤에 원인을 분석하는 것으로 프리모템과 대비된다"]}]}],"ebs27ws_c12_6":[{"t":"tree","title":"복제와 모방","root":"복제와 모방","branches":[["모방(imitation)","문화 진화론에서 문화가 전달되는 핵심 기제다"],["밈(meme)","도킨스(Dawkins)는 문화 복제자를 밈이라 불렀다"],["DNA 복제와 전사(transcription)","생물학에서도 생명의 기본 과정이다"]]}],"ebs27ws_c13_1":[{"t":"tree","title":"매끄러운 기술 설계","root":"인간-컴퓨터 상호작용","branches":[["이음매 없는 설계(seamless design)","기술 설계가 지향하는 방향의 하나로 논의된다"],["유비쿼터스 컴퓨팅(ubiquitous computing)","마크 와이저(Mark Weiser)는 컴퓨터가 어디에나 존재하는 환경을 구상했다"],["장점과 한계","이음매 없는 설계의 장점과 한계는 사용성 연구에서 논의된다"]]}],"ebs27ws_c13_2":[{"t":"tree","title":"매끄러운 기술 설계","root":"인간-컴퓨터 상호작용","branches":[["이음매 없는 설계(seamless design)","기술 설계가 지향하는 방향의 하나로 논의된다"],["유비쿼터스 컴퓨팅(ubiquitous computing)","마크 와이저(Mark Weiser)는 컴퓨터가 어디에나 존재하는 환경을 구상했다"],["장점과 한계","이음매 없는 설계의 장점과 한계는 사용성 연구에서 논의된다"]]}],"ebs27ws_c13_3":[{"t":"tree","title":"아동의 인식적 신뢰","root":"발달심리학","branches":[["인식적 신뢰(epistemic trust)","누구의 정보를 믿을지 판단하는 능력이다"],["아동","누구의 말을 믿는지는 발달심리학에서 실험으로 연구된다"],["정보원 평가","사람이 정보원을 평가하는 방식은 진화심리학에서도 다뤄진다"]]}],"ebs27ws_c13_4":[{"t":"tree","title":"아동의 인식적 신뢰","root":"발달심리학","branches":[["인식적 신뢰(epistemic trust)","누구의 정보를 믿을지 판단하는 능력이다"],["아동","누구의 말을 믿는지는 발달심리학에서 실험으로 연구된다"],["정보원 평가","사람이 정보원을 평가하는 방식은 진화심리학에서도 다뤄진다"]]}],"ebs27ws_s01_6":[{"t":"tree","title":"야생동물 관리","root":"야생동물 관리(wildlife management)","branches":[["분야","야생 개체군과 서식지를 다루는 분야다"],["대표적인 활동","사냥 허용량 설정과 개체수 조절 같은 활동이 대표적인 예로 알려져 있다"],["수용 능력(carrying capacity)","이 분야에서 쓰이는 기본 개념이다"]]}],"ebs27ws_s01_7":[{"t":"tree","title":"해마와 공간 기억","root":"해마(hippocampus)","branches":[["기능","신경과학에서 새로운 기억을 형성하고 공간 정보를 처리하는 뇌 부위다"],["오키프(O'Keefe)","해마의 장소 세포(place cell)를 발견해 노벨상을 받았다"],["환자 H.M.","해마가 기억 형성에 필수임을 보여 준 유명한 사례다"]]}],"ebs27ws_s01_12":[{"t":"vs","title":"실재론과 도구주의","cols":[{"name":"실재론(realism)","items":["과학철학에서 과학이 세계의 참모습을 보여 준다고 본다"]},{"name":"도구주의(instrumentalism)","items":["이론이 예측을 위한 도구일 뿐이라고 본다"]},{"name":"반실재론자","items":["과학 이론이 현실의 거울이 아니라 인간이 구성한 설명이라고 강조한다"]}]},{"t":"def","term":"가설과 이론","text":"관찰에 의해 시험되고 수정된다"}],"ebs27ws_s01_13":[{"t":"tree","title":"개인 활동 스타일","root":"개인의 활동 양식(individual style of activity)","branches":[["정의","심리학에서 과제를 수행할 때 보이는 비교적 안정적인 방식이다"],["관련 연구","인지 양식(cognitive style)과 학습 양식(learning style) 연구와 연결된다"],["스타일 형성","의식적 선택과 무의식적 습관이 모두 스타일 형성에 영향을 준다"]]}],"ebs27ws_s01_14":[{"t":"tree","title":"회의주의와 셰익스피어","root":"회의주의(skepticism)","branches":[["물음","철학에서 우리가 타인의 마음이나 외부 세계를 확실히 알 수 있는가를 묻는다"],["스탠리 카벨(Stanley Cavell)","셰익스피어 비극, 특히 『오셀로』에 회의주의 문제가 있다고 해석했다"],["타인의 마음에 대한 불확실성(other minds problem)","핵심 주제다"]]}],"ebs27ws_s01_15":[{"t":"tree","title":"놀이와 정서 조절","root":"놀이 이론","branches":[["놀이(play)","현실과 구별되는 안전한 틀 속에서 행동과 정서를 연습하게 하는 활동이다"],["놀이 싸움(play fighting)","공격적 감정을 가짜 맥락에서 다루게 하는 예로 자주 거론된다"],["놀이 모드(play mode)","놀이 모드로의 인지적 전환이 핵심이다"]]}],"ebs27ws_s01_16":[{"t":"tree","title":"생물다양성의 수준","root":"생물다양성(biodiversity)","branches":[["유전자"],["종"],["생태계"]]},{"t":"tree","title":"생물다양성 보전 단위","root":"보전 생물학","branches":[["보전의 기본 단위","무엇을 보전의 기본 단위로 삼을지가 논쟁거리다"],["진화적 의미 단위(evolutionarily significant unit)","이에 쓰이는 개념이다"]]}],"ebs27ws_s01_17":[{"t":"cause","title":"아동문학의 비대칭성","causes":["아동문학 연구에서 아동문학은 성인이 아동을 위해 쓰고 번역하고 출판하는 독특한 구조를 가진다"],"result":"교육적 의도와 아동의 취향 사이의 긴장을 낳기도 한다","effects":["아동문학 번역은 번역학에서 별도의 주제로 다뤄진다"]}],"ebs27ws_s01_18":[{"t":"tree","title":"소금의 역사","root":"소금","branches":[["교역과 권력","고대부터 교역과 권력의 중심에 있던 상품이다"],["salary(봉급)","영어 salary(봉급)가 라틴어 salarium(소금 수당 관련 말)에서 유래했다는 설이 있다"],["연구","식문화와 경제사 양쪽에서 자주 다뤄진다"]]}],"ebs27ws_s01_19":[{"t":"tree","title":"글쓰기와 생성형 AI","root":"글쓰기와 생성형 AI","branches":[["생성형 AI","대규모 언어 모델이 확률적으로 단어와 문장을 이어 붙여 글을 만들어 낸다"],["작문 연구(composition studies)","글쓰기를 가르치고 평가하는 방법을 다룬다"],["논의","AI 시대에 글쓰기의 기본이 무엇인지에 대한 논의가 있다"]]}],"ebs27ws_s01_20":[{"t":"tree","title":"지각과 무의식적 추론","root":"인지심리학","branches":[["리처드 그레고리(Richard Gregory)","지각을 가설 검증으로 보았고 이를 하향식 처리(top-down processing)로 설명했다"],["헬름홀츠(Helmholtz)의 무의식적 추론(unconscious inference)","감각 자료로부터 뇌가 무의식적으로 결론을 이끈다는 이론이다"],["착시(optical illusion)","이 과정의 오류로 해석된다"]]}],"ebs27ws_s01_22":[{"t":"tree","title":"프로폴리스와 꿀벌 건강","root":"꿀벌 건강","branches":[["프로폴리스(propolis)","꿀벌이 식물 수지를 모아 벌집에 바르는 물질로 항균 효과가 있다"],["사회성 면역(social immunity)","개체 대신 집단 차원에서 병원체를 막는 행동이다"],["미생물군(microbiome)","숙주의 건강에 영향을 주는 미생물 집합이다"]]}],"ebs27ws_s01_23":[{"t":"vs","title":"이론과 모형","cols":[{"name":"이론(theory)","items":["과학에서 현상을 설명하고 예측하는 체계적 설명이다"]},{"name":"모형(model)","items":["이를 단순화해 표현한 도구다","수학식, 도표, 물리적 모형 등으로 나타난다","보어(Bohr)의 원자 모형은 과학 교육에서 자주 쓰이는 예다"]}]}],"ebs27ws_s01_24":[{"t":"tree","title":"후광 효과와 위기 소통","root":"후광 효과와 위기 소통","branches":[["후광 효과(halo effect)","한 가지 긍정적 인상이 다른 속성의 평가까지 좋게 만드는 인지 편향이다"],["쿰스(Coombs)의 상황적 위기 소통 이론(SCCT)","위기 때 조직이 평판(reputation)을 어떻게 관리할지를 다룬다"],["홍보학","위기 대응에서 이해관계자와의 관계는 홍보학의 핵심 주제다"]]}],"ebs27ws_s01_25":[{"t":"tree","title":"후광 효과와 위기 소통","root":"후광 효과와 위기 소통","branches":[["후광 효과(halo effect)","한 가지 긍정적 인상이 다른 속성의 평가까지 좋게 만드는 인지 편향이다"],["쿰스(Coombs)의 상황적 위기 소통 이론(SCCT)","위기 때 조직이 평판(reputation)을 어떻게 관리할지를 다룬다"],["홍보학","위기 대응에서 이해관계자와의 관계는 홍보학의 핵심 주제다"]]}],"ebs27ws_s02_6":[{"t":"flow","title":"알고리즘 추천","steps":["추천 알고리즘(recommendation algorithm)은 이용자의 과거 행동 데이터로 선호를 확률적으로 예측한다","이 결과는 이용자를 특정 범주로 분류하고 맞춤 콘텐츠를 보여 줘 필터 버블(filter bubble)을 만들 수 있다"]},{"t":"def","term":"자동화 편향(automation bias)","text":"기계의 판단을 과신하는 경향이다"}],"ebs27ws_s02_12":[{"t":"tree","title":"음악과 언어의 공통점","root":"음악 인지(music cognition)","branches":[["공통점","음악과 언어가 소리의 패턴을 규칙에 따라 조직하고 의미와 감정을 전달한다는 공통점에 주목한다"],["통사(syntax)","둘 다 문법에 해당하는 구조인 통사를 가진다는 논의가 있다"],["차이","음악은 언어와 달리 구체적 지시 의미(reference)가 약하다는 차이도 지적된다"]]}],"ebs27ws_s02_13":[{"t":"tree","title":"윤리 이론","root":"윤리학(ethics)은 옳고 그름과 좋은 삶을 다루며 이론이 서로 다른 답을 제시한다","branches":[["의무론(deontology)"],["공리주의(utilitarianism)"],["덕 윤리(virtue ethics)"]]},{"t":"tree","title":"윤리의 복잡성","root":"윤리적 논쟁","branches":[["도덕적 딜레마(moral dilemma)","서로 충돌하는 의무 사이에서 선택해야 하는 상황이다"],["윤리적 논쟁","이 때문에 흔히 한쪽의 일방적 승리로 끝나지 않는다"]]}],"ebs27ws_s02_14":[{"t":"tree","title":"네 가지 기본 상호작용","root":"물리학에서 자연의 기본 상호작용","branches":[["중력"],["전자기력"],["약한 핵력"],["강한 핵력"]]},{"t":"tree","title":"고체와 전자 구름","root":"물질","branches":[["원자","원자핵과 전자로 이루어져 있다"],["고체 물리학(solid-state physics)","물질의 구조와 성질을 연구한다"]]}],"ebs27ws_s02_15":[{"t":"tree","title":"연구 질문과 지식의 종류","root":"연구 방법론","branches":[["연구 질문(research question)","탐구할 문제를 구체화한 것이다"],["양적 연구(quantitative research)와 질적 연구(qualitative research)","대표적인 접근이다"],["인식론(epistemology)","지식이 어떤 방식으로 얻어지는가를 묻는 철학이다"]]}],"ebs27ws_s02_17":[{"t":"tree","title":"기후와 날씨","root":"기후와 날씨","branches":[["기후(climate)와 날씨(weather)","시간 규모가 다른 개념으로 구분된다"],["기후 연구","대기, 해양, 육지 같은 여러 요소를 함께 다룬다"],["고기후학(paleoclimatology)","지질학적 시간에서 기후가 어떻게 달라져 왔는지가 주제다"]]}],"ebs27ws_s02_19":[{"t":"vs","title":"효율적 시장 가설","cols":[{"name":"효율적 시장 가설(Efficient Markets Hypothesis)","items":["유진 파마(Eugene Fama)가 정리한 이론으로, 자산 가격이 이용 가능한 모든 정보를 이미 반영한다고 본다"]},{"name":"행동경제학","items":["투자자의 비합리성 때문에 가격이 정보에서 벗어날 수 있다고 비판한다"]}]}],"ebs27ws_s02_21":[{"t":"vs","title":"인사 관리","cols":[{"name":"전통적 인사 관리(personnel management)","items":["행정 중심이었다"]},{"name":"전략적 인적자원관리(SHRM)","items":["인사 관리를 조직 전략과 관련지어 다루는 접근이다","전략적 파트너 역할을 강조한다"]}]},{"t":"def","term":"경영 전략의 기본 요소","text":"조직의 비전(vision)과 사명(mission), 목표"}],"ebs27ws_s02_22":[{"t":"tree","title":"사물의 행위성","root":"과학기술학(STS)","branches":[["행위자-네트워크 이론(ANT)","라투르(Latour) 등이 제안한 이론으로 사물도 사회에 영향을 주는 행위자(actant)라고 본다"],["인공물(artifact)","중립적 도구가 아니라 사용 방식과 가치를 형성하는 힘을 가진다"],["예","속도 방지턱처럼 사물이 행동을 유도하는 예가 자주 제시된다"]]}],"ebs27ws_s02_23":[{"t":"flow","title":"말 길들이기와 문명","steps":["고고학에서 말의 가축화(domestication)는 기원전 3천 년대 유라시아 초원(steppe)에서 시작된 것으로 추정된다","승마와 전차는 이동, 전쟁, 교역 방식을 크게 바꾸었다"]}],"ebs27ws_s02_24":[{"t":"vs","title":"의례와 도구적 행위","cols":[{"name":"의례(ritual)","items":["인류학에서 상징적 의미를 가진 정형화된 행위다","소속감과 불안 완화에 기능한다고 연구된다"]},{"name":"도구적 행위(instrumental action)","items":["실용적 목적이 뚜렷한 행위다"]}]},{"t":"def","term":"일상 속 행위의 해석","text":"일상 속 행위를 어떻게 해석할지는 인류학의 방법론적 쟁점이다"}],"ebs27ws_s02_25":[{"t":"vs","title":"의례와 도구적 행위","cols":[{"name":"의례(ritual)","items":["인류학에서 상징적 의미를 가진 정형화된 행위다","소속감과 불안 완화에 기능한다고 연구된다"]},{"name":"도구적 행위(instrumental action)","items":["실용적 목적이 뚜렷한 행위다"]}]},{"t":"def","term":"일상 속 행위의 해석","text":"일상 속 행위를 어떻게 해석할지는 인류학의 방법론적 쟁점이다"}],"ebs27ws_s03_7":[{"t":"tree","title":"부정 편향","root":"부정 편향(negativity bias)","branches":[["정의","심리학에서 같은 강도라도 부정적 정보와 감정에 더 크게 반응하는 경향이다"],["로진(Rozin)과 로이스먼(Royzman)","이를 체계적으로 정리했다"],["기원과 기능","이 경향의 기원과 기능은 진화심리학에서 논의된다"]]}],"ebs27ws_s03_12":[{"t":"vs","title":"허구와 거짓말","cols":[{"name":"허구(fiction)","items":["문학 이론에서 독자가 진짜라고 믿도록 요구하지 않는 서사다","콜리지(Coleridge)의 불신의 자발적 유예(willing suspension of disbelief)는 독자가 허구를 받아들이는 태도를 설명한다"]},{"name":"거짓말(lie)","items":["속일 의도를 가진 진술이라는 점에서 구별된다"]}]}],"ebs27ws_s03_13":[{"t":"tree","title":"숙련과 연습","root":"숙련 연구","branches":[["의도적 연습(deliberate practice)","에릭슨(Ericsson)은 의도적 연습이 전문성 개발의 핵심이라고 주장했다"],["연습","즐거움이 아니라 약점 보완을 목표로 한 구조화된 노력이다"],["놀이(play)와 일(work)","구분은 활동의 목적과 구조에 따라 논의된다"]]}],"ebs27ws_s03_14":[{"t":"tree","title":"자연과 문화의 연결","root":"인류학과 인지과학","branches":[["적응","인간의 적응을 설명할 때 개인의 두뇌와 사회 환경의 역할을 함께 논의한다"],["확장된 마음(extended mind)","인지가 뇌 밖의 도구와 환경으로 확장된다고 주장한다"],["유전자-문화 공진화(gene-culture coevolution)","문화가 유전적 진화에 영향을 준다는 개념이다"]]}],"ebs27ws_s03_15":[{"t":"tree","title":"동물의 사회 인지","root":"동물 사회 인지","branches":[["체니(Cheney)와 세이파스(Seyfarth)","비비(baboon)의 사회생활을 현장 실험으로 연구한 대표적인 영장류 학자다"],["재생 실험","녹음된 소리를 들려주고 동물의 반응을 관찰하는 방법이다"],["동물 사회 인지(social cognition)","이는 동물 사회 인지 연구와 마음 이론(theory of mind) 논쟁으로 이어진다"]]}],"ebs27ws_s03_16":[{"t":"tree","title":"지능의 문화적 상대성","root":"문화심리학","branches":[["지능(intelligence)","정의와 측정 방식은 논쟁거리다"],["가드너(Gardner)의 다중지능 이론(multiple intelligences)","지능이 여러 영역으로 구성된다고 주장했다"],["이누이트","이누이트의 공간 항법 능력은 문화인류학 연구에서 자주 언급된다"]]}],"ebs27ws_s03_17":[{"t":"tree","title":"실험 철학과 쾌락","root":"로버트 보일(Robert Boyle)","branches":[["실험 철학(experimental philosophy)","과학혁명기의 보일은 실험을 통한 지식 탐구를 중시한 실험 철학의 선구자다"],["호기심과 발견의 즐거움","그는 호기심과 발견의 즐거움을 이야기한 과학자로 알려져 있다"],["보일의 법칙","기체의 압력과 부피의 관계를 밝힌 보일의 법칙으로도 유명하다"]]}],"ebs27ws_s03_18":[{"t":"tree","title":"과학 같은 언어의 마케팅","root":"마케팅","branches":[["광고 문구","마케팅에서는 과학 용어가 광고 문구에 쓰이는 경우가 많다"],["권위 편향(authority bias)","권위 있어 보이는 출처를 더 신뢰하는 경향이다"],["소비자 과학 문해력(scientific literacy)","이런 문구를 평가하는 능력과 관련된다"]]}],"ebs27ws_s03_19":[{"t":"flow","title":"생태계의 에너지","steps":["생태학에서 거의 모든 에너지는 태양에서 온다","생산자(producer)가 광합성으로 이를 고정한다","생물이 에너지를 얻는 방식은 생활 방식에 따라 다르다"]},{"t":"def","term":"화석 연료","text":"오래전 생물체에서 만들어진 에너지원이며, 경제사에서는 에너지원이 산업 발달과 어떻게 연결되는지 논의한다"}],"ebs27ws_s03_20":[{"t":"tree","title":"선천적 편향과 노력","root":"심리학","branches":[["인지 편향(cognitive bias)","인간에게 보편적으로 나타난다고 밝혀 왔다"],["선천적(innate)인 성향과 학습, 환경","관계는 심리학의 오랜 쟁점이다"],["숙명론(fatalism)","모든 일이 정해져 있다고 보는 입장이다"]]}],"ebs27ws_s03_22":[{"t":"vs","title":"공간과 장소","cols":[{"name":"공간(space)","items":["인문지리학자 이푸 투안(Yi-Fu Tuan)은 『공간과 장소』에서 공간을 열린 추상적 영역으로 구분했다"]},{"name":"장소(place)","items":["경험과 애착이 쌓인 의미 있는 곳으로 구분했다"]}]},{"t":"def","term":"장소감(sense of place)","text":"인간이 특정 장소에 갖는 정서적 유대를 가리킨다 · 이 구분은 인문지리학의 핵심 개념이다"}],"ebs27ws_s03_23":[{"t":"flow","title":"근대적 정체성","steps":["사회학에서 근대 이전에는 신분, 종교, 직업 같은 집단 소속이 정체성의 바탕이었다","18세기 이후 개인주의(individualism)가 확산되며 개인이 자기 정체성을 스스로 형성한다는 인식이 커졌다","기든스(Giddens)는 후기 근대에 정체성이 성찰적 기획(reflexive project)이 되었다고 보았다"]}],"ebs27ws_s03_24":[{"t":"tree","title":"선악과 인간","root":"윤리학","branches":[["자연주의(naturalism)","도덕이 인간의 본성과 생명 형태에 근거한다고 본다"],["덕 윤리(virtue ethics)","아리스토텔레스(Aristotle)의 덕 윤리는 인간의 번영(eudaimonia)에서 선을 설명한다"],["비교 윤리학","동물의 이타 행동과 도덕성의 관계는 비교 윤리학의 주제다"]]}],"ebs27ws_s03_25":[{"t":"tree","title":"선악과 인간","root":"윤리학","branches":[["자연주의(naturalism)","도덕이 인간의 본성과 생명 형태에 근거한다고 본다"],["덕 윤리(virtue ethics)","아리스토텔레스(Aristotle)의 덕 윤리는 인간의 번영(eudaimonia)에서 선을 설명한다"],["비교 윤리학","동물의 이타 행동과 도덕성의 관계는 비교 윤리학의 주제다"]]}],"ebs27ws_s04_3":[{"t":"tree","title":"디지털 데이터와 선택권","root":"교육 데이터 활용(learning analytics)","branches":[["정의","학생 데이터를 분석해 교육을 개선하려는 분야다"],["쟁점","개인정보 보호(privacy)와 정보 주체의 동의(consent) 문제가 쟁점이다"],["장단점","교육 데이터 활용의 장단점은 교육공학에서 논의된다"]]}],"ebs27ws_s04_4":[{"t":"tree","title":"고층 건물의 설계 문제","root":"고층 건물(high-rise)","branches":[["스카이라인(skyline)","건축에서 스카이라인을 형성하며 구조, 풍하중, 도시 경관 등 여러 문제를 낳는다"],["상부와 하부 처리","건물의 상부와 하부 처리는 건축 형태와 도시 맥락의 조화 문제다"],["루이스 설리번(Louis Sullivan)","형태는 기능을 따른다(form follows function)는 고층 건물 미학의 유명한 원칙이다"]]}],"ebs27ws_s04_5":[{"t":"tree","title":"경험의 소멸","root":"자연 접촉","branches":[["경험의 소멸(extinction of experience)","자연과의 직접 접촉이 줄어드는 현상으로 로버트 마이클 파일(Robert Michael Pyle)이 제안한 개념이다"],["자연 결핍 장애(nature-deficit disorder)","리처드 루브(Richard Louv)가 도시 아동의 자연 접촉 감소를 지적하며 쓴 말이다"],["환경교육","자연 경험과 환경 태도의 관계는 환경교육의 주제다"]]}],"ebs27ws_s04_6":[{"t":"tree","title":"코미디 영화와 사회","root":"영화학","branches":[["코미디(comedy)","대중성과 오락성이 높은 장르다"],["사회","코미디가 사회를 어떻게 다루는지는 영화학의 주요 논쟁 주제다"],["학자","크리스토퍼 비치(Christopher Beach)와 프랭크 크루트닉(Frank Krutnik)은 코미디 영화를 연구한 학자다"]]}],"ebs27ws_s04_7":[{"t":"tree","title":"멸종 위기종의 상품화","root":"환경사회학","branches":[["상품화(commodification)","자연과 동물이 소비재와 이미지로 소비되는 현상이다"],["멸종 위기종","보전 운동의 상징으로 쓰이며 다양한 상품에 등장한다"],["연구 주제","보전 운동에서 어떤 종이 상징으로 선택되는지는 환경사회학의 연구 주제다"]]}],"ebs27ws_s04_12":[{"t":"vs","title":"자기 연민","cols":[{"name":"자기 연민(self-compassion)","items":["크리스틴 네프(Kristin Neff)가 정립한 개념으로, 실패했을 때 자신을 비난하지 않고 친절하게 대하는 태도다"]},{"name":"구별되는 개념","items":["자기애(narcissism)","자기 연민에 빠지는 것(self-pity)"]}]},{"t":"tree","title":"자기 연민의 요소","root":"자기 연민","branches":[["자기 친절"],["보편적 인간성 인식"],["마음챙김"]]}],"ebs27ws_s04_14":[{"t":"tree","title":"리얼리티 TV","root":"리얼리티 TV(reality TV)","branches":[["정의","미디어 연구에서 실제 사람들의 삶을 연출과 편집을 거쳐 오락으로 보여 주는 장르다"],["시청 동기","관음증(voyeurism)과 사회적 비교(social comparison)가 시청 동기로 거론된다"],["수용자 연구","시청자가 이 장르를 어떻게 받아들이는지는 수용자 연구에서 다뤄진다"]]}],"ebs27ws_s04_15":[{"t":"tree","title":"다양성의 이점","root":"다양성","branches":[["음의 빈도 의존 선택(negative frequency-dependent selection)","진화생물학에서 흔한 형질일수록 적합도가 낮아져 다양성이 유지되는 현상이다"],["경제학","산업의 여러 부문이 서로 맞물려 작동하는 방식을 다룬다"],["생태학","종 다양성과 생산성의 관계가 연구된다"]]}],"ebs27ws_s04_16":[{"t":"tree","title":"동물의 모방 검사","root":"모방(imitation)","branches":[["정의","비교심리학에서 행동의 방식을 관찰해 그대로 따라 하는 학습이다"],["따라 하기 검사(do-as-I-do test)","훈련사가 새로운 행동을 보이면 동물이 따라 하는지 확인하는 방법이다"],["구별","모방은 에뮬레이션(emulation), 자극 강화(stimulus enhancement)와 구별된다"]]}],"ebs27ws_s04_17":[{"t":"tree","title":"시의 특수성","root":"문학 이론","branches":[["시(poem)","일상 언어와 다른 특성을 가진 장르로 논의된다"],["신비평(New Criticism)","텍스트 자체를 꼼꼼히 읽는 비평 방법을 내세웠다"],["시 번역","시 번역의 어려움은 번역학의 오랜 주제다"]]}],"ebs27ws_s04_18":[{"t":"tree","title":"테니스와 생체역학","root":"생체역학(biomechanics)","branches":[["정의","몸의 움직임을 역학적으로 분석하는 학문이다"],["지각-운동 협응(perception-action coupling)","스포츠 과학에서는 선수의 지각과 동작의 관계를 이렇게 설명한다"],["예측(anticipation)","반응 시간이 매우 짧은 종목에서는 예측이 중요하다"]]}],"ebs27ws_s04_19":[{"t":"tree","title":"초가공식품","root":"초가공식품(ultra-processed food)","branches":[["노바(NOVA) 분류","산업적으로 가공된 첨가물과 성분으로 만든 식품을 가리킨다"],["만성 질환","비만, 당뇨 등 만성 질환과의 연관성이 연구되고 있다"],["식품 환경(food environment)과 소득 수준","식습관에 영향을 준다고 논의된다"]]}],"ebs27ws_s04_20":[{"t":"tree","title":"식물의 일주 온도 반응","root":"식물 생리학","branches":[["일주기 리듬(circadian rhythm)","하루 주기의 생체 시계다"],["온도 차 감지","식물은 낮과 밤의 온도 차를 감지해 생장과 대사를 조절한다"],["DIF(day-night temperature difference)","연구는 낮밤 온도 차가 줄기 신장에 영향을 준다고 밝혔다"]]}],"ebs27ws_s04_21":[{"t":"tree","title":"웃음과 조롱","root":"웃음과 조롱의 어원","branches":[["우월 이론(superiority theory)","유머 이론에서 웃음이 타인의 약점을 비웃으며 얻는 우월감에서 나온다고 설명한다"],["조롱(ridicule)","유럽의 사교와 논쟁 문화에서 오래 논의된 개념이다"],["어원(etymology)","단어의 역사적 변화와 뜻을 연구하는 분야다"]]}],"ebs27ws_s04_22":[{"t":"tree","title":"가리키기와 인류의 진화","root":"비교 인지과학","branches":[["지시 행동(pointing)","타인의 주의를 대상으로 이끄는 의사소통이다"],["인간 유아","12개월경 가리키기를 하며 이는 공유 주의(joint attention)의 중요한 단서다"],["비교 연구","개와 유인원의 이해 능력을 비교하는 연구가 많다"]]}],"ebs27ws_s04_23":[{"t":"tree","title":"미디어 등식","root":"미디어 등식(Media Equation)","branches":[["정의","리브스(Reeves)와 내스(Nass)가 제안한 이론으로, 사람과 미디어의 관계를 다룬다"],["사회적 행위자로서의 로봇(social robot)","연구와 연결된다"],["인간-로봇 상호작용(human-robot interaction)","로봇공학과 심리학이 만나는 분야다"]]}],"ebs27ws_s05_4":[{"t":"tree","title":"AI 과장과 허위 정보","root":"AI 과장과 허위 정보","branches":[["AI 겨울(AI winter)","AI 연구사에는 기대와 실망이 반복된 AI 겨울이 있었다"],["AI 허풍(AI hype)","기술 능력을 과장해 투자와 관심을 끄는 현상이다"],["미디어 문해력(media literacy)","과장된 주장과 허위 정보를 구별하는 능력이다"]]}],"ebs27ws_s05_5":[{"t":"tree","title":"표본의 대표성과 WEIRD","root":"심리학 연구 표본","branches":[["표본의 구성","심리학 연구 표본의 구성은 방법론에서 중요한 문제다"],["WEIRD","Western, Educated, Industrialized, Rich, Democratic의 머리글자로, 헨릭(Henrich) 등이 2010년 논문에서 사용한 표현이다"],["일반화(generalization)","표본과 모집단의 관계는 일반화와 관련된다"]]}],"ebs27ws_s05_7":[{"t":"tree","title":"오디오북과 독서","root":"독서 연구","branches":[["오디오북(audiobook)","읽기와 같은 이해 수준을 제공하는지는 논쟁 주제다"],["연구 보고","일부 연구는 청취와 독서가 이해도에서 비슷하다고 보고하지만 주의 집중과 몰입 방식은 다르다고 지적한다"],["책 문화(book culture)","매체 변화에 어떻게 적응하는지도 함께 논의된다"]]}],"ebs27ws_s05_12":[{"t":"tree","title":"기억의 왜곡","root":"인지심리학","branches":[["기억의 정확성","오래된 연구 주제다"],["대표 연구","바틀릿(Bartlett)의 스키마(schema) 연구와 로프터스(Loftus)의 오정보 효과(misinformation effect)가 대표적이다"],["목격 증언","신뢰성은 법심리학에서도 다뤄진다"]]}],"ebs27ws_s05_13":[{"t":"vs","title":"선물 경제와 시장 경제","cols":[{"name":"선물 경제","items":["인류학에서 마르셀 모스(Marcel Mauss)의 『증여론』은 선물 교환의 사회적 의미를 분석했다","포틀래치(potlatch)는 북서부 아메리카 원주민의 선물 잔치 풍습이다"]},{"name":"시장 경제","items":["선물 경제와 대비되는 개념이다"]}]}],"ebs27ws_s05_14":[{"t":"tree","title":"마음 속의 생각","root":"데카르트(Descartes)","branches":[["이원론(dualism)","철학에서 마음과 몸을 구분했다"],["이성","의심하는 자신의 존재에서 출발하는 철학으로 유명하며 이성을 인간의 핵심 속성으로 보았다"],["쟁점","이성과 인간 본성의 관계는 철학의 오랜 쟁점이다"]]}],"ebs27ws_s05_15":[{"t":"tree","title":"우주 관광","root":"우주 관광(space tourism)","branches":[["정의","민간인이 상업적으로 우주를 여행하는 산업이다"],["데니스 티토(Dennis Tito)","2001년 최초의 우주 관광객으로 알려져 있고 이후 민간 기업이 준궤도 비행을 상용화하고 있다"],["쟁점","우주 관광에 관해서는 여러 쟁점이 연구되고 있다"]]}],"ebs27ws_s05_16":[{"t":"tree","title":"인공지능과 데이터","root":"인공지능","branches":[["기계 학습(machine learning)","인공지능과 기계 학습은 통계적 패턴 인식으로 작동하며 인간의 이해와 같지 않다"],["환각(hallucination)","생성형 AI가 사실이 아닌 내용을 만드는 현상이다"],["AI의 객관성","기술철학에서 논의가 이어진다"]]}],"ebs27ws_s05_17":[{"t":"tree","title":"기술의 확산","root":"기술사","branches":[["범용 기술(general-purpose technology)","전기와 증기기관처럼 경제 전반을 바꾸는 기술이다"],["기술 확산(diffusion)","새로운 기술이 사회에 퍼지는 과정은 기술 확산 연구의 주제다"],["자동차","20세기 사회와 도시를 바꾼 대표적 기술로 꼽힌다"]]}],"ebs27ws_s05_18":[{"t":"tree","title":"미생물군과 현대 생활","root":"미생물군(microbiome)","branches":[["정의","몸에 사는 미생물의 집합으로 소화, 면역, 건강에 영향을 준다"],["연구","생활 방식과 식습관, 약물 사용이 미생물군과 어떤 관계가 있는지 연구된다"],["불균형(dysbiosis)","미생물 군집이 교란된 상태를 불균형이라 한다"]]}],"ebs27ws_s05_19":[{"t":"tree","title":"불의 사용","root":"불(fire)의 통제","branches":[["의의","인류 진화에서 요리, 난방, 포식자 방어를 가능하게 한 중요한 사건이다"],["요리 가설(cooking hypothesis)","랭엄(Wrangham)의 가설은 요리가 소화 부담을 줄여 뇌 발달을 도왔다고 주장한다"],["시기","불을 의도적으로 피운 시기는 아직 확실하지 않다"]]}],"ebs27ws_s05_20":[{"t":"tree","title":"인공지능과 통치","root":"알고리즘 통치(algorithmic governance)","branches":[["정의","정치학에서 데이터와 알고리즘으로 정책 결정을 자동화하는 방식이다"],["문제","효율성이 높아질 수 있지만 책임 소재(accountability)와 투명성(transparency), 민주적 통제 문제가 제기된다"],["인간 개입(human-in-the-loop)","자동화 결정에 사람이 관여하는 원칙이다"]]}],"ebs27ws_s05_21":[{"t":"tree","title":"음악 연주와 진정성","root":"음악학","branches":[["역사적 정보에 입각한 연주(historically informed performance)","작곡 당시의 악기와 연주법을 재현하려는 운동이다"],["진정성(authenticity)","작곡가의 의도에 충실한 연주를 의미하지만 이 개념 자체가 논쟁거리다"],["악보 해석(interpretation)","연주자의 창의성도 포함한다는 반론이 있다"]]}],"ebs27ws_s05_22":[{"t":"tree","title":"시간 지연과 상대성","root":"상대성 이론","branches":[["아인슈타인(Einstein)","상대성 이론은 시간과 공간에 대한 고전적 관념을 바꾸었다"],["시간 지연(time dilation)","상대성 이론에서 예측되는 현상이다"],["시간","절대적이지 않고 관찰자의 운동 상태와 관련된다"]]}],"ebs27ws_s05_23":[{"t":"tree","title":"로크의 재산권","root":"존 로크(John Locke)","branches":[["『통치론』","정치철학에서 자연 상태(state of nature)와 재산권의 문제를 다뤘다"],["사유 재산","로크는 사유 재산이 어떻게 정당화되는지를 설명한 철학자로 알려져 있다"],["단서(proviso)","로크의 재산권 이론에서 조건으로 붙는 제한이다"]]}],"ebs27ws_s05_24":[{"t":"tree","title":"제도의 경직성","root":"제도경제학과 사회과학","branches":[["제도(institution)","사회의 규칙과 규범 체계다"],["경로 의존성(path dependence)","과거 선택이 현재의 선택지를 제약해 제도가 쉽게 바뀌지 않는 현상이다"],["끈적함(stickiness)","전환 비용과 기득권 저항이 제도의 끈적함을 만든다"]]}],"ebs27ws_s05_25":[{"t":"tree","title":"제도의 경직성","root":"제도경제학과 사회과학","branches":[["제도(institution)","사회의 규칙과 규범 체계다"],["경로 의존성(path dependence)","과거 선택이 현재의 선택지를 제약해 제도가 쉽게 바뀌지 않는 현상이다"],["끈적함(stickiness)","전환 비용과 기득권 저항이 제도의 끈적함을 만든다"]]}],"ee78a1c586eb8b1e_20":[{"t":"tree","title":"조직 문화의 층위","root":"에드거 샤인(Edgar Schein)은 조직 문화를 세 층위로 설명했다","branches":[["인공물(artifacts)","눈에 보이는 층위"],["표방하는 가치(espoused values)"],["무의식적인 기본 가정(basic underlying assumptions)"]]},{"t":"cause","title":"문화로 자리 잡는 과정","causes":["가치가 행동으로 이어지고 반복되어 습관화되어야 문화로 자리 잡는다고 본다"],"result":"이는 빙산 모형으로 흔히 비유된다"}],"ee78a1c586eb8b1e_21":[{"t":"tree","title":"주의와 스트레스","root":"심리학","branches":[["반추(rumination)","같은 걱정을 반복해 곱씹는 사고로 스트레스를 오래 끈다"],["주의 협소화(attentional narrowing)","주의가 한 가지 위협에 고정되는 주의 협소화는 시야를 좁힌다"],["마음챙김(mindfulness)","존 카밧진(Jon Kabat-Zinn)의 마음챙김은 판단 없이 현재에 주의를 두는 훈련으로 스트레스 감소에 쓰인다"]]}],"ee78a1c586eb8b1e_23":[{"t":"tree","title":"자연 자원과 시장 유인","root":"환경경제학","branches":[["외부효과(externality)","시장 가격에 반영되지 않는 환경 비용이다"],["생태계 서비스 지불제(payment for ecosystem services, PES)","시장 유인이 숲 벌채처럼 개발에 유리하게 작동하는 문제를 해결하려는 제도다"],["탄소 격리(carbon sequestration)","숲이 이산화탄소를 저장하는 기능이다"]]}],"ee78a1c586eb8b1e_24":[{"t":"tree","title":"과잉 관광과 장소 개념","root":"관광과 장소","branches":[["과잉 관광(overtourism)","방문객이 너무 많아 주민 삶과 환경이 악화되는 현상으로 수용력(carrying capacity) 개념과 관련된다"],["도린 매시(Doreen Massey)","장소를 고정된 경계가 아니라 관계 속에서 열려 있는 것으로 보았다"],["이동성 연구(mobilities)","관광객과 주민을 뚜렷이 나누는 이분법(binary)을 비판한다"]]}],"ee78a1c586eb8b1e_29":[{"t":"tree","title":"사회적 자극에 대한 선천적 성향","root":"발달심리학","branches":[["신생아","신생아가 얼굴 비슷한 모양을 선호한다는 연구(Johnson & Morton, 1991)가 있다"],["선호 응시법(preferential looking)","영아가 어떤 자극을 더 오래 보는지로 선호를 측정한다"],["사회 인지(social cognition)와 공동 주의(joint attention)","타인과 주의를 공유하는 능력으로 발달 초기에 나타난다"]]}],"ee78a1c586eb8b1e_30":[{"t":"tree","title":"바자르 경제","root":"바자르 경제","branches":[["클리퍼드 기어츠(Clifford Geertz)","인류학자로 1978년 논문 「바자르 경제」에서 시장 상인과 손님이 정보를 찾는 데 많은 비용을 쓰고 가격 흥정이 고정 관계에 기대어 이루어진다고 분석했다"],["사회적 착근성(social embeddedness)","마크 그래노베터(Mark Granovetter)의 개념으로 경제 행위가 사회 관계 속에 놓여 있다는 개념이다"],["흥정(haggling)","대표적 예다"]]}],"ee78a1c586eb8b1e_31":[{"t":"tree","title":"다중 양식 문해력","root":"문해력 연구","branches":[["새로운 문해 연구(New Literacy Studies)","읽기를 글자 해독을 넘어 사회적 실천으로 본다"],["다중 양식(multimodality)","군터 크레스와 테오 판 레이우언(Kress & van Leeuwen)의 이론은 글, 이미지, 소리가 함께 의미를 만든다고 설명한다"],["기호학(semiotics)","텍스트를 넓은 의미의 기호로 해석한다"]]}],"ee78a1c586eb8b1e_32":[{"t":"vs","title":"영화 속 소리","cols":[{"name":"극중 소리(diegetic sound)","items":["영화 음악 연구에서 극 중 인물이 들을 수 있는 소리를 극중 소리라 한다"]},{"name":"극 밖 소리(non-diegetic sound)","items":["관객만 듣는 배경 음악을 극 밖 소리라 한다"]}]},{"t":"tree","title":"영화 음악의 기능","root":"영화 음악","branches":[["클라우디아 고브만(Claudia Gorbman)","『들리지 않는 선율』(1987)은 영화 음악의 기능을 분석했다"],["라이트모티프(leitmotif)","바그너(Wagner)의 라이트모티프는 인물, 주제에 연결된 반복 선율이다"]]}],"ee78a1c586eb8b1e_33":[{"t":"tree","title":"표정과 감정 인식","root":"표정과 감정 인식","branches":[["폴 에크만(Paul Ekman)","심리학자로 얼굴 표정으로 기본 감정을 인식할 수 있다고 주장했지만, 맥락에 따라 해석이 달라진다는 반론이 있다"],["샤를 르브룅(Charles Le Brun)","17세기 프랑스 화가로 감정별 얼굴 표현을 체계화했다"],["쿨레쇼프 효과(Kuleshov effect)","같은 표정도 앞뒤 장면에 따라 다르게 보이는 현상이다"]]}],"ee78a1c586eb8b1e_34":[{"t":"tree","title":"거리와 교통 설계","root":"도시계획","branches":[["완전 도로(complete streets)","거리(street)를 자동차 통행만이 아니라 보행, 자전거, 대중교통이 함께 쓰는 공공 공간으로 보는 개념이다"],["도로 다이어트(road diet)","차로를 줄여 보행, 자전거 공간을 늘리는 방식이다"],["교통수단 분담률(mode share)","이용자의 선택을 보여 준다"]]}],"ee78a1c586eb8b1e_36":[{"t":"tree","title":"협상의 기본 개념","root":"협상학","branches":[["BATNA(Best Alternative To a Negotiated Agreement)","협상이 결렬될 때의 최선의 대안으로 피셔와 유리(Fisher & Ury)가 제시했다"],["ZOPA(Zone of Possible Agreement)","합의 가능 영역을 뜻하며 BATNA와 함께 협상력을 설명한다"],["윈윈(win-win)","양측이 모두 이득을 보는 결과다"]]}],"ee78a1c586eb8b1e_37":[{"t":"tree","title":"집단 규범과 동조","root":"집단 규범과 동조","branches":[["무자페르 셰리프(Muzafer Sherif)","자동운동 효과 실험(1936)은 집단 안에서 판단 기준이 수렴함을 보여 주었다"],["솔로몬 애쉬(Solomon Asch)","동조 실험(1951)은 다수 의견에 따르는 압력을 보여 주었다"]]},{"t":"vs","title":"치알디니의 규범 구분","cols":[{"name":"기술적 규범(descriptive norm)","items":["사람들이 실제로 하는 행동"]},{"name":"명령적 규범(injunctive norm)","items":["해야 하는 행동"]}]}],"ee78a1c586eb8b1e_38":[{"t":"tree","title":"과학의 우선권 경쟁","root":"과학사회학","branches":[["우선권(priority)","로버트 머튼(Robert Merton)은 과학자들이 발견의 우선권을 두고 경쟁한다고 분석했다"],["뉴턴과 라이프니츠","미적분 논쟁이 대표적이다"],["마태 효과(Matthew effect, 1968)","머튼의 마태 효과는 이미 유명한 연구자가 더 많은 공로를 인정받는 현상이다"],["동시 발견(multiple discoveries)","서로 독립적으로 같은 발견이 이루어지는 경우다"]]}],"ee78a1c586eb8b1e_39":[{"t":"flow","title":"돌연변이","steps":["분자생물학에서 돌연변이(mutation)는 DNA 복제 오류 등으로 염기 서열이 바뀌는 현상이다","대부분은 해롭거나 중립적이지만 드물게 유리한 변이가 생겨 진화의 원료인 변이(variation)가 된다"]},{"t":"def","term":"비유","text":"이는 책의 오타가 의미를 해치는 것과 자주 비유된다"}],"ee78a1c586eb8b1e_40":[{"t":"flow","title":"전문화","steps":["학문 역사에서는 르네상스의 레오나르도 다 빈치(Leonardo da Vinci)처럼 여러 분야에 정통한 박학가(polymath)를 이상으로 삼기도 했다","지식이 방대해지면서 전문화(specialization)가 진행되었다"]},{"t":"vs","title":"학습 방식","cols":[{"name":"순차적 집중(sequential focus)","items":["학습 연구에서 한 번에 한 주제에 집중하는 방식"]},{"name":"동시에 여러 분야","items":["동시에 여러 분야를 다루는 방식"]}]}],"ee78a1c586eb8b1e_41":[{"t":"tree","title":"과학 보도와 과장","root":"과학 커뮤니케이션","branches":[["보도 자료(press release)","연구 성과를 과장할 수 있다는 비판이 있다"],["과장(hype)","불확실성과 한계를 숨기고 기대를 부풀리는 일이다"],["책임 있는 소통","근거의 강도와 단서(caveat)를 함께 알리는 것이다"],["상관과 인과","이 맥락에서 '상관과 인과'(correlation vs. causation)의 구분이 자주 강조된다"]]}],"fc61dc9ac6b4ceff_20":[{"t":"def","term":"빙산 비유(iceberg model)","text":"에드워드 홀(Edward T. Hall)이 문화를 눈에 보이는 부분과 보이지 않는 부분으로 나누며 널리 알렸다"},{"t":"vs","title":"문화의 빙산","cols":[{"name":"수면 위","items":["겉으로 드러난 관습, 의복, 음식"]},{"name":"수면 아래","items":["가치관과 신념"]}]},{"t":"def","term":"문화 간 역량(intercultural competence)","text":"이를 이해하는 능력이다"}],"fc61dc9ac6b4ceff_21":[{"t":"tree","title":"추천 알고리즘과 필터 버블","root":"추천 알고리즘","branches":[["추천 시스템(recommender system)","협업 필터링(collaborative filtering)처럼 비슷한 사용자의 선택을 이용해 취향을 예측한다"],["필터 버블(filter bubble)","엘리 패리저(Eli Pariser)가 2011년 책으로 알린 개념으로 맞춤 추천이 새로운 정보를 가린다는 우려다"],["세렌디피티(serendipity)","반대로 우연한 발견을 높이는 설계도 연구된다"]]}],"fc61dc9ac6b4ceff_22":[{"t":"vs","title":"조세 원칙","cols":[{"name":"응능 원칙(ability-to-pay principle)","items":["조세 철학에서 부담 능력에 따라 세금을 내야 한다고 본다"]},{"name":"응익 원칙(benefit principle)","items":["얻는 혜택에 따라 내야 한다고 본다"]}]},{"t":"def","term":"『소유의 신화』(2002)","text":"리엄 머피와 토머스 네이글(Liam Murphy & Thomas Nagel)은 세금 제도를 떠나 재산권을 논할 수 없다고 주장했다"}],"fc61dc9ac6b4ceff_23":[{"t":"vs","title":"사회 학습과 환경적 학습","cols":[{"name":"사회 학습(social learning)","items":["농업 의사결정 연구에서 농부가 다른 농부를 모방한다"]},{"name":"환경적 학습(environmental learning)","items":["결과 정보로 직접 배운다"]}]},{"t":"tree","title":"농법의 확산과 관리","root":"농법","branches":[["혁신 확산 이론(diffusion of innovations)","로저스(Rogers)의 이론은 새로운 농법이 어떻게 퍼지는지 설명한다"],["적응적 관리(adaptive management)","결과를 보며 계획을 고쳐 가는 방식이다"]]}],"fc61dc9ac6b4ceff_24":[{"t":"tree","title":"음악 연주의 표현적 편차","root":"음악 심리학","branches":[["표현적 타이밍(expressive timing)과 루바토(rubato)","악보와 달리 연주자가 박자를 미세하게 늘이고 줄이는 것이 음악적 표현의 핵심이라고 본다"],["퀀타이즈(quantization) 연주","컴퓨터가 악보대로 정확히 재생하는 연주는 기계적으로 들린다"],["그루브(groove)","미세한 타이밍 차이가 만드는 흥이다"]]}],"fc61dc9ac6b4ceff_29":[{"t":"vs","title":"법적 문제와 윤리적 문제","cols":[{"name":"법적 문제(legal issue)","items":["경영 윤리(business ethics)는 법적 문제와 윤리적 문제를 구분한다"]},{"name":"윤리적 문제(ethical issue)","items":["합법이지만 비윤리적일 수 있기 때문이다"]}]},{"t":"tree","title":"이해관계자와 딜레마","root":"경영 윤리","branches":[["이해관계자 이론(stakeholder theory)","기업이 주주만이 아니라 직원, 고객, 지역 사회를 고려해야 한다고 본다"],["윤리적 딜레마","여러 선택지 중 어느 것도 만족스럽지 않은 상황이다"]]}],"fc61dc9ac6b4ceff_30":[{"t":"tree","title":"인터넷과 전문성","root":"인터넷과 전문성","branches":[["전문가 권위(epistemic authority)","인터넷에서는 누구나 정보를 올릴 수 있어 약해졌다고 논의된다"],["더닝-크루거 효과(Dunning-Kruger effect)","능력이 낮은 사람이 자신의 능력을 과대평가하는 경향이다"],["정보 신뢰성 평가(credibility assessment)와 정보 리터러시(information literacy)","중요해진다"]]}],"fc61dc9ac6b4ceff_31":[{"t":"tree","title":"동물의 영역과 동물원 관리","root":"동물의 영역","branches":[["하이니 헤디거(Heini Hediger)","스위스 동물학자로 『야생 동물과 포획』(1950)에서 동물의 영역(territory) 안에 잠자리, 먹이터 같은 기능 구역이 나뉜다고 설명했다"],["도피 거리(flight distance)","위험을 느끼는 접근 거리이다"],["근접학(proxemics)","사람의 공간 개념을 다룬 에드워드 홀(Edward Hall)의 근접학과 비교된다"]]}],"fc61dc9ac6b4ceff_32":[{"t":"tree","title":"팬덤 연구","root":"팬덤 연구","branches":[["헨리 젠킨스(Henry Jenkins)","『텍스트 밀렵꾼』(1992)은 팬을 단순한 소비자가 아니라 텍스트를 재해석하고 창작하는 참여 문화(participatory culture)의 주체로 보았다"],["팬 픽션(fan fiction)과 팬아트","대표적 예다"],["정서와 정체성","팬덤 연구는 정서와 정체성이 어떻게 형성되는지 분석한다"]]}],"fc61dc9ac6b4ceff_33":[{"t":"flow","title":"오트 쿠튀르와 디자이너","steps":["샤를 프레데릭 워스(Charles Frederick Worth)는 1850년대 파리에서 고객 요구를 받는 재단사가 아니라 자신의 작품을 제안하는 디자이너로서 활동한 최초의 오트 쿠튀르(haute couture) 디자이너로 평가된다","그는 옷에 자기 이름의 라벨을 붙였다","이후 디자이너는 창작자이자 예술가로 인식되었다"]}],"fc61dc9ac6b4ceff_34":[{"t":"tree","title":"자전적 기억과 서사","root":"자전적 기억","branches":[["자전적 기억(autobiographical memory)","심리학에서 개인이 겪은 삶의 사건에 대한 기억이다"],["프레더릭 바틀릿(Frederic Bartlett)","1932년 기억이 사진처럼 저장되는 것이 아니라 재구성(reconstruction)된다고 주장했다"],["서사 정체성(narrative identity)","댄 맥애덤스(Dan McAdams)의 개념으로 자신의 삶을 이야기로 엮어 정체성을 형성한다는 개념이다"]]}],"fc61dc9ac6b4ceff_35":[{"t":"cause","title":"식물의 모듈형 생장과 재생","causes":["식물은 가지, 잎 같은 반복 단위를 계속 만드는 모듈형(modular) 생물이며 분열 조직(meristem)이 평생 세포를 만든다"],"result":"동물보다 손상 후 재생(regeneration)이 쉽다","effects":["생태학의 천이(succession)에서 선구 식물(pioneer species)은 훼손된 땅에 가장 먼저 자리 잡는다"]}],"fc61dc9ac6b4ceff_36":[{"t":"flow","title":"운하의 갑문","steps":["운하의 갑문(lock)은 수위가 다른 두 수역을 연결하는 장치다","선박이 칸막이 안으로 들어가면 물을 채우거나 빼서 수위를 맞춘 뒤 다음 구간으로 이동한다","중력을 이용한 이런 방식은 파나마 운하(1914년 개통)에서도 쓰인다"]}],"fc61dc9ac6b4ceff_37":[{"t":"tree","title":"무의식적 문화","root":"문화인류학","branches":[["아비투스(habitus)","피에르 부르디외(Pierre Bourdieu)의 아비투스는 사회 환경에서 몸에 밴 성향 체계를 가리킨다"],["암묵지(tacit knowledge)","마이클 폴라니(Michael Polanyi)의 암묵지는 말로 설명하기 어려운 지식이다"],["문화적 대본(cultural script)","문화는 의식적으로 논의되는 부분뿐 아니라 당연하게 여겨지는 문화적 대본으로도 작동한다"]]}],"fc61dc9ac6b4ceff_38":[{"t":"tree","title":"집단의 정의","root":"사회심리학","branches":[["집단(group)","단순히 모인 사람들(aggregate)과 구별된다"],["쿠르트 레빈(Kurt Lewin)","구성원이 서로 영향을 주고받는 상호의존성(interdependence)을 집단의 핵심으로 보았다"],["집단성(entitativity)","한 무리가 하나의 실체처럼 보이는 정도다"]]}],"fc61dc9ac6b4ceff_39":[{"t":"tree","title":"보안과 편의의 상충","root":"결제 보안","branches":[["IC 칩(EMV) 카드","마그네틱 띠 카드에서 IC 칩 카드로 바뀌면 위조 방지가 강화된다"],["상충(trade-off)","보안과 편의는 흔히 상충 관계로 논의되며 다중 인증(multi-factor authentication)은 보안을 높이지만 이용 절차가 늘어난다"],["비접촉 결제(contactless payment)","편의를 높이는 대안이다"]]}],"fc61dc9ac6b4ceff_40":[{"t":"vs","title":"기능주의와 작가성","cols":[{"name":"기능주의","items":["디자인사에서 건축가 루이스 설리번(Louis Sullivan)의 '형태는 기능을 따른다(form follows function)'는 말을 따라 개인 표현보다 기능과 표준을 강조했고 바우하우스(Bauhaus)가 대표적이다"]},{"name":"스타 디자이너 문화","items":["개인 개성과 작가성(authorship)을 부각한다"]}]},{"t":"def","term":"건축가 없는 건축(architecture without architects, 1964)","text":"익명의 토착 디자인에 주목했다"}],"fc61dc9ac6b4ceff_41":[{"t":"tree","title":"기후 위기와 상상력","root":"기후 위기와 상상력","branches":[["아미타브 고시(Amitav Ghosh)","인류학자로 2016년 『대혼란: 기후 변화와 상상할 수 없는 것』(The Great Derangement)에서 현대 소설이 기후 위기를 제대로 다루지 못했다고 비판했다"],["기후 소설(cli-fi)","기후 위기를 주제로 한 장르다"],["인류세(Anthropocene)","인간 활동이 지구 환경을 바꾼 시대라는 개념이다"]]}],"ce57f02ce782bac3_33":[{"t":"tree","title":"혁신 이론","root":"혁신 이론","branches":[["인접 가능성(adjacent possible)","스튜어트 카우프만(Stuart Kauffman)의 개념으로 현재 상태에서 한 걸음 만에 도달할 수 있는 새 가능성들을 가리키며 스티븐 존슨(Steven Johnson)이 혁신 이론으로 소개했다"],["혁신 확산 이론(diffusion of innovations)","에버렛 로저스(Everett Rogers)의 이론으로 새로운 아이디어가 사회에 퍼지는 과정을 설명한다"]]}],"ce57f02ce782bac3_34":[{"t":"tree","title":"사진과 장소","root":"사진과 장소의 이동","branches":[["사진의 등장","장소의 이미지를 복제해 이동시켰다"],["벤야민과 손택","발터 벤야민(Walter Benjamin)은 복제 기술이 작품의 아우라를 약화시킨다고 보았고, 수전 손택(Susan Sontag)은 『사진에 관하여』(1977)에서 사진이 현실을 소유하는 방식이라고 논했다"],["장소성(sense of place)","에드워드 렐프(Edward Relph)의 개념으로 사람이 장소에 갖는 의미 있는 애착이다"]]}],"ce57f02ce782bac3_35":[{"t":"tree","title":"재택근무","root":"재택근무(telecommuting, teleworking)","branches":[["정의","정보통신 기술로 사무실 밖에서 일하는 방식이다"],["현전주의(presenteeism)","관리자가 눈에 보이는 근무를 평가하는 태도로 확산을 막는 요인으로 지적된다"],["근접 편향(proximity bias)","원격 근무자가 승진에서 불리해지는 현상으로 논의된다"]]}],"ce57f02ce782bac3_36":[{"t":"tree","title":"고정관념","root":"고정관념(stereotype)","branches":[["리프먼","월터 리프먼(Walter Lippmann)은 1922년 『여론』에서 사람이 복잡한 세계를 단순화한 머릿속 그림, 곧 고정관념으로 이해한다고 설명했다"],["범주화(categorization)","정보를 빠르게 처리하게 해 주지만 개인차를 무시하게 만든다"],["구별","사회심리학에서는 고정관념이 편견(prejudice), 차별(discrimination)과 구별된다"]]}],"ce57f02ce782bac3_37":[{"t":"tree","title":"식물의 결핍 반응","root":"영양 결핍에 대한 식물의 반응","branches":[["무기 영양소(mineral nutrient) 부족","질소, 인, 칼륨 같은 영양소가 부족하면 뿌리를 더 뻗거나 가지를 늘리는 식으로 반응한다"],["황화(chlorosis)","잎이 누렇게 변하는 현상으로 결핍의 신호다"],["균근(mycorrhiza)","균류와의 공생도 영양분 흡수를 돕는다"]]}],"ce57f02ce782bac3_38":[{"t":"tree","title":"디지털 음악 제작","root":"디지털 음악","branches":[["표본화(sampling)","소리를 수치로 바꾸는 방법으로 만든다"],["음질","샘플링 주파수와 해상도가 음질을 결정한다"],["DAW의 기능","디지털 오디오 워크스테이션(DAW)에서는 원본을 건드리지 않고 편집을 되돌릴 수 있는 비파괴 편집(non-destructive editing)이 가능하며 양자화(quantization)로 박자를 맞출 수 있다"]]}],"ce57f02ce782bac3_39":[{"t":"tree","title":"예술 작품의 범주","root":"예술 작품의 범주와 제작","branches":[["켄들 월턴(Kendall Walton)","1970년 논문 「예술의 범주들」에서 작품이 어떤 범주에 속하는지에 따라 감상 방식과 평가가 달라진다고 주장했다"],["미학의 쟁점","작품이 제작된 방식과 작가의 의도를 감상에 포함할지가 쟁점이다"],["아서 단토(Arthur Danto)","겉모습이 같아도 의미가 다를 수 있다고 보았다"]]}],"ce57f02ce782bac3_40":[{"t":"tree","title":"역사 소설","root":"역사 소설(historical fiction)","branches":[["월터 스콧(Walter Scott)","『웨이벌리』(1814)로 근대 장르가 되었다는 평가를 받는다"],["게오르크 루카치(Georg Lukács)","『역사 소설』(1937)에서 소설이 시대의 사회적 힘을 보여 준다고 분석했다"],["아래로부터의 역사(history from below)","평범한 사람들의 경험에 주목하는 접근이다"]]}],"ce57f02ce782bac3_41":[{"t":"tree","title":"망각과 기억","root":"망각과 기억","branches":[["망각 곡선(forgetting curve)","헤르만 에빙하우스(Hermann Ebbinghaus)가 1885년 제시해 학습 후 시간이 지날수록 기억이 급격히 줄어든다고 보였다"],["인출 방식","단서 없이 떠올리는 회상(recall)과 보고 알아보는 재인(recognition)이 있으며 재인이 더 쉽다"],["출처 기억(source memory)","정보를 어디서 배웠는지 기억하는 능력이다"]]}],"d0bf808e464f65e3_20":[{"t":"tree","title":"목표 설정","root":"목표 설정 이론(goal-setting theory)","branches":[["로크와 래섬(Locke & Latham)","에드윈 로크와 게리 래섬의 이론으로 구체적이고 도전적인 목표가 모호한 목표보다 수행을 높인다고 본다"],["SMART 목표","구체적(Specific), 측정 가능(Measurable), 달성 가능(Achievable), 현실적(Relevant), 기한 있는(Time-bound) 목표를 가리킨다"],["목표의 구분","결과 목표(outcome goal)와 과정 목표(process goal)를 구분하기도 한다"]]}],"d0bf808e464f65e3_21":[{"t":"vs","title":"구성주의와 실재론","cols":[{"name":"칸트","items":["우리가 사물 자체(noumena)가 아니라 인식 틀을 거친 현상(phenomena)을 안다고 보았다"]},{"name":"사회 구성주의(social constructivism)","items":["지식과 현실 인식이 문화와 상호작용으로 만들어진다고 본다"]},{"name":"실재론(realism)","items":["인식과 독립된 현실이 있다고 본다"]}]}],"d0bf808e464f65e3_22":[{"t":"tree","title":"프라이버시 역설","root":"프라이버시 역설(privacy paradox)","branches":[["정의","사람들이 프라이버시를 걱정한다고 말하면서도 실제로는 개인정보를 쉽게 공유하는 모순적 행동이다"],["부추기는 요인","디지털 흔적(digital footprint)과 맞춤형 서비스(personalization)의 편익이 이를 부추긴다"],["이해관계자(stakeholder)","기업, 정부, 소비자의 역할이 논의된다"]]}],"d0bf808e464f65e3_23":[{"t":"vs","title":"감정의 보편성과 구성","cols":[{"name":"기본 감정(basic emotions) 모델","items":["보편적 기본 감정을 상정한다","폴 에크만(Paul Ekman)은 기본 감정의 보편성을 주장했다"]},{"name":"구성주의(constructionism)","items":["감정이 문화에 따라 구성된다고 본다","감정 표현을 얼마나 드러낼지는 문화마다 다른 표현 규칙(display rules)을 따른다","독일어 Schadenfreude 같은 번역하기 어려운 감정 단어도 연구된다"]}]}],"d0bf808e464f65e3_24":[{"t":"tree","title":"인간-로봇 협업","root":"인간-로봇 협업 체계","branches":[["공동 인지 체계(joint cognitive system)","인지공학에서 홀나겔과 우즈(Hollnagel & Woods)가 사람과 기계를 하나의 인지 체계로 보는 개념을 제안했다"],["인간-로봇 팀(human-robot teaming)","각자의 강점이 합쳐져 시너지(synergy)가 나온다는 관점이다"],["혼합 주도(mixed-initiative)","사람과 기계가 주도권을 번갈아 갖는 방식이다"]]}],"d0bf808e464f65e3_29":[{"t":"tree","title":"생태계의 규모","root":"생태계(ecosystem)","branches":[["정의","아서 탠슬리(Arthur Tansley)가 1935년 정의한 생물 군집과 비생물 환경이 상호작용하는 체계다"],["규모","입속 미생물군집(microbiome)부터 바다 전체까지 다양하며, 관찰 규모(scale)에 따라 중요한 과정이 달라진다"],["생물군계(biome)","열대우림, 사막처럼 거대한 규모의 생태계 유형이다"]]}],"d0bf808e464f65e3_30":[{"t":"tree","title":"자동차 수요 관리","root":"교통계획","branches":[["모터화(motorization)","교통계획에서는 소득이 늘면 자동차 보유가 늘어나는 모터화가 나타난다"],["교통수요관리(travel demand management)","이를 관리하는 방법에는 혼잡통행료(congestion pricing)가 있으며 싱가포르(1975)와 런던(2003)이 대표적이다"],["유발 수요(induced demand)","도로를 늘리면 교통량이 늘어나는 현상도 알려져 있다"]]}],"d0bf808e464f65e3_31":[{"t":"tree","title":"디지털 시대의 미술","root":"디지털 시대의 미술","branches":[["매체 특정성(medium specificity)","미술사에서 클레멘트 그린버그(Clement Greenberg)가 매체의 고유성을 강조하며 주장했다"],["포스트디지털(post-digital)","디지털 기술이 일상화되면서 미술가들이 컴퓨터를 특별한 매체로 내세우지 않는 경향이 나타났다"],["추상(abstraction)","현실의 재현에서 벗어난 표현이다"]]}],"d0bf808e464f65e3_32":[{"t":"tree","title":"형식주의 비평","root":"형식주의(formalism)","branches":[["형식주의","작품의 외적 맥락보다 텍스트 자체의 형식을 분석한다"],["신비평(New Criticism)","1940~50년대 영미 신비평은 면밀한 읽기(close reading)와 의도의 오류(intentional fallacy)를 강조했다"],["러시아 형식주의(Russian Formalism)","문학성을 형식에서 찾았다"]]}],"d0bf808e464f65e3_33":[{"t":"tree","title":"사용자 혁신","root":"사용자 혁신","branches":[["에릭 폰 히펠(Eric von Hippel)","『혁신의 민주화』(2005)에서 제품 혁신이 제조업체가 아닌 사용자(user)에게서 나올 수 있다고 주장했다"],["선도 사용자(lead user)","앞서가는 사용자로 새로운 요구를 먼저 발견한다"],["공동 창조(co-creation)","기업과 소비자가 함께 가치를 만드는 접근이다"]]}],"d0bf808e464f65e3_34":[{"t":"tree","title":"푸가","root":"푸가(fugue)","branches":[["정의","하나의 주제(subject)를 여러 성부가 차례로 모방하며 전개하는 대위법(counterpoint) 음악 형식이다"],["대표작","요한 세바스티안 바흐(Johann Sebastian Bach)의 『푸가의 기법』이 대표적이다"],["동기(motif)","짧은 선율인 동기를 변형, 확장해 곡을 발전시키는 과정은 음악 분석의 핵심이다"]]}],"d0bf808e464f65e3_35":[{"t":"tree","title":"동물 분쟁의 게임 이론","root":"동물의 싸움","branches":[["존 메이너드 스미스(John Maynard Smith)","동물의 싸움을 매파-비둘기 게임(Hawk-Dove game)과 진화적으로 안정한 전략(ESS)으로 분석했다"],["평가 전략(assessment strategy)","싸우는 개체는 상대의 힘을 평가하는 전략을 쓴다"],["의례화된 과시(ritualized display)","실제 싸움 전에 하기도 한다"]]}],"d0bf808e464f65e3_36":[{"t":"tree","title":"화석 기록","root":"화석 기록(fossil record)","branches":[["화석 기록","지층(stratigraphy)에 보존된 과거 생물의 흔적으로 진화의 증거다"],["다윈","중간 단계 화석이 부족하다는 문제를 인식했다"],["단속평형설(punctuated equilibrium)","엘드리지와 굴드(Eldredge & Gould, 1972)가 진화가 오랜 정체와 급격한 변화로 이루어진다고 제안했다"]]}],"d0bf808e464f65e3_37":[{"t":"tree","title":"매몰비용과 소유 효과","root":"합리적이지 않은 의사결정","branches":[["매몰비용(sunk cost)","이미 지출해 회수할 수 없는 비용이며, 이를 의식해 합리적이지 않은 결정을 계속하는 것이 매몰비용 오류(sunk cost fallacy)다"],["소유 효과(endowment effect)","리처드 세일러(Richard Thaler)가 제시한, 소유한 물건을 더 높이 평가하는 현상이다"],["손실 회피(loss aversion)","같은 크기의 이득보다 손실을 더 크게 느끼는 경향이다"]]}],"d0bf808e464f65e3_38":[{"t":"tree","title":"녹색 혁명","root":"녹색 혁명(Green Revolution)","branches":[["녹색 혁명","1960년대 노먼 볼로그(Norman Borlaug) 등이 개발한 다수확 품종(high-yield varieties)과 비료, 관개로 수확량을 크게 늘린 농업 변화다"],["붉은 여왕 효과(Red Queen effect)","병해충이 계속 진화해 새 품종(cultivar)이 필요한 상황은 생물학의 이 효과로 설명되기도 한다"]]}],"d0bf808e464f65e3_39":[{"t":"tree","title":"집단의 포식자 탐지","root":"동물행동학","branches":[["다수의 눈 효과(many-eyes effect)","무리의 구성원이 많을수록 포식자를 일찍 발견한다"],["관련 개념","한 개체의 도주가 무리 전체에 퍼지는 정보 연쇄(information cascade)와 경계 신호인 경보 울음(alarm call)도 관련 개념이다"],["보초 행동(sentinel behavior)","일부 개체가 감시를 맡는 방식이다"]]}],"d0bf808e464f65e3_40":[{"t":"tree","title":"이동성 연구","root":"이동성 패러다임(mobilities paradigm)","branches":[["제안","사회과학의 이동성 패러다임은 존 어리(John Urry)와 미미 셸러(Mimi Sheller)가 2006년 제안했다"],["관점","사람, 물건, 정보의 이동이 사회를 구성한다고 보며 이동 중인 몸의 경험(embodiment)을 연구한다"],["비장소(non-place)","마르크 오제(Marc Augé)의 개념으로 공항, 역처럼 정체성 없이 지나가는 공간이다"]]}],"d0bf808e464f65e3_41":[{"t":"cause","title":"방관자 효과","causes":["책임 분산(diffusion of responsibility)","서로 눈치를 보다 상황을 위험하지 않다고 오해하는 다원적 무지(pluralistic ignorance)"],"result":"주변에 사람이 많을수록 도움이 줄어드는 방관자 효과(bystander effect)","effects":["사회심리학자 존 달리와 빕 라타네(John Darley & Bibb Latané, 1968)가 1964년 키티 제노비스 사건에 자극받아 연구했다"]}],"d45c804a7c27aaf5_21":[{"t":"tree","title":"전문성의 한계","root":"전문성과 가치 판단","branches":[["존재-당위 문제(is-ought problem)","철학에서 흄(David Hume)이 지적한, 사실에 대한 진술에서 도덕적 당위를 직접 이끌어낼 수 없다는 문제다"],["가치중립적 과학(value-free ideal)","과학철학에서 논의되는 이상이다"],["전문성","특정 영역(domain)에 한정되며 사실 판단과 가치 판단은 구별된다"]]}],"d45c804a7c27aaf5_22":[{"t":"vs","title":"위해요소와 위험","cols":[{"name":"위해요소(hazard)","items":["해를 끼칠 잠재력이 있는 요인"]},{"name":"위험(risk)","items":["위해요소에 노출되어 실제 해를 입을 확률"]}]},{"t":"tree","title":"위험 평가","root":"위험 평가(risk assessment)","branches":[["고려 요소","노출 정도와 독성을 함께 고려한다"],["요인 분류","생물학적, 물리적, 화학적 요인이 대표적 분류이며 오염물질(contaminant) 노출 경로도 따진다"]]}],"d45c804a7c27aaf5_23":[{"t":"flow","title":"쿤의 과학 변동","steps":["과학자 집단이 공유하는 연구 틀인 패러다임(paradigm) 안에서 문제를 푸는 정상과학(normal science)","설명되지 않는 변칙 사례(anomaly)가 쌓임","위기가 옴","패러다임 전환(paradigm shift)이 일어남"]},{"t":"def","term":"토머스 쿤(Thomas Kuhn)","text":"과학철학자로 1962년 『과학혁명의 구조』에서 정상과학을 설명했다"}],"d45c804a7c27aaf5_24":[{"t":"tree","title":"수리와 창조성","root":"수리(repair)","branches":[["수리","기술사와 인류학에서 단순한 복구가 아니라 창의적 실천으로 연구된다"],["브리콜라주(bricolage)","클로드 레비스트로스(Claude Lévi-Strauss)의 개념으로 주어진 재료로 임기응변하는 방식이다"],["대장장이","산업화 이전의 대장장이는 주문 제작(made-to-order)으로 고객에 맞춰 물건을 만들었고, 대량 생산(mass production)과 대비된다"]]}],"d45c804a7c27aaf5_29":[{"t":"flow","title":"세포 주기","steps":["세포가 자라고 DNA를 복제하는 간기(interphase)","분열기","체세포 분열인 유사분열(mitosis)","세포질 분열(cytokinesis)로 두 딸세포(daughter cell)가 생김"]},{"t":"def","term":"세포 주기(cell cycle)","text":"세포가 자라고 DNA를 복제한 뒤 둘로 나뉘는 과정으로 세포의 크기와 대사 활동은 주기에 따라 달라진다"}],"d45c804a7c27aaf5_30":[{"t":"tree","title":"유기농과 토지 이용","root":"농업","branches":[["유기농(organic farming)","합성 비료, 농약을 쓰지 않는 농업이다"],["하버-보슈법(Haber-Bosch process)","대기 질소로 암모니아 비료를 만드는 방법으로 20세기 식량 생산을 크게 늘렸다"],["수확량 격차(yield gap)","수확량 차이로 농업 집약화(agricultural intensification)와 함께 땅 아끼기(land sparing)와 땅 나누기(land sharing) 논쟁으로 이어진다"]]}],"d45c804a7c27aaf5_31":[{"t":"tree","title":"유머 이론","root":"유머 이론","branches":[["불일치 이론(incongruity theory)","기대와 현실의 어긋남이 웃음을 낳는다고 설명한다"],["우월 이론"],["해소 이론"],["놀이 틀(play frame)","그레고리 베이트슨(Gregory Bateson)의 개념으로 진짜와 가짜를 구분하지 않는 맥락을 설명하며 유머와 연결된다"],["칸트(Kant)","웃음을 긴장이 갑자기 풀리는 현상으로 보았다"]]}],"d45c804a7c27aaf5_32":[{"t":"tree","title":"뉴스 보도 양식","root":"방송 연구의 뉴스","branches":[["긴장","뉴스는 정보 제공과 오락 사이에서 긴장을 겪는다"],["인포테인먼트(infotainment)","정보와 오락의 결합이다"],["타블로이드화(tabloidization)","선정적 스타일이 퍼지는 현상이다"],["공영방송(public service broadcasting)","시민의 교육과 정보를 목적으로 한다"],["화법(mode of address)","시청자에게 말을 거는 방식이다"]]}],"d45c804a7c27aaf5_33":[{"t":"vs","title":"공유지의 비극과 자치","cols":[{"name":"개릿 하딘(Garrett Hardin)","items":["1968년 공유지의 비극(tragedy of the commons)을 발표했다","공동 자원이 과도하게 쓰여 고갈된다고 주장했다"]},{"name":"엘리너 오스트롬(Elinor Ostrom)","items":["2009년 노벨 경제학상을 받았다","공동 자원(common-pool resources)을 둘러싼 제도와 자치(self-governance)를 연구했다"]}]}],"d45c804a7c27aaf5_34":[{"t":"vs","title":"정확성의 의미","cols":[{"name":"과학","items":["정밀성(precision)과 측정의 엄밀함을 추구한다"]},{"name":"역사 서술","items":["헤이든 화이트(Hayden White)의 『메타역사』(1973)는 역사 서술이 서사(narrative) 구조를 가진다고 분석했다"]},{"name":"인문학","items":["의미의 모호성(ambiguity)과 해석의 다양성이 중요하다"]}]}],"d45c804a7c27aaf5_35":[{"t":"tree","title":"가치 사슬과 정보 시스템","root":"기업 정보 시스템","branches":[["가치 사슬(value chain)","마이클 포터(Michael Porter)가 1985년 기업 활동을 단계별로 보는 개념으로 제시했다"],["기업 간 정보 시스템과 EDI","기업 간 정보 시스템(interorganizational information system)과 전자 문서 교환(EDI)은 거래를 자동화해 공급망(supply chain)을 통합한다"],["ERP","기업의 자원 관리를 통합한 시스템이다"]]}],"d45c804a7c27aaf5_36":[{"t":"tree","title":"가격 기구","root":"가격 기구(price mechanism)","branches":[["가격 기구","경제학에서 가격 변동이 생산자, 소비자의 행동을 조정하는 방식이다"],["사이먼-에를리히 내기(Simon-Ehrlich wager)","1980년 줄리언 사이먼과 폴 에를리히의 자원 희소성과 가격의 관계를 둘러싼 논쟁이었다"],["시장 반응 모형","대체재(substitute) 개발과 절약이 가격 신호로 촉진된다"],["탄소세(carbon tax)","세금으로 가격을 올리는 방식의 대표다"]]}],"d45c804a7c27aaf5_37":[{"t":"tree","title":"허구 세계","root":"허구 세계와 현실","branches":[["가능 세계(possible worlds)","서사학에서 허구 세계를 설명하는 개념이다"],["아리스토텔레스(Aristotle)","『시학』에서 시는 일어난 일을 그대로 기록하는 역사보다 있을 법한 일을 다루므로 더 보편적이라고 했다"],["인과","허구는 현실의 무한한 사건 중 일부를 선택, 배열한 것이므로 인과가 정돈되어 있다"]]}],"d45c804a7c27aaf5_38":[{"t":"tree","title":"자동화와 변화 관리","root":"자동화(automation)","branches":[["기술적 실업(technological unemployment)","자동화가 낳는 우려다"],["변화 관리(change management)","경영학에서 조직 변화를 구성원이 받아들이도록 돕는 활동이며 변화에 대한 저항(resistance to change)을 줄이는 방법을 연구한다"],["관련 개념","노사 관계(labor relations)와 재교육(retraining)도 관련 개념이다"]]}],"d45c804a7c27aaf5_39":[{"t":"vs","title":"영화 이론","cols":[{"name":"정신분석 영화 이론","items":["프로이트(Freud)와 라캉(Lacan)을 바탕으로 영화가 욕망과 환상(fantasy)을 어떻게 드러내는지 분석한다","철학자 슬라보예 지젝(Slavoj Žižek)은 다큐멘터리 「변태적 영화 가이드」(2006)에서 이를 설명했다"]},{"name":"현실주의(realism)","items":["앙드레 바쟁(André Bazin)의 관점으로 영화가 현실을 기록한다고 본다"]}]}],"d45c804a7c27aaf5_40":[{"t":"tree","title":"과학적 설명 이론","root":"과학철학의 설명 이론","branches":[["연역-법칙적 모형(deductive-nomological model, 1948)","칼 헴펠(Carl Hempel)이 설명을 법칙과 초기 조건으로부터의 논리적 도출로 본다"],["통합주의(unificationism)","필립 키처(Philip Kitcher)가 폭넓은 현상을 통합하는 설명을 대표한다"],["인과-기계론적 설명(causal-mechanical explanation)","웨슬리 새먼(Wesley Salmon)이 원인 과정을 밝히는 설명을 대표한다"]]}],"d45c804a7c27aaf5_41":[{"t":"tree","title":"분류와 범주화","root":"분류와 범주화","branches":[["원형 이론(prototype theory)","인지심리학에서 엘리너 로시(Eleanor Rosch)가 범주가 가장 전형적인 사례를 중심으로 조직된다고 본다"],["분류학(taxonomy)","생물학의 분류학은 린네(Linnaeus)의 위계적 분류에서 비롯된다"],["자연종(natural kinds)","철학에서 자연에 실재하는 분류인 자연종을 인간이 편의상 만든 분류와 구별한다"]]}],"ebs27dy_g01_1":[{"t":"vs","title":"감정의 보편성과 맥락","cols":[{"name":"보편적 기본 감정","items":["심리학에서 감정(emotion)이 인류 공통의 것인지, 문화와 상황에 따라 달라지는 것인지는 오래된 논쟁이다","다윈(Darwin) 이래 일부 연구자는 얼굴 표정(facial expression)에 보편적인 기본 감정(basic emotion)이 있다고 보았다"]},{"name":"상황에 따른 형성","items":["감정은 상황(context)과 학습된 사회화(socialization) 속에서 형성된다는 입장도 있다","Izard는 감정과 인지(cognition)가 서로 얽힌 구조를 연구한 학자로 알려져 있다"]}]}],"ebs27dy_g01_2":[{"t":"tree","title":"인터페이스와 재탐색","root":"인간-컴퓨터 상호작용(HCI)","branches":[["HCI","사용자가 시스템을 쉽고 효율적으로 쓰도록 설계하는 분야다"],["사용성(usability) 연구","설계자의 의도와 사용자의 실제 행동이 어긋나는 경우를 자주 보여 준다"],["재탐색","사람은 반복 사용을 통해 항목의 위치를 기억해 두고 찾는 경향이 있다"]]}],"ebs27dy_g01_3":[{"t":"tree","title":"인터페이스 은유","root":"은유(metaphor)","branches":[["은유","한 대상을 다른 대상에 빗대어 이해하는 방식으로, 언어뿐 아니라 사고의 틀을 만든다는 것이 인지언어학(cognitive linguistics)의 관점이다"],["인터페이스 은유","컴퓨터의 데스크톱(desktop), 폴더(folder), 휴지통(trash) 같은 이름이 대표적이다"],["기능","이런 은유는 낯선 기술을 익숙한 경험에 연결해 사용법을 짐작하게 한다"]]}],"ebs27dy_g01_4":[{"t":"def","term":"프레이밍(framing)","text":"같은 사안도 어떤 관점과 표현으로 제시하느냐에 따라 수용자의 해석과 판단이 달라진다는 이론","ex":["사형제는 도덕이나 비용 등 서로 다른 틀로 논의될 수 있다"]},{"t":"def","term":"뉴스 프레임","text":"언론학에서 여론(public opinion)에 미치는 영향을 실험(experiment)으로 검증한다"}],"ebs27dy_g01_5":[{"t":"tree","title":"귀납과 지식","root":"인식론(epistemology)","branches":[["인식론","우리가 무엇을 어떻게 안다고 말할 수 있는지를 따지는 철학의 한 분야다"],["흄(Hume)의 귀납(induction) 문제","과거 경험에서 미래를 추론하는 귀납이 논리적으로 확실하게 정당화되지 않는다는 문제를 제기했다"],["구분","확실성(certainty)과 높은 개연성(probability)을 구분하는 논의가 이어져 왔다"]]}],"ebs27dy_g01_6":[{"t":"tree","title":"수용의 심리학","root":"수용(acceptance)","branches":[["수용","심리치료에서 불쾌한 생각이나 감정을 억지로 없애려 하지 않고 있는 그대로 인정하는 태도를 가리킨다"],["관련 치료","수용전념치료(ACT)나 마음챙김(mindfulness)이 이 개념을 중시한다"],["구분","수용은 불편한 경험과 싸우거나 피하려는 반응과 구분되며, 이 글은 수용이라는 말이 실제로 가리키는 바를 다룬다"]]}],"ebs27dy_g01_7":[{"t":"tree","title":"우연의 일치와 확률","root":"우연의 일치(coincidence)","branches":[["확률론","놀랍게 느껴져도 확률론(probability theory)으로 따져 볼 수 있다"],["생일 문제(birthday problem)","직관(intuition)이 확률을 잘못 어림하는 대표 사례로 알려져 있다"],["무한 원숭이 정리(infinite monkey theorem)","충분한 시간이 주어지면 드문 사건도 일어날 수 있다는 점을 보여 주는 사고 실험이다"]]}],"ebs27dy_g01_8":[{"t":"tree","title":"심상 주사 실험","root":"심상(mental image)","branches":[["심상","인지심리학(cognitive psychology)에서 감각 없이 머릿속에 떠올리는 시각적 표상이다"],["코슬린(Kosslyn)의 심상 주사(image scanning) 실험","사람이 상상 속 대상 위를 훑을 때 실제 공간과 비슷한 방식으로 처리하는지를 검증하려 했다"],["논쟁","심상이 그림 같은 형태인지, 명제(proposition) 같은 형태인지에 대한 논쟁과 이어진다"]]}],"ebs27dy_g01_9":[{"t":"flow","title":"소셜미디어의 상업화","steps":["처음에 개인 간 소통 수단으로 출발한 소셜미디어(social media)","광고와 판매 기능이 붙음","상업 플랫폼(platform)으로 확장","이용자 데이터를 활용해 소비자에게 직접 접근하는 마케팅"]},{"t":"def","term":"전자상거래(e-commerce)","text":"인터넷으로 상품과 서비스를 사고파는 활동"}],"ebs27dy_g01_10":[{"t":"tree","title":"경청","root":"경청(listening)","branches":[["경청","단순히 소리를 듣는 것이 아니라 상대의 말을 이해하려고 주의를 기울이는 능동적 행위다"],["경청 장애물(barrier)","의사소통 연구에서 상대가 말하는 도중 자기 답변을 미리 준비하는 습관이 흔한 장애물로 거론된다"],["결과","이런 습관은 상대의 의도(intention)나 맥락을 놓치게 만든다"]]}],"ebs27dy_g01_11":[{"t":"tree","title":"소비자의 구매와 위험 인식","root":"구매 결정(purchase decision)","branches":[["관점","마케팅(marketing)의 소비자 행동 이론에서는 합리적 이득 계산의 결과로 볼지, 위험 회피의 과정으로 볼지 관점이 갈린다"],["인식된 위험(perceived risk)","금전적 손실, 성능 불확실성, 사회적 평가 등이 있다"],["브랜드(brand)","이런 불확실성을 줄여 주는 단서로 작용하기도 한다"]]}],"ebs27dy_g01_12":[{"t":"tree","title":"꿀벌의 거리 측정","root":"꿀벌(honeybee)","branches":[["춤(waggle dance)","꿀이 있는 곳을 동료에게 알리는 것으로 유명하며, 이 춤에는 방향과 거리 정보가 담긴다"],["동물 인지(animal cognition)","동물이 거리를 어떻게 재는지는 이 연구의 주제다"],["길 찾기","곤충의 길 찾기는 여러 감각 정보를 어떻게 이용하는지와 관련지어 연구된다"]]}],"ebs27dy_g02_1":[{"t":"tree","title":"공감 정확도","root":"공감 정확도(empathic accuracy)","branches":[["공감 정확도","사회심리학(social psychology)에서 타인의 생각과 감정을 얼마나 정확히 알아맞히는지를 가리킨다"],["이크스(Ickes)","이를 일상 대화 장면에서 측정한다"],["추론(inference)","사람은 상대의 마음을 추론할 때 표정, 말투, 맥락 등 여러 단서를 쓴다"]]}],"ebs27dy_g02_2":[{"t":"tree","title":"본능","root":"본능(instinct)","branches":[["본능","심리학에서 학습 없이 타고나는 행동 양식을 뜻하며, 동기(motivation) 연구의 오랜 주제다"],["일상의 쓰임","일상에서는 직관이나 숙련된 반응을 본능적이라고 부르지만 학술적 정의는 더 엄격하다"],["고정 행동 패턴(fixed action pattern)","동물행동학(ethology)이 종 특유의 행동으로 본능의 예로 든다"]]}],"ebs27dy_g02_3":[{"t":"vs","title":"섬광 기억의 생생함과 정확도","cols":[{"name":"생생함","items":["섬광 기억(flashbulb memory)은 충격적인 공적 사건을 들었을 때의 상황을 아주 생생하게 기억한다고 느끼는 현상이다"]},{"name":"정확도(accuracy)","items":["연구들은 그 생생함에 비해 정확도는 꼭 높지 않다고 보고한다","미디어 노출이 기억에 미치는 영향은 기억의 재구성(reconstruction)과도 관련된다"]}]}],"ebs27dy_g02_4":[{"t":"tree","title":"프레이밍과 선택","root":"프레이밍 효과(framing effect)","branches":[["행동경제학(behavioral economics)","같은 내용도 표현 방식에 따라 선택이 달라지는 효과가 널리 확인되었다"],["합리적 선택(rational choice) 모형","사람의 선호가 미리 고정되어 있다는 모형에 의문을 제기한다"],["정치학","여론조사 문항의 문구가 응답을 바꾸는 현상이 연구되어 왔다"]]}],"ebs27dy_g02_5":[{"t":"tree","title":"의식과 무의식 계산","root":"신경과학(neuroscience)","branches":[["신경세포(neuron)","뇌의 신경세포들이 의식(consciousness) 없이도 많은 계산을 수행한다고 본다"],["근사 계산","정보를 합산하는 근사 계산은 비교적 단순한 신경 회로로도 가능하다고 알려져 있다"],["의식","흔히 더 복잡한 통합과 보고 과정과 연결지어 논의된다"]]}],"ebs27dy_g02_6":[{"t":"vs","title":"기억의 종류","cols":[{"name":"서술 기억(declarative memory)","items":["사실 정보를 저장한다"]},{"name":"절차 기억(procedural memory)","items":["기술을 몸에 익힌다"]}]},{"t":"tree","title":"기억 과정","root":"기억","branches":[["암기(rote memory)","의미와 무관하게 외우는 일과, 원리를 이해하며 기억하는 일은 서로 다른 인지 과정으로 구분되곤 한다"],["천재(genius)","천재와 기억력의 관계는 오래전부터 철학자와 문인들이 논한 주제다"]]}],"ebs27dy_g02_7":[{"t":"tree","title":"과학 연구의 비선형성","root":"과학적 방법(scientific method)","branches":[["흔한 설명","가설(hypothesis) 설정과 검증이 순서대로 직선처럼 이루어진다고 설명된다"],["과학사(history of science)","가설이 오랫동안 묻혔다가 새로운 기술이나 자료로 다시 주목받는 경우가 많다"],["현실적 제약","연구비와 데이터 같은 제약도 이론의 운명을 좌우한다"]]}],"ebs27dy_g02_8":[{"t":"vs","title":"우연성과 알고리즘","cols":[{"name":"우연성(contingency)","items":["철학에서 어떤 일이 필연(necessity)이 아니라 다르게 될 수도 있었음을 뜻한다"]},{"name":"알고리즘(algorithm)","items":["정해진 규칙에 따라 단계적으로 문제를 푸는 절차로, 컴퓨터과학의 기본 개념이다"]}]},{"t":"def","term":"인공지능(AI)과 인간의 선택","text":"비교하는 논의에서 이 두 개념이 함께 쓰이곤 한다"}],"ebs27dy_g02_9":[{"t":"tree","title":"쾌락","root":"쾌락(pleasure)","branches":[["에피쿠로스(Epicurus)","철학에서 행복론의 핵심 개념인 쾌락을 선의 기준으로 삼았다"],["공리주의(utilitarianism)","쾌락과 고통이 도덕 판단의 기준으로 쓰인다"],["성찰(reflection)","즐거움을 누리는 순간의 경험과 이를 되돌아보는 성찰이 어떤 관계인지는 오래된 쟁점이다"]]}],"ebs27dy_g02_10":[{"t":"tree","title":"과학의 이상화","root":"이상화(idealization)","branches":[["이상화","과학은 복잡한 현실을 다루기 위해 일부러 단순화한 모형을 쓴다"],["이상기체(ideal gas)","분자 사이의 힘과 분자 부피를 무시한 가상의 기체 모형이다"],["과학철학(philosophy of science)","이상화가 진리와 어떤 관계인지가 논의된다"]]}],"ebs27dy_g02_11":[{"t":"vs","title":"위험과 불확실성","cols":[{"name":"위험(risk)","items":["결과와 확률이 모두 알려진 상황","작은 세계(small world)에 비유한다"]},{"name":"불확실성(uncertainty)","items":["알려지지 않은 상황","큰 세계(large world)에 비유한다"]}]},{"t":"def","term":"후회(regret)","text":"의사결정론에서 위험과 불확실성을 각각 작은 세계와 큰 세계로 비유하기도 하며, 후회는 지나간 선택의 결과를 대안과 비교할 때 생기는 감정이다"}],"ebs27dy_g02_12":[{"t":"tree","title":"아동기 기억","root":"자서전적 기억(autobiographical memory)","branches":[["자서전적 기억","자신이 겪은 일에 대한 기억으로, 어린 시절에는 점차 형성된다"],["유아기 기억상실(infantile amnesia)","대부분의 사람이 유아기를 기억하지 못하는 현상이다"],["부모와 아이의 대화","방식은 아이가 경험을 이야기로 엮는 능력에 영향을 줄 수 있다고 알려져 있다"]]}],"ebs27dy_g03_1":[{"t":"vs","title":"자존감과 자기개념","cols":[{"name":"자존감(self-esteem)","items":["자신을 가치 있다고 평가하는 정도"]},{"name":"자기개념(self-concept)","items":["자신에 대해 가진 신념의 총체","명료성(self-concept clarity)은 심리적 안정과 관련된다"]}]},{"t":"def","term":"연구","text":"사회심리학자들은 자존감 수준에 따라 자기개념의 모습이 어떻게 다른지를 연구해 왔다"}],"ebs27dy_g03_2":[{"t":"tree","title":"문해력","root":"문해력(literacy)","branches":[["문해력","글을 읽고 쓰는 능력이며, 현대 사회에서는 시민권과 경제 참여의 기반으로 여겨진다"],["유네스코(UNESCO)","문맹 퇴치를 교육 접근성과 연결해 왔다"],["문자 사용","학자들은 문자 사용이 사회 제도와 사고방식 전반에 영향을 준다고 논의해 왔다"]]}],"ebs27dy_g03_3":[{"t":"vs","title":"문화와 사고 방식","cols":[{"name":"서양","items":["문화심리학(cultural psychology)에서 개인주의(individualism)로 대비한다"]},{"name":"동아시아","items":["집단주의(collectivism)로 대비하며 문화에 따른 사고 방식의 차이를 연구한다"]}]},{"t":"def","term":"니스벳(Nisbett)","text":"문화에 따라 주의와 사고의 방식이 다르다고 제안했다. 이 글은 자아관(self-construal)이 주의(attention)에 미치는 영향을 다룬다"}],"ebs27dy_g03_4":[{"t":"tree","title":"의료 수요와 가격","root":"수요(demand)","branches":[["수요","경제학에서 특정 가격에서 소비자가 실제로 구매하려는 양을 뜻한다"],["필요와 수요","필요가 있어도 가격 때문에 사지 못하는 사람은 시장에서 수요로 잡히지 않는다"],["수요 법칙(law of demand)","가격과 수요량의 관계를 설명한다"]]}],"ebs27dy_g03_5":[{"t":"tree","title":"역사 서술","root":"역사학(historiography)","branches":[["역사가","사료(source)를 선택하고 해석하며 이를 하나의 서사(narrative)로 엮는다"],["연대순(chronological order)","기본 틀이지만 원인을 설명하기 위해 시간을 오가기도 한다"],["역사","과거 그 자체가 아니라 과거에 대한 구성된 설명이라는 점이 자주 강조된다"]]}],"ebs27dy_g03_6":[{"t":"vs","title":"지배와 위신","cols":[{"name":"위신(prestige)","items":["배울 만한 기술과 지식을 가진 사람에게 자발적으로 주어지는 존경","헨릭(Henrich) 등이 설명한다"]},{"name":"지배(dominance)","items":["위협이나 힘에 기반한 복종과 연결된다"]}]},{"t":"def","term":"지위(status)","text":"인류학과 진화심리학에서 지위를 얻는 길로 지배와 위신을 구분하는 이론이 있다"}],"ebs27dy_g03_7":[{"t":"vs","title":"감정과 느낌","cols":[{"name":"감정(emotion)","items":["신체와 뇌의 자동적 반응"]},{"name":"느낌(feeling)","items":["그 반응에 대한 의식적 경험"]}]},{"t":"tree","title":"구분의 쓰임","root":"신경과학자 다마지오(Damasio)의 구분","branches":[["일상","일상에서 두 단어를 섞어 쓰는 경향과 대비된다"],["감정 조절(emotion regulation)","연구에서도 이 구분이 활용된다"]]}],"ebs27dy_g03_8":[{"t":"tree","title":"메소포타미아","root":"메소포타미아(Mesopotamia)","branches":[["위치","티그리스와 유프라테스 강 사이 지역으로 최초의 도시 문명이 일어난 곳이다"],["관개","강수가 적고 강이 불규칙하게 범람해서 농사에 물 관리가 중요했다"],["수메르인(Sumerians)","쐐기문자(cuneiform)를 만든 것으로 알려져 있다"]]}],"ebs27dy_g03_9":[{"t":"vs","title":"문화와 문명","cols":[{"name":"문화(culture)","items":["라틴어에서 경작(cultivation)을 뜻하는 말에서 유래했다"]},{"name":"문명(civilization)","items":["도시(civitas)와 관련이 있다"]}]},{"t":"def","term":"은유(metaphor)","text":"이 글은 농업과 교환이라는 은유로 두 개념을 구분하는 논의로 읽힌다"}],"ebs27dy_g03_10":[{"t":"vs","title":"대표성의 두 영역","cols":[{"name":"대의민주주의(representative democracy)","items":["대표(representation)는 국민을 대신해 의사를 결정하는 정당성의 근거가 된다"]},{"name":"과학","items":["모형이나 데이터가 현실을 대표(represent)한다는 점이 권위의 바탕이 된다"]}]},{"t":"def","term":"과학기술학(STS)","text":"이런 두 영역의 권위가 어떻게 정당화되는지를 비교한다"}],"ebs27dy_g03_11":[{"t":"tree","title":"열대 토양","root":"토양의 비옥도(fertility)","branches":[["비옥도","기후와 암석의 풍화(weathering) 정도에 따라 크게 달라진다"],["용탈(leaching)","열대 지역은 비가 많이 내려 양분이 씻겨 내려가는 현상이 일어나기 쉽다"],["양분","토양 속 양분의 양은 그 땅에서 농사를 얼마나 오래 지속할 수 있는지와 관련된다"]]}],"ebs27dy_g03_12":[{"t":"tree","title":"팀 신뢰","root":"신뢰(trust)","branches":[["신뢰","조직심리학(organizational psychology)에서 팀 성과와 협력의 핵심 요인이다"],["심리적 안전감(psychological safety)","높은 팀일수록 구성원이 정보를 공유하고 의견을 말하기 쉽다"],["정보는 곧 힘","이런 인식은 정보를 쥐고 있으려는 행동으로 이어진다"]]}],"ebs27dy_g04_1":[{"t":"tree","title":"범주화","root":"범주화(categorization)","branches":[["범주화","인지심리학에서 대상을 같은 종류로 묶는 정신 과정이다"],["확률론적 관점(probabilistic view)","범주가 필수 조건 대신 유사한 특징의 묶음으로 이루어진다고 본다"],["원형 이론(prototype theory)","로쉬(Rosch)의 이론으로 대표적인 원형에 가까운 사례일수록 더 빨리 인식된다고 설명한다"]]}],"ebs27dy_g04_2":[{"t":"tree","title":"리더십과 공감","root":"리더십(leadership)","branches":[["공감(empathy)","타인의 감정을 이해하고 반응하는 능력으로, 감성지능(emotional intelligence)의 핵심 요소로 꼽힌다"],["진정성(authenticity)","말과 행동이 내면의 가치와 일치하는 성질을 뜻한다"],["칸트(Kant)","윤리학에서 결과보다 의무와 도리를 중시한 철학자로 알려져 있다"]]}],"ebs27dy_g04_3":[{"t":"tree","title":"언어와 감정","root":"감정(emotion)과 언어(language)","branches":[["관계","심리학과 언어학에서 오래 논의된 주제다"],["문화","문화마다 감정을 가리키는 단어가 다르다는 점이 자주 거론된다"],["표현","감정을 말로 표현하는 일이 감정 경험과 어떻게 연결되는지도 연구 주제다"]]}],"ebs27dy_g04_5":[{"t":"tree","title":"소득과 수요","root":"소득탄력성(income elasticity)","branches":[["소득탄력성","경제학에서 소득(income)이 변할 때 수요량이 바뀌는 정도를 말한다"],["정상재(normal good)","소득이 늘면 수요가 늘어나는 재화"],["열등재(inferior good)","소득이 늘면 수요가 줄어드는 재화"],["한계효용 체감(diminishing marginal utility)","소비가 늘수록 추가 만족이 줄어드는 관련 개념이다"]]}],"ebs27dy_g04_6":[{"t":"vs","title":"패스트패션과 슬로패션","cols":[{"name":"패스트패션(fast fashion)","items":["유행을 빠르게 반영한 저가 의류를 대량 생산하고 빨리 소비하는 산업 방식","의류 폐기물과 노동 문제 때문에 환경과 윤리 측면의 비판을 받는다"]},{"name":"슬로패션(slow fashion)","items":["적게 사서 오래 입는 지속가능한 소비(sustainable consumption)를 내세운다"]}]}],"ebs27dy_g04_7":[{"t":"vs","title":"자연적 의미와 비자연적 의미","cols":[{"name":"자연적 의미(natural meaning)","items":["연기가 불을 뜻하듯 징후에서 읽어 내는 의미"]},{"name":"비자연적 의미(non-natural meaning)","items":["말이나 기호가 전달하는 의미로 화용론(pragmatics)에서 다룬다"]}]},{"t":"def","term":"그라이스(Grice)","text":"영국 철학자로 의미를 자연적 의미와 비자연적 의미로 나누었다"}],"ebs27dy_g04_8":[{"t":"tree","title":"과학의 진보","root":"과학의 진보","branches":[["두 관점","과학철학에서는 과학의 진보를 이해의 증대로 볼지, 자연에 대한 통제력의 증대로 볼지 논의한다"],["근대 과학","이론적 호기심을 넘어 실용적 목적을 갖게 되었다는 해석도 있다"],["복지(welfare)","의학 기술의 발달이 인간의 복지에 실제로 어떤 영향을 주는지는 따로 따져 볼 물음이다"]]}],"ebs27dy_g04_9":[{"t":"tree","title":"동물복지","root":"동물복지(animal welfare) 연구","branches":[["기준","동물이 좋은 상태에 있는지 판단하는 기준을 다룬다"],["행동 목록(ethogram)","동물행동학에서 한 종이 자연 상태에서 보이는 행동을 정리한 것이다"],["비교","야생과 사육 환경의 차이를 비교하면 사육 동물의 복지 문제를 알아낼 수 있다"]]}],"ebs27dy_g04_10":[{"t":"tree","title":"선거제도의 분류","root":"선거제도(electoral system)","branches":[["다수대표제(plurality/majority)"],["비례대표제(proportional representation)"],["혼합제(mixed)"]]},{"t":"def","term":"선거제도","text":"정치학에서 득표를 의석으로 바꾸는 규칙이며, 분류(typology)는 복잡한 현실을 이해하기 위해 기준을 정해 유형을 나누는 작업이다"}],"ebs27dy_g04_11":[{"t":"tree","title":"멜로디","root":"음악 인지(music cognition)","branches":[["음악 인지","사람이 소리를 어떻게 듣고 기억하는지를 다루는 분야다"],["멜로디(melody)","여러 음이 시간에 따라 이어진 짜임으로, 같은 곡이 조(key)나 빠르기(tempo)가 달라져도 같은 곡으로 들리는 경험은 흔하다"],["이조(transposition)","이를 이조라 부르는 경우도 있다"]]}],"ebs27dy_g04_12":[{"t":"tree","title":"참여 저널리즘","root":"디지털 시대의 저널리즘(journalism)","branches":[["참여자","독자를 단순 수용자가 아니라 참여자로 보려는 흐름이 있다"],["참여 저널리즘(participatory journalism)","독자의 제보와 의견이 취재 과정에 반영되는 방식이다"],["구독 기반 모델","광고 의존에서 벗어나려는 시도로 거론된다"]]}],"ebs27dy_g05_1":[{"t":"tree","title":"돌고래의 인지","root":"돌고래(dolphin)","branches":[["연구 대상","뇌가 크고 사회성이 높아 동물 인지(animal cognition) 연구에서 자주 다뤄진다"],["대표 연구","거울 자기인식(mirror self-recognition) 실험과 개체별 신호음(signature whistle) 연구가 대표적이다"],["질문","이런 연구는 동물의 지능과 의식이 어디까지 인정될 수 있는지를 묻는다"]]}],"ebs27dy_g05_2":[{"t":"tree","title":"기술 낙관론","root":"환경 논의","branches":[["기술 낙관론(technological optimism)","새로운 기술이 환경 문제를 해결하리라는 입장이다"],["생태경제학(ecological economics)","경제 활동과 자연 환경의 관계를 함께 다룬다"],["반동 효과(rebound effect)","효율이 높아지면 사용량이 오히려 늘어나는 현상이다"]]}],"ebs27dy_g05_3":[{"t":"vs","title":"동물 복지론과 권리론","cols":[{"name":"동물 복지론","items":["싱어(Singer)는 고통을 느끼는 능력(sentience)을 기준으로 동물의 이익을 고려해야 한다고 주장했다"]},{"name":"동물 권리론","items":["레건(Regan)은 권리론을 대표하는 철학자다"]}]},{"t":"def","term":"도덕적 지위(moral status)","text":"동물 보호는 윤리학에서 동물의 도덕적 지위와 연결된다"}],"ebs27dy_g05_4":[{"t":"tree","title":"고대 그리스의 교육","root":"고대 그리스(Ancient Greece)의 교육","branches":[["가정과 공동체","국가 주도의 학교보다 가정과 공동체에서 이루어지는 경우가 많았다"],["소피스트(sophist)","돈을 받고 수사학과 지식을 가르친 순회 교사였다"],["소크라테스(Socrates)","대화로 가르쳤다"],["교육사(history of education)","교육 방식의 변화는 주요 주제다"]]}],"ebs27dy_g05_5":[{"t":"tree","title":"인정 욕구","root":"인정 욕구(need for approval)","branches":[["정의","심리학에서 타인에게 인정받고 싶은 마음이다"],["애착 이론(attachment theory)","아동이 양육자와 맺는 정서적 유대가 이후 관계와 자기 평가에 영향을 준다고 본다"],["의존","타인의 평가에 지나치게 의존하면 자기 가치감이 흔들릴 수 있다"]]}],"ebs27dy_g05_6":[{"t":"flow","title":"동기 이론의 흐름","steps":["동기(motivation): 행동을 시작하고 지속하게 하는 심리적 힘이다","클라크 헐(Clark Hull): 쥐의 미로 실험으로 학습과 동기를 연구한 행동주의 심리학자로, 목표 구배(goal gradient)라는 개념으로도 알려져 있다","이후 기대-가치 이론(expectancy-value theory)과 목표 설정 이론이 이어졌다"]}],"ebs27dy_g05_7":[{"t":"tree","title":"행동과 마음","root":"인간의 행동","branches":[["두 기원","심리학과 철학에서는 의식적 숙고(deliberation)에서 나오는지 무의식(unconscious)에서 나오는지를 논의한다"],["프로이트(Freud)","인간 행동의 상당 부분이 무의식적 동기에서 비롯된다고 보았다"],["합리화(rationalization)","일상에서 우리는 자신의 행동을 사후에 합리화하기도 한다"]]}],"ebs27dy_g05_8":[{"t":"tree","title":"사고의 신경 경로","root":"에드워드 드 보노(Edward de Bono)","branches":[["수평적 사고(lateral thinking)","그가 제안한 창의성 이론이다"],["설명","뇌가 자주 쓰는 경로를 따라 사고하는 경향이 있다고 설명했다"],["신경가소성(neuroplasticity)","뇌 연결이 경험에 따라 바뀔 수 있다는 개념이다"]]}],"ebs27dy_g05_9":[{"t":"vs","title":"참여할 권리와 보호받을 권리","cols":[{"name":"참여할 권리","items":["아동과 청소년이 정보의 소비자일 뿐 아니라 생산자로 참여한다는 점이 주목받는다"]},{"name":"보호받을 권리","items":["이들은 법적으로 보호 대상이어서 두 권리가 충돌하기도 한다"]}]},{"t":"def","term":"유엔 아동권리협약(CRC)","text":"두 권리를 모두 인정한다"}],"ebs27dy_g05_10":[{"t":"tree","title":"숲과 나무","root":"생태학(ecology)의 숲(forest)","branches":[["숲","나무 종류와 나이가 다양하게 섞인 복합 생태계다"],["나무의 모양","같은 종도 환경과 경쟁(competition)에 따라 모양이 달라진다"],["비유","이 글은 나무의 이상적 모양을 규범처럼 비유한 표현이다"]]}],"ebs27dy_g05_11":[{"t":"tree","title":"하이데거의 기술론","root":"하이데거(Heidegger)의 기술(technology)","branches":[["탈은폐(revealing)","기술을 단순한 도구가 아니라 존재가 드러나는 방식으로 보았다"],["주장","기술의 본질이 기술적인 것이 아니라고 주장했다"],["포이에시스(poiesis)","그리스어로 무엇인가를 산출해 내는 일을 가리키며 이 논의의 배경이 된다"]]}],"ebs27dy_g05_12":[{"t":"tree","title":"팬 위키","root":"팬 위키(fan wiki)","branches":[["팬 위키","팬덤(fandom) 연구에서 팬들이 정보를 모아 편집하는 협업 사이트다"],["규범","위키피디아처럼 신뢰할 만한 출처(reliable source)를 요구하는 규범이 있다"],["정보 리터러시(information literacy)","팬 공동체가 정보를 다루는 방식과 연결된다"]]}],"ebs27dy_g06_1":[{"t":"cause","title":"무기 이전의 부작용","causes":["동맹 강화나 영향력 확대 수단으로 쓰이는 무기 이전(arms transfer)"],"result":"부작용","effects":["블로백(blowback): 미국 정보기관 CIA가 사용한 용어로, 비밀 작전의 의도치 않은 역효과를 가리킨다","외교정책의 예상치 못한 결과(unintended consequences)를 설명할 때 자주 인용된다"]}],"ebs27dy_g06_2":[{"t":"tree","title":"유통 경로","root":"유통 경로(distribution channel)","branches":[["유통 경로","마케팅에서 생산자에서 소비자까지 상품이 이동하는 통로다"],["도매상(wholesaler)","생산자와 소매상 사이에서 대량으로 사들여 나누어 파는 중간 상인이다"],["중간 상인","유통 경로에서 어떤 기능을 하는지는 마케팅의 기본 주제다"]]}],"ebs27dy_g06_3":[{"t":"tree","title":"현실 검증","root":"현실 검증(reality testing)","branches":[["현실 검증","상상과 현실을 구별하는 능력으로, 정신분석학과 발달심리학에서 중요한 개념이다"],["피아제(Piaget)","아동의 사고가 단계적으로 발달한다고 보았다"],["범주화(categorization)","이 구분을 돕는 인지 능력이다"]]}],"ebs27dy_g06_4":[{"t":"tree","title":"사회적 학습","root":"사회적 학습(social learning)","branches":[["사회적 학습","다른 개체를 관찰해 배우는 학습이다"],["모방(imitation)","그중 행동 방식을 그대로 따라 하는 것이다"],["구별","에뮬레이션(emulation)이나 자극 강화(stimulus enhancement)와 구별되며 동물 인지와 문화(culture) 연구에서 중요하다"]]}],"ebs27dy_g06_5":[{"t":"vs","title":"고객 만족과 감동","cols":[{"name":"고객 만족(customer satisfaction)","items":["마케팅과 서비스 연구에서 감동과 구분된다"]},{"name":"고객 감동(delight)","items":["기대를 크게 넘어설 때 생기는 강한 긍정 감정","한 번 경험한 감동이 이후 서비스에 대한 평가 기준과 어떤 관계가 있는지도 연구 주제다"]}]}],"ebs27dy_g06_6":[{"t":"tree","title":"개념 정의","root":"정의(definition)","branches":[["정의","논리학에서 개념의 범위를 정하는 진술이다"],["적절성","정의가 적절한지 어떻게 검증하는지는 논리학과 철학의 기초 문제다"],["범위","정의는 대상을 너무 넓게도, 너무 좁게도 규정할 수 있다"]]}],"ebs27dy_g06_7":[{"t":"vs","title":"곤충의 행동","cols":[{"name":"흔한 통념","items":["곤충(insect)은 흔히 본능에 따라 정해진 행동을 한다고 알려져 있다"]},{"name":"최근 연구","items":["일부 곤충이 학습하고 위치를 기억하는 등 유연한 행동을 보인다고 보고한다","인간의 일화 기억(episodic memory)을 동물에게서 찾을 수 있는지는 비교 인지 연구의 쟁점이다"]}]}],"ebs27dy_g06_8":[{"t":"tree","title":"고령화","root":"고령화(aging population)","branches":[["정의","평균 수명이 늘고 출생률이 낮아져 노년층 비중이 커지는 인구 현상이다"],["영향","의료, 연금, 여가 산업 등 사회 전반에 영향을 준다"],["스포츠 산업","관중과 후원 기업의 구성이 달라지는 데 맞춰 마케팅 방식을 바꿀 수 있다"]]}],"ebs27dy_g06_9":[{"t":"tree","title":"소비 단위","root":"소비자 행동 연구","branches":[["단위 편향(unit bias)","사람들이 한 단위를 적정량으로 여겨 그만큼 소비하는 경향을 말한다"],["포만감(satiety)","먹은 양에 따라 느끼는 배부름이다"],["결과","음식 섭취량이 배고픔뿐 아니라 환경적 단서에도 영향받음을 보여 준다"]]}],"ebs27dy_g06_10":[{"t":"tree","title":"스포츠와 의사결정","root":"스포츠과학(sport science)","branches":[["선수의 수행","운동 기술(motor skill)뿐 아니라 의사결정(decision-making)에도 좌우된다고 본다"],["전문성(expertise)","인지심리학은 전문가가 상황을 읽고 빠르게 판단하는 능력을 핵심으로 연구한다"],["지각-행동 결합(perception-action coupling)","이를 설명하는 개념이다"]]}],"ebs27dy_g06_11":[{"t":"tree","title":"소수 영향","root":"소수 영향(minority influence)","branches":[["정의","사회심리학에서 소수가 일관된 태도로 다수의 생각을 바꾸는 현상이다"],["동조(conformity)","모스코비치(Moscovici)가 연구한 이래 동조와 대비되는 영향 방식으로 다뤄진다"],["집단 규범","집단 규범과 내집단(in-group) 소속감이 설득에 큰 영향을 준다"]]}],"ebs27dy_g06_12":[{"t":"tree","title":"본질주의","root":"본질주의(essentialism)","branches":[["정의","사물이 그것이게 하는 필수적 속성, 곧 본질(essence)을 가진다는 철학적 입장이다"],["기원","아리스토텔레스(Aristotle)의 실체론에서 비롯되었다"],["가족 유사성(family resemblance)","비트겐슈타인(Wittgenstein)의 개념이 다른 설명으로 거론된다"]]}],"ebs27dy_g07_1":[{"t":"tree","title":"녹색 소비자","root":"녹색 소비자(green consumer)","branches":[["정의","환경에 덜 해로운 제품을 선호하는 소비자다"],["통제 소재(locus of control)","환경심리학에서는 통제 소재와 같은 성격 요인이 친환경 행동에 영향을 준다고 본다"],["간극","반면 태도와 실제 구매 사이의 간극(attitude-behavior gap)도 자주 지적된다"]]}],"ebs27dy_g07_2":[{"t":"tree","title":"학습법","root":"인지과학의 학습 연구","branches":[["연구 주제","어떻게 공부해야 오래 기억되는지를 연구하며, 인출 연습(retrieval practice)과 분산 학습(spaced practice)이 대표적인 주제다"],["점검","학교와 기관이 내놓는 학습 조언이 연구 결과와 얼마나 맞는지도 점검 대상이다"],["착각","안다고 느끼는 것과 실제로 아는 것이 다를 수 있다는 점도 연구되어 왔다"]]}],"ebs27dy_g07_3":[{"t":"tree","title":"교육 속 문화 편견","root":"교육사회학(sociology of education)","branches":[["학교 운영","학교가 어떤 계층과 문화의 기준 위에서 운영되는지를 다룬다"],["평가","학교 안에서 집단별 학업 성취와 행동이 어떻게 평가되는지도 연구 주제다"],["다문화 교육(multicultural education)","이는 문제의식과 연결된다"]]}],"ebs27dy_g07_4":[{"t":"tree","title":"해양 플라스틱 오염","root":"해양 플라스틱 오염(marine plastic pollution)","branches":[["정의","플라스틱이 분해되지 않고 바다에 쌓이는 환경 문제다"],["미세플라스틱(microplastics)","5mm 이하의 작은 조각으로 먹이사슬(food chain)을 통해 생물에 축적될 수 있다"],["지구 한계(planetary boundaries)","지구 시스템이 견딜 수 있는 환경 한계를 뜻한다"]]}],"ebs27dy_g07_5":[{"t":"tree","title":"저작권","root":"저작권(copyright)","branches":[["저작권","창작물의 복제와 배포를 창작자가 통제할 수 있게 하는 법적 권리다"],["앤 여왕법(Statute of Anne)","1709년 영국의 법으로 최초의 근대 저작권법으로 불린다"],["불법 복제(piracy)","디지털 시대에는 출판업과 서점의 수익에 영향을 준다는 논의가 있다"]]}],"ebs27dy_g07_6":[{"t":"tree","title":"사진과 현실","root":"사진과 현실","branches":[["수전 손택(Susan Sontag)","『사진에 관하여』에서 사진과 현실의 관계를 비판적으로 논했다"],["통념","사진이 현실을 있는 그대로 보여 준다는 생각은 오래된 통념이다"],["디지털 사진","등장하면서 사진의 객관성(objectivity)과 표상(representation)을 둘러싼 논의가 더 복잡해졌다"]]}],"ebs27dy_g07_7":[{"t":"tree","title":"뉴스 가치","root":"언론학의 뉴스 선택","branches":[["게이트키핑(gatekeeping)","편집자가 어떤 정보를 뉴스로 내보낼지 선택하는 과정이다"],["뉴스 가치(news value)","시의성, 영향력, 근접성 등 기준으로 설명된다"],["보도자료(press release)","기관이 언론에 보내는 공식 자료로 언론의 선택을 받아야 보도된다"]]}],"ebs27dy_g07_8":[{"t":"tree","title":"분업과 전문화","root":"분업(division of labour)","branches":[["분업","경제학에서 생산 과정을 나누어 각자 일부를 맡는 방식이다"],["애덤 스미스(Adam Smith)","『국부론』에서 분업이 생산성을 높인다고 설명했다"],["전문화(specialization)","교환과 시장 발달의 기초로 논의된다"]]}],"ebs27dy_g07_9":[{"t":"tree","title":"심리학의 정의","root":"심리학의 정의 논쟁","branches":[["내성법(introspection)","초기 심리학은 사람이 자기 마음을 직접 살피는 방법에 크게 의존했다"],["논쟁","이후 심리학의 연구 대상과 방법을 어떻게 정할지를 두고 논쟁이 이어졌다"],["동물 심리학(animal psychology)","본능(instinct)과 학습 연구에서 성과를 냈다"]]}],"ebs27dy_g07_10":[{"t":"tree","title":"도시 농업","root":"도시 농업(urban agriculture)","branches":[["정의","도시 안에서 작물을 기르거나 가축을 키우는 활동이다"],["효과","식량 접근성(food access)과 지역 식량 안보(food security)를 높일 수 있다고 논의된다"],["식물원(botanical garden)","식물 보전과 교육을 맡는 기관으로, 지역 사회와 협력해 프로그램을 운영한다"]]}],"ebs27dy_g07_11":[{"t":"tree","title":"식민지 노동","root":"식민주의(colonialism)","branches":[["정의","한 나라가 다른 지역을 정치적, 경제적으로 지배하는 체제다"],["식민지 경제","본국을 위한 원료 생산에 맞춰져 노동 착취(labour exploitation)가 흔했다"],["경제사","이런 역사가 오늘날의 국가 간 불평등(global inequality)과 연결되는지 논의한다"]]}],"ebs27dy_g08_1":[{"t":"cause","title":"해양 산성화","causes":["바다가 대기의 이산화탄소(CO2)를 흡수"],"result":"pH가 낮아지는 해양 산성화(ocean acidification)","effects":["바다는 탄소 흡수원(carbon sink)이지만 수온 상승과 산성화로 흡수 능력이 약해질 수 있다","탄산칼슘(calcium carbonate)으로 껍데기를 만드는 생물에 영향을 준다"]}],"ebs27dy_g08_2":[{"t":"tree","title":"대규모 언어 모델","root":"대규모 언어 모델(LLM)","branches":[["작동","방대한 텍스트로 훈련된 인공신경망(neural network)으로, 다음에 올 단어를 예측하는 방식으로 언어를 생성한다"],["핵심 기술","딥러닝(deep learning)과 트랜스포머(transformer) 구조가 핵심 기술이다"],["한계","훈련 데이터에 따라 편향(bias)이나 사실과 다른 내용이 나올 수 있다"]]}],"ebs27dy_g08_4":[{"t":"tree","title":"마지막 기회 관광","root":"마지막 기회 관광(last chance tourism)","branches":[["정의","기후변화로 사라질 위험이 있는 빙하나 산호초 같은 곳을 사라지기 전에 보려는 관광이다"],["영향","관광 연구에서는 이런 관광이 관광지와 지역 사회에 어떤 영향을 주는지를 논의한다"],["지속 가능한 관광(sustainable tourism)","이와 연결된 주제다"]]}],"ebs27dy_g08_5":[{"t":"tree","title":"과일 가공 폐기물","root":"순환경제(circular economy)","branches":[["순환경제","폐기물을 줄이고 자원을 다시 사용하는 경제 모델이다"],["부산물(by-product)","과일 가공 과정의 껍질과 씨 같은 부산물은 매립(landfill)하면 온실가스를 배출한다"],["업사이클링(upcycling)","식품 폐기물에서 유용한 성분을 추출하는 연구가 진행되고 있다"]]}],"ebs27dy_g08_6":[{"t":"vs","title":"하드 스킬과 소프트 스킬","cols":[{"name":"하드 스킬(hard skills)","items":["업무에 필요한 기술적 능력"]},{"name":"소프트 스킬(soft skills)","items":["소통과 협업, 문제 해결 같은 대인 능력"]}]},{"t":"def","term":"직무 기술서(job description)","text":"직무에 필요한 자격을 적은 문서이며 기업이 신입 사원에게 요구하는 역량은 인사 관리의 주요 관심사다"}],"ebs27dy_g08_7":[{"t":"tree","title":"무역","root":"경제사의 무역(trade)","branches":[["동력","문명이 발전하는 핵심 동력으로 다뤄진다"],["교환","지역마다 자원이 달라 교환이 이루어지고, 교환은 지식과 기술의 전파도 가져온다"],["위험(risk) 분산","한 지역의 흉작과 같은 위험을 분산하는 수단으로도 설명된다"]]}],"ebs27dy_g08_8":[{"t":"tree","title":"직원 창업","root":"기회비용(opportunity cost)","branches":[["기회비용","경제학에서 어떤 선택을 하면서 포기한 가장 가치 있는 대안의 가치다"],["직원 창업(employee entrepreneurship)","스핀오프(spin-off) 연구는 근로자가 회사를 떠나 창업하는 요인을 분석한다"],["영향 요인","이직과 창업 결정에는 회사의 상황, 직원 개인의 특성, 저축 같은 재정 여건이 영향을 줄 수 있다고 논의된다"]]}],"ebs27dy_g08_9":[{"t":"tree","title":"시간 지각","root":"시간 지각(time perception)","branches":[["정의","실제 시간과 달리 주관적으로 길거나 짧게 느껴지는 현상이다"],["내부 시계(internal clock)","뇌의 내부 시계가 시간을 재는 방식은 여러 모델로 설명된다"],["체온","체온과 대사 속도가 내부 시계에 영향을 줄 수 있다는 가설이 있다"],["비교 연구","사회와 기후에 따라 생활의 속도가 다르다는 비교 연구도 있다"]]}],"ebs27dy_g08_10":[{"t":"tree","title":"세대와 생애 과정","root":"세대(generation)","branches":[["세대","사회학에서 연령과 역사적 시기를 기준으로 사회를 이해하는 개념이다"],["카를 만하임(Karl Mannheim)","1920년대 논문에서 세대를 사회 변동의 요인으로 분석한 독일 사회학자다"],["생애 과정(life course)","연구는 나이가 개인의 역할과 사회 구조에 어떤 의미를 갖는지 다룬다"]]}],"ebs27dy_g08_11":[{"t":"tree","title":"의식 연구","root":"의식(consciousness)","branches":[["의식","주관적 경험을 뜻하며 철학과 신경과학에서 가장 어려운 문제로 꼽힌다"],["어려운 문제(hard problem)","차머스(Chalmers)가 의식의 주관적 경험을 설명하는 일을 이렇게 불렀다"],["접근","인간 의식은 자기 경험을 통해 직접 접근할 수 있지만 다른 생물의 의식은 추론해야 한다는 점이 쟁점이다"]]}],"ebs27dy_g08_12":[{"t":"tree","title":"유기화학","root":"유기화학(organic chemistry)","branches":[["정의","탄소(carbon)를 중심으로 한 화합물을 연구하는 화학 분야다"],["탄소","다른 원자와 결합해 긴 사슬과 고리를 만들 수 있어 생명체의 분자 구조 기반이 된다"],["핵심 원리","전자의 이동과 분자 구조가 반응 성질을 결정한다"]]}],"ebs27dy_g09_2":[{"t":"tree","title":"돌고래 사회","root":"돌고래(dolphin)의 사회","branches":[["분열-융합 사회(fission-fusion society)","집단 구성이 수시로 바뀌는 것으로 알려져 있다"],["연구의 어려움","이런 사회에서는 개체가 집단에 고정 소속되지 않아 연구자가 집단을 명확히 정의하기 어렵다"],["번식 성공(reproductive success)","동물행동 연구에서 개체의 적응 정도를 보여 주는 지표로 쓰인다"]]}],"ebs27dy_g09_3":[{"t":"cause","title":"무표정 실험","causes":["어머니가 갑자기 무표정해짐"],"result":"상호작용의 리듬이 깨져 영아가 혼란과 스트레스를 보임","effects":["발달심리학에서 에드 트로닉(Ed Tronick)의 무표정 실험(still-face experiment)이다","애착(attachment)과 정서 조절(emotion regulation) 연구에 널리 인용된다"]}],"ebs27dy_g09_4":[{"t":"vs","title":"경합성과 비경합성","cols":[{"name":"경합 재화(rivalry)","items":["한 사람이 쓸수록 다른 사람이 쓸 몫이 줄어든다","공유지의 비극(tragedy of the commons)은 경합적 공유 자원이 과도하게 쓰이는 문제를 다룬다"]},{"name":"비경합 재화","items":["여럿이 함께 써도 줄지 않는다"]}]},{"t":"def","term":"재화의 분류","text":"경제학에서 재화는 경합성과 배제성(excludability)으로 분류된다"}],"ebs27dy_g09_5":[{"t":"tree","title":"회복탄력성","root":"회복탄력성(resilience)","branches":[["정의","역경이나 스트레스를 겪은 뒤 다시 회복하고 적응하는 능력이다"],["영향 요인","심리학에서는 타고난 기질뿐 아니라 사회적 지지와 대처 방식이 영향을 준다고 본다"],["다른 분야","이 개념은 생태학과 공학에서도 시스템의 복원력을 뜻하는 말로 쓰인다"]]}],"ebs27dy_g09_6":[{"t":"tree","title":"회복탄력성","root":"회복탄력성(resilience)","branches":[["정의","역경이나 스트레스를 겪은 뒤 다시 회복하고 적응하는 능력이다"],["영향 요인","심리학에서는 타고난 기질뿐 아니라 사회적 지지와 대처 방식이 영향을 준다고 본다"],["다른 분야","이 개념은 생태학과 공학에서도 시스템의 복원력을 뜻하는 말로 쓰인다"]]}],"ebs27dy_g09_7":[{"t":"tree","title":"기후변화의 감지","root":"초객체(hyperobject)","branches":[["티머시 모턴(Timothy Morton)","환경철학자로 기후변화를 초객체라 불렀다"],["초객체","시간과 공간에 광범위하게 퍼져 있어 한눈에 파악하기 어려운 대상이다"],["구분","기후(climate)와 날씨(weather)의 구분도 이 논의에서 자주 쓰인다"]]}],"ebs27dy_g09_8":[{"t":"tree","title":"과학의 양면성","root":"과학과 윤리","branches":[["주제","과학과 윤리의 관계는 과학철학의 오랜 주제다"],["베이컨(Bacon)","지식이 곧 힘이라고 했고, 20세기에는 핵무기를 계기로 과학자의 사회적 책임(social responsibility)이 부각되었다"],["과학주의(scientism)","과학 지식만이 유일한 참된 지식이라는 입장이다"]]}],"ebs27dy_g09_9":[{"t":"tree","title":"동물 이미지","root":"동물 이미지","branches":[["활용","환경 및 동물 운동 단체는 동물 이미지를 이용해 대중의 공감과 지지를 이끈다"],["관련 개념","이는 의인화(anthropomorphism)와 상징적 종(flagship species) 개념과 연결된다"],["사회학","동물에 대한 태도 변화가 환경 감수성(environmental sensitivity)의 확대와 관련된다고 본다"]]}],"ebs27dy_g09_10":[{"t":"tree","title":"소비문화","root":"소비 문화(consumer culture)","branches":[["정의","사회사에서 상품이 사회적 지위(social status)를 나타내는 현상으로 설명된다"],["베블런(Veblen)","과시적 소비(conspicuous consumption)를 부유층이 지위를 드러내려는 소비로 정의했다"],["브로델(Braudel)","자본주의 이전부터 사치품 거래가 있었음을 보였다"]]}],"ebs27dy_g09_11":[{"t":"tree","title":"언어의 기능","root":"언어의 사회적 기능","branches":[["화용론과 사회언어학","화용론(pragmatics)과 사회언어학(sociolinguistics)에서는 언어가 정보 전달뿐 아니라 관계 형성, 권력 행사, 정체성 표현 같은 사회적 행위를 한다고 본다"],["화행 이론(speech act theory)","오스틴(Austin)이 말이 행위를 수행한다고 주장했다"],["교육 언어학","교실 담화를 이 관점에서 분석한다"]]}],"ebs27dy_g09_12":[{"t":"tree","title":"언어의 기능","root":"언어의 사회적 기능","branches":[["화용론과 사회언어학","화용론(pragmatics)과 사회언어학(sociolinguistics)에서는 언어가 정보 전달뿐 아니라 관계 형성, 권력 행사, 정체성 표현 같은 사회적 행위를 한다고 본다"],["화행 이론(speech act theory)","오스틴(Austin)이 말이 행위를 수행한다고 주장했다"],["교육 언어학","교실 담화를 이 관점에서 분석한다"]]}],"ebs27dy_g10_1":[{"t":"tree","title":"도덕 기반","root":"도덕 기반 이론(moral foundations theory)","branches":[["도덕 판단","하이트(Haidt)의 이론으로 도덕 판단이 돌봄, 공정, 충성, 권위, 순수 같은 여러 기반에서 나온다고 본다"],["충성(loyalty)","내집단(ingroup)을 지키려는 도덕 직관이다"],["조롱(ridicule) 유머","유머 심리학은 집단 정체성을 강화한다고 분석한다"]]}],"ebs27dy_g10_2":[{"t":"tree","title":"위험 민감 먹이 찾기","root":"행동생태학(behavioral ecology)","branches":[["최적 섭식 이론(optimal foraging theory)","동물이 에너지 이득을 극대화하도록 먹이를 선택한다고 본다"],["위험 민감 이론(risk-sensitive foraging)","동물이 결과의 변동성을 고려해 선택하는지를 다룬다"],["기대 효용(expected utility)","이는 경제학의 개념과 비교된다"]]}],"ebs27dy_g10_3":[{"t":"tree","title":"재현 예술","root":"모방론(mimesis)","branches":[["모방론","예술철학(philosophy of art)에서 예술이 현실을 재현한다고 보는 오랜 입장이다"],["초상화","초상화가 모델과 닮았다는 말이 무엇을 뜻하는지는 오래된 물음이다"],["재현(representation)","미학과 회화론에서 두루 쓰이는 개념이다"]]}],"ebs27dy_g10_4":[{"t":"tree","title":"목격자 증언","root":"엘리자베스 로프터스(Elizabeth Loftus)","branches":[["목격자 증언(eyewitness testimony)","기억의 재구성 때문에 부정확할 수 있음을 밝힌 기억 심리학자다"],["오정보 효과(misinformation effect)","질문 문구에 따라 기억이 변하는 대표적 발견이다"],["신뢰성(reliability)","이 연구는 법정에서 증언의 신뢰성을 평가하는 데 쓰인다"]]}],"ebs27dy_g10_5":[{"t":"tree","title":"수 감각","root":"수 감각(numerosity)","branches":[["정의","동물 인지 연구에서 수량을 어림하고 비교하는 능력이다"],["양 비교(quantity discrimination)","침팬지, 새, 물고기 등 많은 동물이 두 집합 중 더 많은 쪽을 고르는 것으로 보고된다"],["시사","이는 인간의 수학적 능력이 진화적으로 뿌리가 있음을 시사한다"]]}],"ebs27dy_g10_6":[{"t":"tree","title":"수 감각","root":"수 감각(numerosity)","branches":[["정의","동물 인지 연구에서 수량을 어림하고 비교하는 능력이다"],["양 비교(quantity discrimination)","침팬지, 새, 물고기 등 많은 동물이 두 집합 중 더 많은 쪽을 고르는 것으로 보고된다"],["시사","이는 인간의 수학적 능력이 진화적으로 뿌리가 있음을 시사한다"]]}],"ebs27dy_g10_7":[{"t":"tree","title":"자기 조절","root":"자기 조절(self-regulation)","branches":[["자기 조절","충동과 감정을 조절해 목표에 맞게 행동하는 능력이다"],["자아 고갈(ego depletion)","바우마이스터(Baumeister)의 이론으로 자기 통제 능력이 쓰는 만큼 소모되는지를 다루며, 이 효과의 재현성(replicability)에는 논쟁이 있다"],["인지 부하(cognitive load)","유혹에 대한 반응에 어떤 영향을 주는지도 연구되어 왔다"]]}],"ebs27dy_g10_8":[{"t":"tree","title":"기억의 은유","root":"기억의 은유","branches":[["은유","인지심리학에서는 기억을 설명하기 위해 시대마다 다른 은유를 써 왔다"],["신경과학","기억이 뇌에 어떻게 저장되고 인출되는지는 신경과학에서도 연구된다"],["스키마(schema)","바틀릿(Bartlett)은 기억이 스키마의 영향을 받는다는 것을 보였다"]]}],"ebs27dy_g10_9":[{"t":"tree","title":"수용 능력","root":"수용 능력(carrying capacity)","branches":[["정의","생태학에서 환경이 지속적으로 부양할 수 있는 최대 개체 수다"],["결정 요인","먹이, 서식지, 물 같은 자원과 환경 조건에 따라 정해진다"],["로지스틱 성장(logistic growth)","개체군이 이 한계에 가까워지면 성장 속도가 느려지는 모델과 연결된다"]]}],"ebs27dy_g10_10":[{"t":"tree","title":"도덕과 시간","root":"도덕 규칙","branches":[["윤리학","도덕 규칙은 보통 시간과 상관없이 같다고 가정한다"],["도덕 심리학","사람들의 도덕 판단이 상황과 시점에 따라 달라지는지를 실험으로 검증한다"],["심리적 거리(psychological distance)","시간이 멀수록 추상적으로 판단한다는 해석 수준 이론(construal level theory)의 핵심 개념이다"]]}],"ebs27dy_g10_11":[{"t":"tree","title":"학습 잠재력","root":"학습 잠재력(learning potential)","branches":[["정의","교육학에서 앞으로 새로 배울 수 있는 가능성을 가리킨다"],["근접발달영역(ZPD)","비고츠키(Vygotsky)의 개념으로 도움을 받으면 할 수 있는 영역을 뜻하는 이 맥락의 핵심 개념이다"],["역동적 평가(dynamic assessment)","이런 잠재력을 측정하려는 시도이고, 지능의 정의와 측정 방식은 심리학에서 오래 논쟁되어 왔다"]]}],"ebs27dy_g10_12":[{"t":"tree","title":"학습 잠재력","root":"학습 잠재력(learning potential)","branches":[["정의","교육학에서 앞으로 새로 배울 수 있는 가능성을 가리킨다"],["근접발달영역(ZPD)","비고츠키(Vygotsky)의 개념으로 도움을 받으면 할 수 있는 영역을 뜻하는 이 맥락의 핵심 개념이다"],["역동적 평가(dynamic assessment)","이런 잠재력을 측정하려는 시도이고, 지능의 정의와 측정 방식은 심리학에서 오래 논쟁되어 왔다"]]}],"ebs27dy_g11_1":[{"t":"tree","title":"학문의 경계","root":"학문의 범위 정의","branches":[["질문","학문의 범위를 정의하는 일은 과학철학과 학문론에서 중요한 질문이다"],["정의의 문제","정의가 너무 넓으면 관련 없는 것까지 포함하고 너무 좁으면 중요한 것을 놓친다"],["학제 간 연구(interdisciplinary research)","분야 경계를 넘나드는 접근이다"]]}],"ebs27dy_g11_2":[{"t":"tree","title":"심해","root":"심해(deep sea)","branches":[["정의","수심 200m 이하의 햇빛이 거의 닿지 않는 영역으로, 지구 최대의 서식 공간이다"],["해양학","심해의 환경과 생물이 인간 활동과 어떤 관계에 있는지는 해양학에서 연구된다"],["지속 가능성(sustainability)","해양 보전은 이 논의의 일부다"]]}],"ebs27dy_g11_3":[{"t":"tree","title":"동물 감정","root":"동물 감정 연구","branches":[["감수성(sentience)","동물이 고통과 기쁨을 느끼는 감수성을 가진다고 본다"],["케임브리지 선언","2012년 많은 포유류와 조류가 의식의 신경 기반을 가진다고 선언했다"],["처우 기준","이런 인식은 실험실, 농장, 동물원에서의 동물 처우 기준 변화로 이어진다"]]}],"ebs27dy_g11_4":[{"t":"tree","title":"사회과학의 실험법","root":"과학적 방법","branches":[["통제 실험(controlled experiment)","원인과 결과의 관계를 검증하는 대표적 방법이다"],["사회과학","관찰 연구, 사례 연구, 통계 분석 등 여러 방법을 쓴다"],["상관과 인과","상관(correlation)이 곧 인과(causation)는 아니라는 원칙이 중요하다"]]}],"ebs27dy_g11_5":[{"t":"vs","title":"인적 자원 관리 접근","cols":[{"name":"경성 접근","items":["구성원을 비용으로 보고 통제한다"]},{"name":"연성 접근","items":["구성원의 역량과 헌신을 키우려 한다"]}]},{"t":"tree","title":"관광 산업","root":"관광과 접객업(tourism and hospitality)","branches":[["외부 충격","경기 변동(economic cycle), 정치적 불안 같은 외부 충격에 민감한 산업이다"],["항공 산업","노동조합과 경영진의 갈등이 잦은 분야로 알려져 있다"]]}],"ebs27dy_g11_6":[{"t":"vs","title":"인적 자원 관리 접근","cols":[{"name":"경성 접근","items":["구성원을 비용으로 보고 통제한다"]},{"name":"연성 접근","items":["구성원의 역량과 헌신을 키우려 한다"]}]},{"t":"tree","title":"관광 산업","root":"관광과 접객업(tourism and hospitality)","branches":[["외부 충격","경기 변동(economic cycle), 정치적 불안 같은 외부 충격에 민감한 산업이다"],["항공 산업","노동조합과 경영진의 갈등이 잦은 분야로 알려져 있다"]]}],"ebs27dy_g11_7":[{"t":"tree","title":"예측 치안","root":"예측 치안(predictive policing)","branches":[["정의","과거 범죄 데이터를 알고리즘으로 분석해 범죄 위험 지역과 인물을 예측하는 기법이다"],["비판","비판자들은 이 기법의 공정성과 정확성을 문제 삼는다"],["쟁점","알고리즘 공정성(algorithmic fairness)과 투명성(transparency)이 쟁점이다"]]}],"ebs27dy_g11_8":[{"t":"tree","title":"해양 자원과 오염","root":"해양 자원","branches":[["남획(overfishing)","해양 자원은 식량의 중요한 원천이지만 어획 기술 발달로 남획이 심각해졌다"],["폐기물","바다는 폐기물을 버리는 곳으로도 오래 쓰여 왔다"],["양식업(aquaculture)","어족 자원 감소의 대안으로 주목받는다"]]}],"ebs27dy_g11_9":[{"t":"tree","title":"준비된 학습","root":"준비된 학습(prepared learning)","branches":[["정의","셀리그먼(Seligman)이 제안한 개념으로, 생존에 중요했던 자극에 대해 더 쉽게 학습하게 하는 진화적 경향이다"],["예","뱀이나 거미 공포 학습이 쉬운 것이 예로 거론된다"],["밈(meme)","도킨스(Dawkins)가 제안한 문화 전달 단위 개념이다"]]}],"ebs27dy_g11_10":[{"t":"tree","title":"검열","root":"검열(censorship)","branches":[["정의","정부나 종교 등 권위가 표현과 정보의 유통을 통제하는 행위다"],["고전","밀턴(Milton)의 『아레오파지티카』와 밀(Mill)의 『자유론』은 표현의 자유(freedom of expression)를 옹호한 고전이다"],["논쟁","검열이 정당한지는 오랫동안 논쟁되어 왔다"]]}],"ebs27dy_g11_11":[{"t":"tree","title":"과학 교양","root":"과학 교양의 가치","branches":[["두 문화(Two Cultures)","문화 연구에서 C. P. 스노(Snow)가 1959년 강연에서 과학과 인문학 사이의 거리를 다룬 데서 비롯되었다"],["과학적 소양(scientific literacy)","시민이 과학 지식을 이해하고 판단하는 능력이다"],["교양(liberal education)","범위에 과학이 포함되어야 하는가가 오래된 쟁점이다"]]}],"ebs27dy_g11_12":[{"t":"tree","title":"과학 교양","root":"과학 교양의 가치","branches":[["두 문화(Two Cultures)","문화 연구에서 C. P. 스노(Snow)가 1959년 강연에서 과학과 인문학 사이의 거리를 다룬 데서 비롯되었다"],["과학적 소양(scientific literacy)","시민이 과학 지식을 이해하고 판단하는 능력이다"],["교양(liberal education)","범위에 과학이 포함되어야 하는가가 오래된 쟁점이다"]]}],"ebs27dy_g12_1":[{"t":"tree","title":"수행 평가 오류","root":"수행 평가(performance appraisal)","branches":[["평가자 오류(rater error)","인사 관리에서 자주 문제 된다"],["최근성 오류(recency error)","최근 일을 더 크게 반영하는 편향이며 후광 효과(halo effect)와 함께 대표적이다"],["평가 기록(performance log)","작성이 평가자의 판단에 어떤 영향을 주는지도 연구되어 왔다"]]}],"ebs27dy_g12_2":[{"t":"vs","title":"정체성 관리 전략","cols":[{"name":"구획화(compartmentalization)","items":["여러 정체성을 서로 분리해 관리하는 전략"]},{"name":"통합(integration)","items":["섞어 쓰는 전략"]}]},{"t":"tree","title":"다중 정체성","root":"사회심리학의 정체성(identity)","branches":[["다중 정체성","사람은 직업인, 부모, 친구 등 여러 정체성을 동시에 가진다"],["창업자 연구","일과 삶의 경계(boundary) 관리가 스트레스와 몰입에 영향을 준다고 본다"]]}],"ebs27dy_g12_3":[{"t":"vs","title":"노화와 기억","cols":[{"name":"일화 기억(episodic memory)","items":["노화(aging) 연구에서 나이에 따른 기억의 변화를 설명할 때 의미 기억과 차이로 다룬다"]},{"name":"의미 기억(semantic memory)","items":["사실과 지식에 대한 기억이다"]}]}],"ebs27dy_g12_5":[{"t":"tree","title":"공간 정향","root":"공간 정향(spatial orientation)","branches":[["정의","소비자 행동 연구에서 소비자가 매장에서 상품 위치를 파악하고 이동하는 방식이다"],["매장 레이아웃(layout)","진열은 구매 동선과 충동 구매에 영향을 준다"],["인지 지도(cognitive map)","사람이 머릿속에 만든 공간 표상을 뜻한다"]]}],"ebs27dy_g12_6":[{"t":"tree","title":"공간 정향","root":"공간 정향(spatial orientation)","branches":[["정의","소비자 행동 연구에서 소비자가 매장에서 상품 위치를 파악하고 이동하는 방식이다"],["매장 레이아웃(layout)","진열은 구매 동선과 충동 구매에 영향을 준다"],["인지 지도(cognitive map)","사람이 머릿속에 만든 공간 표상을 뜻한다"]]}],"ebs27dy_g12_7":[{"t":"tree","title":"달러화","root":"달러화(dollarization)","branches":[["정의","한 나라가 자국 통화 대신 미국 달러 같은 외국 통화를 공식 통화로 쓰는 것이다"],["사례","에콰도르와 엘살바도르가 대표 사례로 알려져 있다"],["통화 정책(monetary policy)","중앙은행이 금리와 통화량을 조절하는 정책이며, 단일 통화의 장점과 비용은 경제학에서 오래 논의되어 왔다"]]}],"ebs27dy_g12_8":[{"t":"tree","title":"이누이트의 항법","root":"민족과학(ethnoscience)","branches":[["연구","인류학과 민족과학은 전통 사회의 지식 체계를 연구한다"],["이누이트(Inuit)","북극 지역 환경에 맞춘 길 찾기 지식을 발전시켰다"],["천체 항법(celestial navigation)","별의 위치로 방향과 위치를 파악하는 방법이다"]]}],"ebs27dy_g12_9":[{"t":"tree","title":"무리 짓기","root":"무리 짓기","branches":[["이유","행동생태학(behavioral ecology)에서 포유류가 무리 짓는 이유로 포식자 회피, 먹이 확보, 번식이 거론된다"],["비용","사회적 동물은 무리의 이득과 경쟁의 비용을 저울질한다"],["인류학","인간 집단이 갈라져 새 정착지를 이루는 과정도 연구한다"]]}],"ebs27dy_g12_10":[{"t":"tree","title":"기억의 신경 재활성화","root":"신경과학의 기억","branches":[["기억","경험할 때 활성화된 뉴런 패턴이 다시 활성화되는 것으로 설명된다"],["헵(Hebb)의 원리","함께 활성화된 뉴런은 연결이 강해진다는 학습 규칙이다"],["정확성","기억의 정확성은 신경과학과 법심리학에서 중요한 주제다"]]}],"ebs27dy_g12_11":[{"t":"tree","title":"유머의 진화","root":"유머의 진화적 기능","branches":[["진화심리학","웃음과 유머가 왜 진화했는지를 설명하려 한다"],["다윈(Darwin)","『인간과 동물의 감정 표현』에서 웃음의 진화적 기원을 다뤘다"],["영장류","유머와 웃음은 영장류의 놀이 행동과도 비교되어 연구된다"]]}],"ebs27dy_g12_12":[{"t":"tree","title":"유머의 진화","root":"유머의 진화적 기능","branches":[["진화심리학","웃음과 유머가 왜 진화했는지를 설명하려 한다"],["다윈(Darwin)","『인간과 동물의 감정 표현』에서 웃음의 진화적 기원을 다뤘다"],["영장류","유머와 웃음은 영장류의 놀이 행동과도 비교되어 연구된다"]]}],"ebs27dy_m01_3":[{"t":"tree","title":"과학 언어","root":"학술 글쓰기(academic writing)","branches":[["특성","정확성과 객관성이 중요한 글쓰기다"],["인식","과학 글쓰기는 딱딱하고 어렵다는 인식이 널리 퍼져 있으며 전문 용어(jargon)가 낯설게 느껴질 수 있다"],["과학 소통(science communication)","전문 지식을 대중에게 쉽게 전달하는 분야다"]]}],"ebs27dy_m01_6":[{"t":"tree","title":"철학의 하위 분야","root":"철학(philosophy)","branches":[["형이상학(metaphysics)","존재를 묻는다"],["인식론(epistemology)","앎을 묻는다"],["윤리학(ethics)","옳음을 묻는다"]]},{"t":"vs","title":"과학과 철학의 물음","cols":[{"name":"과학","items":["어떻게(how)를 묻는다"]},{"name":"철학","items":["왜(why)와 무엇을 의미하는가를 묻는다","지식 자체뿐 아니라 그 의미와 근거를 묻는 학문이다"]}]}],"ebs27dy_m01_7":[{"t":"tree","title":"몰입형 연극","root":"몰입형 연극(immersive theatre)","branches":[["정의","관객이 관람석에 앉아 보는 대신 공연 공간 안에서 직접 참여하는 연극 형식이다"],["장소 특정적(site-specific) 공연","극장 대신 특정 장소를 무대로 삼는다"],["참여 예술(participatory art)","관객과 배우의 경계를 허문다는 점에서 연결된다"]]}],"ebs27dy_m01_12":[{"t":"tree","title":"부모 투자","root":"부모 투자(parental investment) 이론","branches":[["정의","진화생물학에서 트리버스(Trivers)가 제안한 개념으로, 자손에 쏟는 시간과 에너지의 성별 차이를 설명한다"],["포유류","임신과 수유 때문에 암컷의 투자가 훨씬 큰 편이다"],["인간 남성","양육에 참여하는 점에서 포유류 중 예외적인 편이라고 논의된다"]]}],"ebs27dy_m01_13":[{"t":"vs","title":"감정 노동의 연기","cols":[{"name":"표면 연기(surface acting)","items":["느끼지 않는 감정을 겉으로만 연기한다"]},{"name":"내면 연기(deep acting)","items":["감정 자체를 바꾸려 한다"]}]},{"t":"def","term":"감정 노동(emotional labor)","text":"사회학자 혹실드(Hochschild)가 제안한 개념으로, 직무에서 요구되는 감정을 표현하기 위해 자신의 감정을 관리하는 노동이다. 소진(burnout)과 관련해 연구된다"}],"ebs27dy_m01_15":[{"t":"tree","title":"컴퓨터 보안","root":"정보 보안(information security)","branches":[["사용자 행동","기술뿐 아니라 사용자 행동에 크게 좌우되며, 사용성(usability)과 보안의 균형이 오래된 쟁점이다"],["사용자 교육","흔히 보안 인식 제고(security awareness) 방법이지만 효과가 제한적이라는 연구가 있다"],["배경","사람은 복잡한 위험을 평가하는 데 한계가 있다"]]}],"ebs27dy_m01_16":[{"t":"vs","title":"예술과 과학","cols":[{"name":"예술","items":["주관적(subjective) 활동으로 구분된다"]},{"name":"과학","items":["객관적(objective) 활동으로 구분된다"]}]},{"t":"tree","title":"관계","root":"예술과 과학의 관계","branches":[["논의","철학과 인지과학에서 오래 논의된 주제다"],["이론 의존성(theory-laden observation)","과학철학은 관찰과 이론의 관계를 따지는 개념을 다룬다"]]}],"ebs27dy_m01_17":[{"t":"tree","title":"뉴턴의 과학관","root":"뉴턴(Newton)","branches":[["『프린키피아』","운동 법칙과 만유인력 법칙을 정리했다"],["평가","그의 설명 방식은 당대에 찬사와 비판을 함께 받았다"],["기계론적 세계관(mechanistic worldview)","이 업적은 기계론적 세계관과 연결된다"]]}],"ebs27dy_m01_18":[{"t":"tree","title":"장 면역","root":"장 면역계","branches":[["장 면역계","인체 면역 세포의 상당 부분이 모여 있는 곳으로, 음식물과 미생물을 구별하는 일을 한다"],["장내 미생물(gut microbiota)","소화와 면역 조절을 돕는다"],["면역 관용(immune tolerance)","무해한 물질에는 반응하지 않는 면역의 성질이다"]]}],"ebs27dy_m01_19":[{"t":"cause","title":"프루스트 효과","causes":["후각 정보가 시상을 거치지 않고 변연계(limbic system)로 전달되어 감정, 기억과 밀접함"],"result":"냄새가 특정 기억을 떠올리게 하는 프루스트 효과(Proust effect)","effects":["풍미(flavor)는 맛(taste)과 냄새(smell)가 결합한 감각 경험으로, 후각이 큰 비중을 차지한다"]}],"ebs27dy_m01_20":[{"t":"tree","title":"지위재로서의 교육","root":"지위재(positional good)","branches":[["지위재","경제학에서 가치가 절대적 수준보다 남과의 상대적 순위에 따라 결정되는 재화다"],["신호(signaling)","학력은 취업 시장에서 상대적 우위를 보여 주는 신호로 기능한다고 설명된다"],["학력 인플레이션(credential inflation)","고등교육이 대중화되면 학위의 변별력이 줄어드는 현상이 논의된다"]]}],"ebs27dy_m01_21":[{"t":"tree","title":"조망 효과","root":"조망 효과(overview effect)","branches":[["정의","우주에서 지구를 바라본 우주비행사들이 보고한 경외감과 인류 일체감 같은 인지 변화를 가리킨다"],["프랭크 화이트(Frank White)","이 용어를 대중화했다"],["환경 의식","지구의 취약함과 국경 없는 모습이 환경 의식과 연결된다는 논의가 있다"]]}],"ebs27dy_m01_22":[{"t":"tree","title":"팬덤과 언어 학습","root":"비형식 학습(informal learning)","branches":[["비형식 학습","응용언어학(applied linguistics)에서 학교 밖에서 이루어지는 언어 학습이다"],["팬덤(fandom)","드라마, 음악 등 특정 콘텐츠를 좋아하는 팬 공동체로, 팬들이 원어로 콘텐츠를 즐기며 언어를 익히는 경우가 연구되고 있다"],["관점","이는 학습자의 동기(motivation)와 정체성(identity)이 중요하다는 관점과 연결된다"]]}],"ebs27dy_m01_23":[{"t":"tree","title":"언어의 기원","root":"언어의 기원(origin of language)","branches":[["가설","언어학과 인류학의 미해결 주제로, 제스처 기원설, 사회적 유대설 등 여러 가설이 있다"],["초기 인류","초기 인류의 생활과 인지 능력은 고고학과 인류학에서 연구된다"],["기본 개념","상징(symbol)과 의사소통(communication)은 언어 연구의 기본 개념으로 거론된다"]]}],"ebs27dy_m01_24":[{"t":"flow","title":"의례화","steps":["동물행동학(ethology)에서 지배(dominance)는 개체 간 서열을 나타내는 개념이며 신호(signal)로 표시된다","의도 동작(intention movement)은 행동을 시작하려는 초기 동작이 의사소통 신호로 진화한 것이다","이를 의례화(ritualization)라 하며 실제 공격 없이 서열을 정하게 한다"]}],"ebs27dy_m01_25":[{"t":"flow","title":"의례화","steps":["동물행동학(ethology)에서 지배(dominance)는 개체 간 서열을 나타내는 개념이며 신호(signal)로 표시된다","의도 동작(intention movement)은 행동을 시작하려는 초기 동작이 의사소통 신호로 진화한 것이다","이를 의례화(ritualization)라 하며 실제 공격 없이 서열을 정하게 한다"]}],"ebs27dy_m02_4":[{"t":"tree","title":"빅시드 마케팅","root":"빅시드 마케팅(big-seed marketing)","branches":[["제안","와츠(Watts)와 페레티(Peretti)가 2007년 하버드 비즈니스 리뷰 논문에서 바이럴 마케팅(viral marketing)과 전통 매체 광고를 결합해 제안했다"],["바이럴 마케팅","소비자 간 입소문으로 메시지가 퍼지는 방식이다"],["확산 연구","소수의 영향력 있는 사람(influencer)에 의존하는 모델과 비교한다"]]}],"ebs27dy_m02_5":[{"t":"tree","title":"눈 맞춤과 공감","root":"신경과학·사회 신경과학","branches":[["거울 뉴런(mirror neuron)","타인의 행동을 볼 때 자신이 같은 행동을 할 때처럼 활성화되는 뉴런"],["시뮬레이션 이론(simulation theory)","타인의 감정을 자신의 뇌에서 모의 실행해 이해한다고 본다"],["눈 맞춤과 표정 모방","눈 맞춤(eye contact)과 표정 모방(mimicry)은 사회 신경과학에서 자주 다뤄지는 주제"]]}],"ebs27dy_m02_6":[{"t":"vs","title":"다문화주의와 동화주의","cols":[{"name":"다문화주의(multiculturalism)","items":["소수 집단이 고유한 문화를 유지하면서 평등한 권리를 누려야 한다는 정치, 사회 이념","사회 통합(social cohesion)과 차별 문제와 함께 논의된다"]},{"name":"동화주의(assimilation)","items":["소수가 주류 문화에 흡수되어야 한다고 본다"]}]}],"ebs27dy_m02_7":[{"t":"vs","title":"집중 주의와 확산 주의","cols":[{"name":"집중 주의(focused attention)","items":["한 대상에 정신을 모으는 것"]},{"name":"확산 주의(diffuse attention)","items":["폭넓게 열어 두는 주의 방식","뇌의 기본 모드 네트워크(default mode network)는 몽상과 창의적 연결과 관련된다고 연구된다"]}]},{"t":"def","term":"창의성 연구","text":"집중과 확산 주의의 역할은 창의성 연구에서 다뤄진다"}],"ebs27dy_m02_12":[{"t":"vs","title":"목록화와 지적 통제","cols":[{"name":"목록화(cataloguing)","items":["기록학과 도서관학에서 자료를 기술하고 정리해 찾을 수 있게 하는 작업"]},{"name":"지적 통제(intellectual control)","items":["소장 자료의 내용과 맥락을 파악하고 접근할 수 있도록 하는 관리 개념"]}]},{"t":"def","term":"기록학의 핵심 과제","text":"자료의 보존과 접근"}],"ebs27dy_m02_13":[{"t":"def","term":"생활사(life history)","text":"진화생물학에서 성장, 성숙, 번식 시기 등 생애 전략"},{"t":"cause","title":"포식 압력과 생활사","causes":["포식 압력(predation pressure)"],"result":"생활사 전략에 어떤 영향을 주는지 연구되어 왔다","effects":["레즈닉(Reznick)과 엔들러(Endler)의 Trinidad 섬 구피 연구는 자연선택(natural selection)을 직접 관찰한 사례로 유명"]}],"ebs27dy_m02_14":[{"t":"def","term":"기억 동조(memory conformity)","text":"사회심리학에서 타인이 말한 내용이 자신의 기억에 반영되는 현상"},{"t":"tree","title":"기억 동조의 원인","root":"기억 동조의 원인으로 거론되는 것","branches":[["정보적 영향","정보적 영향(informational influence)"],["규범적 영향","규범적 영향(normative influence)"]]},{"t":"def","term":"설득 연구","text":"정보를 건네는 사람의 특성이 받아들이는 사람에게 어떤 영향을 주는지는 설득 연구의 주제"}],"ebs27dy_m02_15":[{"t":"def","term":"사회적 학습(social learning)","text":"동료를 관찰하거나 상호작용해서 배우는 학습 · 쥐는 동료의 입 냄새로 먹이 정보를 얻는 것으로 알려져 있다"},{"t":"vs","title":"동물 문화와 전통","cols":[{"name":"동물 문화(animal culture)","items":["사회적으로 학습된 행동이 집단에 유지되는 현상"]},{"name":"전통(tradition)","items":["사회적으로 학습되어 집단에 유지되는 행동 양식"]}]}],"ebs27dy_m02_16":[{"t":"cause","title":"혐오의 학습","causes":["아이가 양육자의 말과 반응을 본다"],"result":"무엇이 혐오스러운지 배운다","effects":[]},{"t":"def","term":"혐오(disgust)","text":"심리학에서 오염과 질병을 피하게 하는 진화된 감정 · 언어와 학습의 관계는 행동분석(behavior analysis)과 임상심리에서 다루어진다"}],"ebs27dy_m02_17":[{"t":"def","term":"비형식 학습(informal learning)","text":"정보 시대의 학습 연구에서 학교 밖 또래와 어울리며 일어나는 학습"},{"t":"vs","title":"청소년의 미디어 참여","cols":[{"name":"친구 중심 참여(friendship-driven)","items":["이토 미즈코(Ito) 등이 나눈 청소년 미디어 참여의 한 갈래"]},{"name":"관심 중심 참여(interest-driven)","items":["이토 미즈코(Ito) 등이 나눈 청소년 미디어 참여의 다른 갈래"]}]},{"t":"def","term":"또래 학습(peer learning)","text":"교사 중심 수업과 구조가 다르다"}],"ebs27dy_m02_18":[{"t":"def","term":"웃음(laughter)","text":"놀이 신호(play signal)로 진화했다는 가설이 널리 알려져 있다"},{"t":"def","term":"감정 전염(emotional contagion)","text":"한 사람의 감정 상태가 타인에게 퍼지는 현상 · 웃음의 기능을 설명하는 관점은 여러 가지다"}],"ebs27dy_m02_19":[{"t":"flow","title":"섀넌-위버 모형","steps":["발신자","신호","채널","수신자"]},{"t":"def","term":"잡음(noise)","text":"섀넌-위버 모형(Shannon-Weaver model)에서 신호를 방해하는 것 · 물리적 소음뿐 아니라 심리적, 의미적 방해도 포함 · 이 모형은 정보 이론(information theory)에서 비롯되었다"}],"ebs27dy_m02_20":[{"t":"def","term":"사회적 역할과 자아","text":"사회심리학과 사회학에서 사람은 여러 사회적 역할(role)과 자아를 가진다 · 자아가 안정적인지 상황에 따라 달라지는지는 오래된 논쟁"},{"t":"def","term":"고프먼(Goffman)","text":"일상 속 자기 연출을 연구한 사회학자로 알려져 있다"}],"ebs27dy_m02_21":[{"t":"tree","title":"언어의 구성적 기능","root":"언어와 세계의 관계","branches":[["언어학과 철학","언어가 세계와 어떤 관계를 맺는지가 오래된 물음"],["오스틴(Austin)의 수행적 발화(performative)","말이 행위가 된다는 개념"],["교육","교사의 말투와 표현이 교실 상호작용에 어떤 영향을 주는지 분석"]]}],"ebs27dy_m02_22":[{"t":"flow","title":"과학적 탐구의 역사","steps":["호기심, 관찰, 추론, 실험을 통한 과학의 발전","고대 그리스 철학자들: 자연을 신화 대신 이성으로 설명","근대 과학 혁명(Scientific Revolution): 실험과 수학적 방법을 결합"]}],"ebs27dy_m02_23":[{"t":"flow","title":"에너지 전환","steps":["화석 연료(fossil fuel) 중심 체제","재생에너지(renewable energy) 중심으로 옮겨 가는 과정"]},{"t":"def","term":"에너지 전환의 뒷받침","text":"에너지 전환(energy transition)은 파리협정(Paris Agreement)의 온실가스 감축 목표가 뒷받침 · 속도와 방식은 정책과 기술에 따라 달라진다"}],"ebs27dy_m02_24":[{"t":"tree","title":"미각과 음식 취향","root":"미각 생리학의 기본 맛","branches":[["기본 맛","단맛, 짠맛, 신맛, 쓴맛, 감칠맛(umami)"],["침의 아밀라아제(amylase)","입속에서 녹말을 당으로 분해"],["음식 취향","어떻게 형성되는지는 심리학과 영양학의 주제"]]}],"ebs27dy_m02_25":[{"t":"tree","title":"미각과 음식 취향","root":"미각 생리학의 기본 맛","branches":[["기본 맛","단맛, 짠맛, 신맛, 쓴맛, 감칠맛(umami)"],["침의 아밀라아제(amylase)","입속에서 녹말을 당으로 분해"],["음식 취향","어떻게 형성되는지는 심리학과 영양학의 주제"]]}],"ebs27dy_m03_3":[{"t":"def","term":"통계 문해력(statistical literacy)","text":"위험 소통(risk communication)에서 숫자로 표현된 위험을 이해하는 능력"},{"t":"cause","title":"위험 알리는 형식","causes":["기거렌처(Gigerenzer)가 지적한 문제: 의사와 환자가 상대 위험과 절대 위험, 자연 빈도를 혼동"],"result":"위험을 어떤 형식으로 알리는지가 중요","effects":["환자의 이해와 알 권리와 관련"]}],"ebs27dy_m03_4":[{"t":"tree","title":"기업의 목적과 가치","root":"기업의 목적과 가치","branches":[["비전을 갖춘 기업(visionary company)","짐 콜린스(Jim Collins)와 제리 포라스(Jerry Porras)가 『성공하는 기업들의 8가지 습관』에서 연구"],["기업의 가치관","조직 문화와 직원 몰입에 영향을 준다고 논의"],["주주 이익 극대화론","이와 대비되는 시각으로 거론"]]}],"ebs27dy_m03_5":[{"t":"vs","title":"구성주의와 사회적 구성주의","cols":[{"name":"구성주의(constructivism)","items":["학습자가 경험과 상호작용으로 지식을 구성한다는 교육 이론"]},{"name":"사회적 구성주의(social constructivism)","items":["비고츠키(Vygotsky)의 영향으로 대화와 협력을 강조"]}]},{"t":"def","term":"선개념(preconception)","text":"유아 과학 교육에서 아이가 가진 선개념을 고려한 수업 설계가 중요하다고 본다"}],"ebs27dy_m03_7":[{"t":"def","term":"디지털 전환(digital transformation)","text":"디지털 기술을 이용해 기업의 업무 방식과 비즈니스 모델을 근본적으로 바꾸는 과정"},{"t":"cause","title":"디지털 전환의 성패","causes":["기술","조직과 구성원의 요인"],"result":"디지털 전환의 성패를 좌우한다고 논의","effects":["생산성 향상과 신사업 기회를 줄 수 있다고 알려져 있다"]}],"ebs27dy_m03_12":[{"t":"flow","title":"광고의 연상","steps":["광고가 브랜드와 긍정적 이미지 또는 이점을 반복 연결","연상(association)을 만든다"]},{"t":"def","term":"고전적 조건형성(classical conditioning)","text":"두 자극을 짝지어 하나가 다른 하나의 반응을 일으키게 하는 학습 원리로, 연상의 이론적 배경 · 제품 특징과 편익(benefit)을 연결하는 일은 브랜드 포지셔닝(positioning)의 기본"}],"ebs27dy_m03_13":[{"t":"tree","title":"얕은 지식의 착각","root":"심리학의 착각 개념","branches":[["더닝-크루거 효과(Dunning-Kruger effect)","능력이 낮은 사람이 자신의 능력을 과대평가하는 경향"],["설명 깊이의 착각(illusion of explanatory depth)","안다고 생각하지만 막상 설명하려면 모른다는 점을 깨닫는 현상"],["메타인지(metacognition) 연구","전문성이 쌓일수록 자기 지식의 한계를 어떻게 인식하는지도 주제"]]}],"ebs27dy_m03_14":[{"t":"def","term":"행동경제학(behavioral economics)","text":"사람이 완전히 합리적(rational)이라는 전통 경제학의 가정에 의문을 제기"},{"t":"cause","title":"카너먼과 트버스키의 연구","causes":["카너먼(Kahneman)과 트버스키(Tversky)의 휴리스틱(heuristic)과 편향(bias) 연구"],"result":"인간의 판단이 체계적으로 한계를 가진다고 보였다","effects":["일관성 없는 선호와 즉흥적 결정이 그 사례로 거론"]}],"ebs27dy_m03_15":[{"t":"def","term":"분배 정의(distributive justice)","text":"정치철학에서 재화와 부담을 사회 구성원에게 어떻게 나누는 것이 정당한지를 다룬다"},{"t":"def","term":"롤스(Rawls)","text":"무지의 베일(veil of ignorance)을 통해 공정한 원칙을 도출하려 했다 · 불평등을 도덕적으로 평가하는 논의가 이어져 왔다"}],"ebs27dy_m03_16":[{"t":"vs","title":"전통 매체와 소셜 미디어","cols":[{"name":"전통 매체(traditional media)","items":["정보를 만들고 퍼뜨리는 방식이 소셜 미디어와 다르다"]},{"name":"소셜 미디어","items":["정보를 만들고 퍼뜨리는 방식이 전통 매체와 다르다"]}]},{"t":"def","term":"게이트키핑(gatekeeping)","text":"이 차이를 논의하는 개념 · 미디어의 소유 구조는 미디어 경제학의 주요 주제"}],"ebs27dy_m03_17":[{"t":"def","term":"본능(instinct)","text":"동물행동학에서 학습 없이 나타나는 정형화된 행동"},{"t":"def","term":"로렌츠(Lorenz)와 틴버겐(Tinbergen)","text":"고정 행동 패턴(fixed action pattern)과 신호 자극(sign stimulus)으로 본능을 설명 · 최근에는 본능과 학습이 엄격히 분리되지 않고 상호작용한다는 관점도 있다"}],"ebs27dy_m03_18":[{"t":"vs","title":"동기식과 비동기식 수업","cols":[{"name":"동기식(synchronous) 수업","items":["온라인 교육에서 교사와 학생이 같은 시간에 모여 실시간으로 진행"]},{"name":"비동기식(asynchronous) 수업","items":["각자 시간에 맞춰 자료로 학습"]}]},{"t":"def","term":"원격 교육(distance education)","text":"형태를 이 기준으로 나눈다 · 두 방식은 상호작용과 유연성(flexibility)에서 장단점이 다르다"}],"ebs27dy_m03_19":[{"t":"def","term":"에릭슨(Erikson)","text":"발달심리학에서 인간의 삶을 단계별 발달 과제로 보았다"},{"t":"vs","title":"신체상과 자기개념","cols":[{"name":"신체상(body image)","items":["자신의 몸에 대한 지각과 평가"]},{"name":"자기개념(self-concept)","items":["자신에 대한 믿음의 총체"]}]},{"t":"cause","title":"생애 전환","causes":["결혼, 이혼, 은퇴 같은 생애 전환(life transition)"],"result":"정체성 변화","effects":[]}],"ebs27dy_m03_20":[{"t":"cause","title":"습관(habit)","causes":["특정 맥락의 단서(cue)"],"result":"자동으로 일어나는 반복 행동","effects":["우드(Wood)의 연구가 대표적"]},{"t":"def","term":"맥락","text":"습관 연구에서 장소, 시간, 선행 행동 등으로 정의되어 왔다 · 스마트폰 같은 기술 습관(tech habit)은 새롭게 주목받는 대상"}],"ebs27dy_m03_21":[{"t":"cause","title":"로마 공화정 후기의 사회 불안","causes":["대토지(latifundia)가 늘고 소농(small farmer)이 몰락","부채(debt)로 농민이 토지를 잃고 도시로 이주"],"result":"사회 불안이 커졌다는 해석","effects":["그라쿠스 형제(Gracchi)의 토지 개혁은 이 문제를 다룬 시도"]}],"ebs27dy_m03_22":[{"t":"tree","title":"연상과 추론","root":"사회심리학의 평가","branches":[["연상","사람은 사물과의 연상으로 타인을 평가하곤 한다"],["암묵적 연합(implicit association)","의식 없이 형성되는 연결"],["후광 효과(halo effect)","한 특성이 다른 평가에 번지는 현상"],["『안나 카레니나』","톨스토이의 소설로 이런 인간 심리를 잘 묘사했다고 자주 인용"]]}],"ebs27dy_m03_23":[{"t":"flow","title":"아시아 외환위기","steps":["1997~98년 태국 바트화 폭락","한국, 인도네시아 등으로 번졌다"]},{"t":"cause","title":"외환위기의 핵심 원인","causes":["단기 외화 자금이 급격히 빠져나가는 자본 유출(capital flight)"],"result":"아시아 외환위기(Asian financial crisis)","effects":["외국인 투자자의 행동은 국제 금융 연구의 주제"]}],"ebs27dy_m03_24":[{"t":"def","term":"행동경제학","text":"사람들이 선택을 어떻게 내리는지를 연구한다"},{"t":"def","term":"네거티브 옵션(negative-option) 마케팅","text":"소비자가 거부하지 않으면 자동 가입되는 방식 · 이런 상술은 소비자 보호 규제의 대상이 되기도 한다"}],"ebs27dy_m03_25":[{"t":"def","term":"행동경제학","text":"사람들이 선택을 어떻게 내리는지를 연구한다"},{"t":"def","term":"네거티브 옵션(negative-option) 마케팅","text":"소비자가 거부하지 않으면 자동 가입되는 방식 · 이런 상술은 소비자 보호 규제의 대상이 되기도 한다"}],"ebs27sd_g03_1":[{"t":"def","term":"디지털 플랫폼 노동(platform labour)","text":"업무를 잘게 쪼개 온라인 시장에서 거래한다"},{"t":"tree","title":"일의 외부화 형태","root":"일의 외부화 대표 형태","branches":[["아웃소싱(outsourcing)","기업이 업무 일부를 외부에 맡기는 것"],["오프쇼어링(offshoring)","해외로 이전하는 것"],["크라우드워크(crowdwork)","불특정 다수에게 일을 맡기는 것"]]},{"t":"def","term":"지리적 고착성(geographical stickiness)","text":"경제지리학에서 일이 특정 장소에 묶이는 정도를 설명하는 표현"}],"ebs27sd_g03_2":[{"t":"def","term":"미기후(microclimate)","text":"기후학에서 좁은 지역의 독특한 기후로, 건물, 나무, 수면이 영향을 준다"},{"t":"def","term":"도시열섬(urban heat island)","text":"도시가 주변보다 더운 현상 · 건축과 조경에서는 방풍림, 그늘, 건물 배치로 야외 열적 쾌적성(outdoor thermal comfort)을 높인다"}],"ebs27sd_g03_3":[{"t":"vs","title":"허즈버그의 2요인 이론","cols":[{"name":"위생 요인(hygiene factors)","items":["임금 같은 요인"]},{"name":"동기 요인(motivators)","items":["성취, 인정 같은 요인"]}]},{"t":"def","term":"당근과 채찍(carrot and stick)의 한계","text":"허즈버그(Herzberg)의 2요인 이론(two-factor theory)과 함께, 다니엘 핑크(Daniel Pink)의 『드라이브』(2009)와 알피 콘(Alfie Kohn)의 『보상으로 인한 처벌』(1993)이 지적"}],"ebs27sd_g03_4":[{"t":"def","term":"경로 의존성(path dependence)","text":"경제학과 정치학에서 과거의 선택이 현재의 선택지를 제약한다는 개념"},{"t":"tree","title":"경로 의존성의 사례","root":"경로 의존성 사례","branches":[["QWERTY 자판 배열","폴 데이비드(Paul David, 1985)가 비효율적이어도 굳어진 예로 들었다"],["역사적 제도주의(historical institutionalism)","제도가 과거의 결정에 묶인다고 설명"],["DNA","생물학에서 자연선택이 오랜 세월 쌓은 계통의 기록으로 본다"]]}],"ebs27sd_g03_5":[{"t":"def","term":"인지 부조화(cognitive dissonance, 1957)","text":"레온 페스팅거(Leon Festinger)가 말한 믿음과 행동, 정보가 충돌할 때 느끼는 불편함"},{"t":"cause","title":"인지 부조화와 비판적 사고","causes":["불편을 줄이려는 사람"],"result":"믿음을 고치기보다 반대 증거를 외면하는 경우가 많다","effects":["확증 편향(confirmation bias)과 신념 고수(belief perseverance)가 관련 개념"]}],"ebs27sd_g04_1":[{"t":"def","term":"협력적 경쟁(coopetition)","text":"경영학에서 협력과 경쟁을 동시에 하는 관계 · 브란덴버거와 네일버프(Brandenburger & Nalebuff)가 1996년 책으로 널리 알렸다"},{"t":"vs","title":"게임 이론의 관점","cols":[{"name":"제로섬(zero-sum) 게임","items":["한쪽이 이기면 다른 쪽이 진다"]},{"name":"협력적 경쟁","items":["제로섬 게임이 아니라는 게임 이론(game theory)의 관점과 이어진다"]}]},{"t":"def","term":"스포츠 산업","text":"리그, 구단, 후원사가 얽힌 생태계(ecosystem)로 설명"}],"ebs27sd_g04_2":[{"t":"flow","title":"신석기 혁명","steps":["약 1만 년 전 수렵채집","농경으로 전환(Neolithic Revolution)"]},{"t":"def","term":"가축화, 작물화(domestication)","text":"작물과 가축을 길들이는 일로, 종자 선택과 재배 지식의 축적이었다 · 경제학자 하이에크(Friedrich Hayek)는 1945년 사회의 지식이 분산되어 있다고 논했다"}],"ebs27sd_g04_3":[{"t":"tree","title":"지역 뉴스와 참여 저널리즘","root":"지역 뉴스와 저널리즘","branches":[["뉴스 사막(news desert)","미국에서 지역 신문 폐간으로 지역 뉴스가 사라진 것이 문제"],["공공 저널리즘(public journalism)","1990년대 기자가 시민의 문제를 다루도록 하자는 운동"],["참여 저널리즘(engaged journalism)","시민과 협력해 뉴스를 만드는 접근"]]}],"ebs27sd_g04_4":[{"t":"tree","title":"상대주의와 과학적 객관성","root":"상대주의와 과학적 객관성","branches":[["상대주의(relativism)","인식론에서 모든 견해가 동등하게 타당하다고 보는 입장"],["거짓 균형(false balance)","언론이 근거의 질을 구분하지 않고 양쪽을 같은 비중으로 보도하는 문제"],["반증 가능성(falsifiability)","칼 포퍼(Karl Popper)가 제시한 과학적 주장을 구분하는 기준"]]}],"ebs27sd_g04_5":[{"t":"def","term":"사회불안(social anxiety)","text":"타인의 평가를 두려워하는 불안"},{"t":"def","term":"스포트라이트 효과(spotlight effect)","text":"토머스 길로비치(Thomas Gilovich) 등의 연구(2000)가 보인, 사람들이 자신이 눈에 띄는 정도를 과대평가하는 경향 · 인지행동치료(CBT)는 사고를 점검하고 상황에 점진적으로 노출하게 한다"}],"ebs27sd_g05_1":[{"t":"tree","title":"언어 혁신과 대중음악 가사","root":"영어사와 가사","branches":[["셰익스피어","수많은 어휘와 표현을 처음 쓰거나 널리 퍼뜨린 것으로 평가"],["언어적 혁신(linguistic innovation)","신조어(neologism) 형성과 어휘 확산을 통해 일어난다"],["밥 딜런(Bob Dylan)","2016년 노벨 문학상 수상이 가사를 문학으로 볼 수 있느냐는 논쟁을 일으켰다"]]}],"ebs27sd_g05_2":[{"t":"vs","title":"라자루스와 폴크먼의 대처(coping)","cols":[{"name":"문제 중심 대처(problem-focused)","items":["문제의 원인에 대응"]},{"name":"정서 중심 대처(emotion-focused)","items":["감정을 다룬다"]}]},{"t":"def","term":"통제 소재(locus of control)","text":"결과를 자신이 통제한다고 믿는 정도 · 대침체(Great Recession)는 2007~2009년에 걸친 세계적 경제 위기"}],"ebs27sd_g05_3":[{"t":"tree","title":"건강 정보와 미디어 영향","root":"공중보건과 미디어","branches":[["건강 문해력(health literacy)","건강 정보를 찾아 이해, 활용하는 능력"],["건강 통제 소재(health locus of control)","건강이 자신의 행동에 달렸다는 믿음"],["잘못된 정보(misinformation)","미디어에서 영양 정보를 얻을 때 근거의 질을 가려내기 어려워 퍼질 수 있다"]]}],"ebs27sd_g05_4":[{"t":"def","term":"서번트 리더십(servant leadership)","text":"로버트 그린리프(Robert Greenleaf)가 1970년 에세이에서 제안한 개념으로 리더가 구성원을 섬기는 데서 리더십이 나온다고 본다"},{"t":"vs","title":"리더십의 방식","cols":[{"name":"솔선수범(leading by example)","items":["말보다 행동으로 모범을 보이는 방식"]},{"name":"위계적 지시 중심의 리더십","items":["서번트 리더십과 대비된다"]}]}],"ebs27sd_g05_5":[{"t":"tree","title":"자율신경계","root":"자율신경계(autonomic nervous system)","branches":[["교감신경(sympathetic)","투쟁-도피 반응과 각성을 일으킨다"],["부교감신경(parasympathetic)","이완을 돕는다 · 느리고 깊은 복식 호흡(diaphragmatic breathing)이 부교감 활동을 높이고 심박 변이도(heart rate variability)를 개선한다고 알려져 있다"]]}],"ebs27sd_g06_1":[{"t":"cause","title":"대중교통 계획의 체감 시간","causes":["배차 간격(headway)과 운행 빈도(frequency)","이동 시간과 기다리는 시간(waiting time)을 합쳐 체감"],"result":"속도 못지않게 중요","effects":["배차가 잦으면 시간표를 보지 않고도 이용할 수 있어 접근성(accessibility)이 높아진다"]},{"t":"def","term":"교통계획의 쟁점","text":"빈도와 넓은 노선망 중 무엇을 우선하느냐"}],"ebs27sd_g06_2":[{"t":"def","term":"시민권","text":"시민권 이론에서 법적 지위, 권리, 정체성으로 나누어 본다"},{"t":"tree","title":"시민권과 거주자","root":"외국인 참정권(alien suffrage)","branches":[["외국인 참정권","시민이 아닌 거주자의 투표권 문제"],["데니즌십(denizenship)","토마스 함마르(Tomas Hammar)가 말한, 영주권자처럼 시민 아니지만 안정적 권리를 가진 지위"],["배타적 시민권(exclusionary citizenship)","구성원 자격을 엄격히 제한하는 관점"]]}],"ebs27sd_g06_3":[{"t":"tree","title":"추상표현주의와 의미 부여","root":"현대미술","branches":[["추상표현주의(Abstract Expressionism)","2차 세계대전 후 미국에서 잭슨 폴록(Jackson Pollock) 등이 이끈 회화 운동"],["일상 사물을 전시 공간에 놓는 시도","마르셀 뒤샹(Marcel Duchamp)의 「샘」(1917)이 대표적"],["미술관, 화랑","이런 제도는 미술사의 주요 연구 대상"]]}],"ebs27sd_g06_4":[{"t":"flow","title":"인지 혁명","steps":["1950년대 인지 혁명(cognitive revolution): 행동주의(behaviorism)를 대신해 마음의 내적 처리 과정 연구","정보 처리 모형(information-processing model): 마음을 컴퓨터에 비유","체화 인지(embodied cognition)와 신경과학: 이 비유의 한계를 지적"]}],"ebs27sd_g06_5":[{"t":"tree","title":"문학과 상상력","root":"문학과 마음","branches":[["마음 이론(theory of mind)과 공감","심리학자 키스 오틀리(Keith Oatley)가 소설 읽기가 이를 높인다는 연구를 해 왔다"],["서사 몰입(narrative transportation)","이야기에 빠져 현실을 잊는 경험"],["가능 세계(possible worlds)","허구가 대안적 세계를 탐색하는 방식을 설명"]]}],"ebs27sd_g07_1":[{"t":"def","term":"culturtainment","text":"문화(culture)와 오락(entertainment)을 합친 말로 문화유산, 공연, 축제를 관광 상품으로 만드는 흐름"},{"t":"cause","title":"문화 관광(cultural tourism)","causes":["문화 관광"],"result":"지역 경제에 도움을 주지만 상품화(commodification) 비판도 따른다","effects":["진정성(authenticity)을 어떻게 보느냐가 학계의 논쟁점"]}],"ebs27sd_g07_2":[{"t":"def","term":"의도적 연습(deliberate practice)","text":"심리학자 안데르스 에릭슨(K. Anders Ericsson)이 1993년 연구에서 전문가가 되는 데에 중요하다고 밝힌 것"},{"t":"def","term":"1만 시간의 법칙(10,000-hour rule)","text":"말콤 글래드웰(Malcolm Gladwell)이 『아웃라이어』(2008)에서 대중화 · 에릭슨은 이 단순화를 비판했다"}],"ebs27sd_g07_3":[{"t":"vs","title":"문화 차원 이론","cols":[{"name":"개인주의(individualism)","items":["헤이르트 호프스테더(Geert Hofstede)의 문화 차원 이론(cultural dimensions)이 구분"]},{"name":"집단주의(collectivism)","items":["헤이르트 호프스테더의 문화 차원 이론이 구분"]}]},{"t":"def","term":"현지화(localization)","text":"국제 마케팅에서 광고와 제품을 현지에 맞게 바꾸는 것 · '생각은 세계적으로 행동은 지역적으로'(think global, act local)라는 표현이 쓰인다"}],"ebs27sd_g07_4":[{"t":"tree","title":"건축 스케치와 컴퓨터","root":"건축 설계 도구","branches":[["손 스케치(freehand sketch)","건축에서 아이디어를 빠르게 탐색하는 도구"],["성찰적 대화(reflective conversation)","도널드 쇤(Donald Schön)이 설계자가 스케치와 나눈다고 설명"],["캐드(CAD)와 건물정보모델링(BIM)","설계 도구를 디지털로 바꾸었다"]]}],"ebs27sd_g07_5":[{"t":"vs","title":"풀 애니메이션과 제한 애니메이션","cols":[{"name":"풀 애니메이션(full animation)","items":["디즈니(Walt Disney)처럼 매끄러운 움직임을 위해 많은 그림을 그린다","토머스와 존스턴(Thomas & Johnston)의 『The Illusion of Life』(1981)는 디즈니 애니메이션의 12가지 원칙을 정리"]},{"name":"제한 애니메이션(limited animation)","items":["1940~50년대 UPA와 이후 한나-바베라(Hanna-Barbera)가 움직임을 줄여 비용을 낮추었다"]}]}],"ebs27sd_g11_1":[{"t":"cause","title":"누적적 문화","causes":["사회적 학습(social learning)으로 쌓이는 지식이 세대를 거쳐 전달"],"result":"개인이 혼자 발명하기 어려운 수준에 이른다","effects":["이런 누적적 문화(cumulative culture)는 집단 두뇌(collective brain)라는 비유로도 설명"]},{"t":"def","term":"문화적 학습(cultural learning)","text":"인류학자 조지프 헨릭(Joseph Henrich)이 『성공의 비밀』(2016)에서 누적적 문화와 함께 논했다"}],"ebs27sd_g11_2":[{"t":"tree","title":"은유와 학습","root":"은유와 학습","branches":[["은유","조지 레이코프와 마크 존슨(Lakoff & Johnson)의 『삶으로서의 은유』(1980)는 은유가 추상 개념을 이해하는 기본 사고 방식이라고 주장"],["은유와 유추(analogy)","교육학에서 낯선 개념을 익숙한 대상에 비유해 설명하는 학습 전략"]]}],"ebs27sd_g11_3":[{"t":"vs","title":"환경 정책의 접근","cols":[{"name":"개혁주의(reformist) 접근","items":["시장 기구를 유지하면서 외부효과(externality)를 내부화하려 한다","녹색 성장(green growth): 성장과 환경 보호가 함께 가능하다고 본다"]},{"name":"탈성장(degrowth)","items":["성장 자체를 줄여야 한다고 주장"]}]},{"t":"def","term":"생태경제학(ecological economics)","text":"경제를 생태계의 하위 체계로 본다"}],"ebs27sd_g11_4":[{"t":"tree","title":"인종 개념과 유전적 변이","root":"인종 개념","branches":[["생물학적 인종 개념","과학적 근거가 약하다는 것이 현대 유전학의 입장"],["리처드 르원틴(Richard Lewontin)","1972년 인간 유전적 변이의 대부분이 집단 내부에 있음을 보였다"],["사회학","인종을 사회적 구성물(social construct)로 본다"],["인간 게놈 프로젝트(Human Genome Project)","사람 사이의 유전적 차이가 매우 작음을 보였다"]]}],"ebs27sd_g11_5":[{"t":"cause","title":"포션 왜곡과 비만","causes":["식당 1인분 크기(portion size)가 커지는 포션 왜곡(portion distortion)"],"result":"비만 증가와 관련","effects":["영양 연구가 관련성을 지적"]},{"t":"vs","title":"식사량 관련 개념","cols":[{"name":"단위 편향(unit bias)","items":["한 접시나 한 봉지를 적정량으로 여기는 경향"]},{"name":"비만 유발 환경(obesogenic environment)","items":["고열량 음식 접근이 쉬운 환경"]}]}],"ebs27sd_g12_1":[{"t":"def","term":"상황 윤리(situational ethics)","text":"신학자 조지프 플레처(Joseph Fletcher)가 1966년 책으로 널리 알린 이론"},{"t":"vs","title":"윤리학의 구별","cols":[{"name":"결과주의(consequentialism)","items":["행위의 결과를 중시"]},{"name":"의무론(deontology)","items":["규칙, 의무를 중시"]}]},{"t":"vs","title":"도덕적 기준","cols":[{"name":"도덕적 절대주의(moral absolutism)","items":["절대적 기준이 있다고 본다"]},{"name":"상대주의(relativism)","items":["문화, 상황에 따라 다르다고 본다"]}]}],"ebs27sd_g12_2":[{"t":"cause","title":"이타적 처벌과 협력","causes":["비용을 감수하고 규칙 위반자를 처벌하는 이타적 처벌(altruistic punishment)"],"result":"협력이 유지된다고 진화 심리학에서 본다","effects":["페르와 게흐터(Fehr & Gächter, 2002)의 공공재 실험이 이를 보여 주었다"]},{"t":"def","term":"확약 장치(commitment device)","text":"토머스 셸링(Thomas Schelling)의 개념으로 미래의 행동을 스스로 묶어 두는 수단"}],"ebs27sd_g12_3":[{"t":"tree","title":"자연 선호 편향","root":"자연성 선호","branches":[["자연성 편향(naturalness bias)","심리학자 폴 로진(Paul Rozin)이 연구한, 사람들이 자연스러운 것을 더 선호하는 경향"],["자연에의 호소(appeal to nature)","자연스러우면 좋다는 논리적 오류"],["진화 심리학","음식 선택이 독성 회피와 신기 공포(neophobia)로 형성되었다고 설명"]]}],"ebs27sd_g12_4":[{"t":"vs","title":"약과 식이보충제","cols":[{"name":"약(drug)","items":["임상시험(clinical trial)을 거쳐야 한다"]},{"name":"식이보충제(dietary supplement)","items":["미국에서는 1994년 식이보충제 건강교육법(DSHEA)에 따라 시판 전 효능, 안전성 승인을 받지 않는다","질병을 치료한다고 표시할 수 없다"]}]},{"t":"def","term":"플라세보 효과(placebo effect)","text":"플라세보 효과와 구분해 효능을 평가해야 한다"}],"ebs27sd_g12_5":[{"t":"vs","title":"로젠블랫의 독서 구분","cols":[{"name":"도구적 읽기(efferent reading)","items":["루이스 로젠블랫(Louise Rosenblatt, 1978)이 구분한, 정보를 얻기 위한 읽기"]},{"name":"심미적 읽기(aesthetic reading)","items":["경험 자체를 음미하는 읽기"]}]},{"t":"def","term":"문학 읽기","text":"문학은 반복해서 읽을 때 새로운 의미를 낳는다 · 면밀한 읽기(close reading)는 문학 연구의 기본 방법"}],"ebs27sd_g13_1":[{"t":"cause","title":"곡물 거래의 이윤","causes":["지역 간 가격 차이를 이용하는 차익거래(arbitrage)"],"result":"곡물 거래는 가격 변동이 큰 상품 거래(commodity trading)의 대표적 분야에서 이윤의 원천이 된다","effects":["20세기에는 카길(Cargill) 등 소수의 대형 곡물 업체가 국제 시장에서 큰 비중을 차지"]},{"t":"def","term":"정보 비대칭(information asymmetry)","text":"경제학에서 거래 당사자 중 한쪽이 더 많은 정보를 가진 상황"}],"ebs27sd_g13_2":[{"t":"tree","title":"아리스토텔레스의 네 가지 원인","root":"아리스토텔레스(Aristotle)가 『자연학』에서 설명한 사물의 원인","branches":[["질료인(material cause)","사물의 원인의 하나"],["형상인(formal cause)","사물의 원인의 하나"],["작용인(efficient cause)","사물의 원인의 하나"],["목적인(final cause)","사물의 원인의 하나"]]},{"t":"def","term":"목적론(teleology)","text":"자연이 목적을 위해 작용한다는 관점 · 엠페도클레스(Empedocles)는 우연한 결합 중 살아남는 것만 남는다는 자연선택과 닮은 설명을 제시"}],"ebs27sd_g13_3":[{"t":"tree","title":"창의적 사고의 측정","root":"토런스(E. P. Torrance)의 창의성 측정","branches":[["유창성(fluency)","창의적 사고의 측정 요소"],["융통성(flexibility)","창의적 사고의 측정 요소"],["독창성(originality)","창의적 사고의 측정 요소"]]},{"t":"def","term":"브레인스토밍(brainstorming)","text":"알렉스 오스본(Alex Osborn)이 1953년 대중화한 집단 발상 기법 · 집단에서는 한 사람씩 말해야 하는 생산 차단(production blocking)이 발상을 줄일 수 있다 · 생성형 AI는 많은 아이디어를 빠르게 낸다"}],"ebs27sd_g13_4":[{"t":"def","term":"내수용 감각(interoception)","text":"심장 박동, 호흡, 배고픔 같은 몸 내부 상태를 느끼는 감각"},{"t":"def","term":"신체 표지 가설(somatic marker hypothesis)","text":"안토니오 다마지오(Antonio Damasio)가 제시한, 몸의 신호가 의사결정과 감정에 영향을 준다는 가설"},{"t":"def","term":"감정표현불능증(alexithymia)","text":"감정을 몸 감각으로 인식하기 어려운 상태"}],"ebs27sd_g13_5":[{"t":"vs","title":"기술에 대한 입장","cols":[{"name":"기술 낙관론(techno-utopianism)","items":["기술철학에서 비관론과 맞선다"]},{"name":"비관론","items":["엘륄과 하이데거는 기술이 인간을 지배할 수 있다는 비판을 제기, 이를 기술 결정론(technological determinism)이라 한다"]}]},{"t":"tree","title":"기술 비판의 논자","root":"기술철학의 저작","branches":[["마셜 매클루언(Marshall McLuhan)","『미디어의 이해』(1964)에서 '매체가 메시지다'(the medium is the message)라고 주장"],["자크 엘륄(Jacques Ellul)","『기술 사회』(1954)"],["하이데거(Heidegger)","「기술에 대한 물음」"]]}],"ebs27sd_g14_1":[{"t":"vs","title":"건축주와 사용자","cols":[{"name":"건축주(client)","items":["건물을 사 주는 사람"]},{"name":"사용자(user)","items":["실제로 쓰는 사람, 건축주와 다를 수 있다"]}]},{"t":"vs","title":"참여 설계와 사후 사용 평가","cols":[{"name":"참여 설계(participatory design)","items":["사용자를 설계 과정에 참여시키는 방식"]},{"name":"사후 사용 평가(post-occupancy evaluation)","items":["건물이 지어진 뒤 사용자 만족도와 성능을 점검하는 절차"]}]}],"ebs27sd_g14_2":[{"t":"def","term":"상호주관성(intersubjectivity)","text":"현상학과 사회심리학에서 서로 다른 주관이 의미를 공유하는 것"},{"t":"vs","title":"공유 개념","cols":[{"name":"공통 기반(common ground)","items":["허버트 클라크(Herbert Clark)의 개념으로 대화자들이 공유한다고 믿는 지식"]},{"name":"공유된 현실(shared reality)","items":["에드워드 토리 히긴스(E. Tory Higgins)의 개념으로 타인과 같은 경험을 공유한다는 느낌"]}]}],"ebs27sd_g14_3":[{"t":"cause","title":"『실험실 생활』","causes":["브뤼노 라투르(Bruno Latour)와 스티브 울가(Steve Woolgar)가 샐크 연구소(Salk Institute) 실험실을 민족지로 연구"],"result":"과학적 사실이 사회적 협상으로 구성된다고 주장","effects":["『실험실 생활』(Laboratory Life, 1979)"]},{"t":"tree","title":"이후 흐름","root":"실험실 연구 이후","branches":[["행위자-네트워크 이론(actor-network theory)","이후 라투르가 발전"],["과학지식사회학(sociology of scientific knowledge)","이런 접근을 포괄"]]}],"ebs27sd_g14_4":[{"t":"flow","title":"지휘의 역사","steps":["지휘(conducting): 합주를 조율하는 일, 가믈란 같은 전통 음악에도 신호를 주는 지도자가 있었다","17~18세기 유럽: 하프시코드 연주자나 악장이 이끌었다","19세기: 막대로 지휘하는 전문 지휘자가 정착"]},{"t":"def","term":"합주 조율(ensemble coordination)","text":"박(beat)과 템포(tempo)를 공유하는 데 달려 있다"}],"ebs27sd_g14_5":[{"t":"tree","title":"스키마와 배경지식","root":"독해와 배경지식","branches":[["스키마 이론(schema theory, 1932)","바틀릿(Frederic Bartlett)이 제시한, 새 정보가 기존 지식 틀에 맞춰 이해된다는 이론"],["『문화적 소양』(1987)","E. D. 허시(E. D. Hirsch)가 공유된 배경지식이 독해에 중요하다고 주장"],["야구 지문 연구","레흐트와 레슬리(Recht & Leslie, 1988)가 독해와 배경지식의 관계를 연구"]]}],"ebs27sd_g15_2":[{"t":"tree","title":"운동 심리와 정서","root":"운동 심리학","branches":[["즐거움(enjoyment)","운동 지속(exercise adherence)과 관련된다고 본다"],["정서 반응(affective response)","운동 중 느끼는 정서 반응이 이후 참여를 예측한다는 연구도 있다"],["지도자의 정서","정서 전염(emotional contagion)을 통해 참여자에게 전해질 수 있다"]]}],"ebs27sd_g15_3":[{"t":"vs","title":"정밀도와 정확도","cols":[{"name":"정밀도(precision)","items":["반복 측정값의 일관성"]},{"name":"정확도(accuracy)","items":["참값과의 가까움"]}]},{"t":"def","term":"유효숫자(significant figures)","text":"측정값은 눈금을 읽을 수 있는 한 자리 아래까지 추정하여 나타낸다 · 측정 불확실성(measurement uncertainty)은 이런 한계를 나타낸다"}],"ebs27sd_g15_4":[{"t":"def","term":"추상화(abstraction)","text":"수학에서 구체적 대상들의 공통 구조를 뽑아 일반적으로 다루는 일 · 집합과 군(group) 같은 구조 개념이 대표적 · 범주론(category theory)은 대상 사이의 관계를 일반화하는 현대 수학"},{"t":"def","term":"일반화(generalization)","text":"구체적 사례를 일반화하는 능력이 수학 학습의 핵심"}],"ebs27sd_g15_5":[{"t":"vs","title":"플라세보 효과와 노세보 효과","cols":[{"name":"플라세보 효과(placebo effect)","items":["효능 없는 처치도 믿음 때문에 증상이 호전되는 현상","공개 플라세보(open-label placebo): 테드 카프척(Ted Kaptchuk)은 2010년 과민성 대장 증후군 환자에게 가짜 약임을 알려 주고 주었는데도 호전되었음을 보고"]},{"name":"노세보 효과(nocebo effect)","items":["해로운 기대가 낳는 효과"]}]}],"ebs27sd_g16_1":[{"t":"def","term":"시계","text":"물리학에서 일정한 주기로 반복되는 진동 과정, 곧 진동자(oscillator)를 세는 장치 · 컴퓨터 안의 클럭(clock)도 같은 원리로 연산의 박자를 맞춘다","ex":["진자, 수정 진동자, 원자의 진동"]},{"t":"def","term":"초(second)","text":"1967년부터 세슘-133 원자의 특정 진동 횟수로 정의"}],"ebs27sd_g16_2":[{"t":"def","term":"과학 논문의 구조","text":"보통 서론, 방법, 결과, 논의(IMRaD) 구조로 쓰이며, 실제 연구 과정의 시행착오를 정리한 재구성된 서사"},{"t":"cause","title":"과학 논문은 사기인가?","causes":["피터 메더워(Peter Medawar)의 1963년 글"],"result":"논문이 사고 과정을 정직하게 반영하지 않는다고 지적","effects":[]},{"t":"def","term":"가설 주도 연구(hypothesis-driven research)","text":"가설을 세워 검증하는 방식"}],"ebs27sd_g16_3":[{"t":"def","term":"지각 항상성(perceptual constancy)","text":"시각 심리학에서 조명이 바뀌어도 물체의 색, 크기를 일정하게 지각하는 능력"},{"t":"flow","title":"무의식적 추론의 발전","steps":["헬름홀츠(Helmholtz)의 무의식적 추론(unconscious inference): 뇌가 불확실한 감각 입력을 경험으로 해석","오늘날의 베이즈 뇌(Bayesian brain) 가설로 발전"]}],"ebs27sd_g16_4":[{"t":"flow","title":"식민지 국경","steps":["식민 시기 유럽 열강: 현지 사정을 무시하고 직선 국경을 그었다","1884~85년 베를린 회의(Berlin Conference): 아프리카 분할을 제도화","이집트와 수단의 1899년, 1902년 국경 차이: 비르 타윌(Bir Tawil)은 어느 나라도 주장하지 않는 땅"]},{"t":"def","term":"무주지(terra nullius)","text":"어느 나라도 주장하지 않는 땅"}],"ebs27sd_g16_5":[{"t":"def","term":"준거 집단(reference group)","text":"사회학에서 자신을 평가하는 기준으로 삼는 집단 · 하이먼(Herbert Hyman)이 1942년 개념을 도입했고 머튼(Merton)이 발전"},{"t":"tree","title":"집단 구분과 박탈감","root":"준거 집단과 비교","branches":[["내집단(in-group)","구분되는 집단"],["외집단(out-group)","내집단과 구분되는 집단"],["상대적 박탈감(relative deprivation)","준거 집단과 비교해 느끼는 불만"]]}],"ebs27sd_g16_6":[{"t":"tree","title":"게슈탈트 집단화 원리","root":"게슈탈트 심리학(Gestalt psychology)의 집단화 원리(grouping principles)","branches":[["근접성(proximity)","막스 베르트하이머(Max Wertheimer, 1923) 등이 정리"],["유사성(similarity)","막스 베르트하이머 등이 정리"],["연속성(continuity)","막스 베르트하이머 등이 정리"]]},{"t":"def","term":"청각 장면 분석(auditory scene analysis, 1990)","text":"앨버트 브레그먼(Albert Bregman)이 소리에도 비슷한 원리가 적용된다고 보았다"}],"ebs27sd_g16_7":[{"t":"def","term":"공공재(public goods)","text":"비배제성(non-excludable)과 비경합성(non-rival)을 지닌 재화"},{"t":"cause","title":"시장 실패","causes":["무임승차(free-rider) 문제"],"result":"시장이 충분히 공급하지 못해 시장 실패(market failure)","effects":[]},{"t":"def","term":"생태계 서비스(ecosystem services)","text":"습지처럼 생태계가 주는 혜택 · 경제적 가치 평가(valuation)가 논의"}],"ebs27sd_g17_1":[{"t":"vs","title":"이야기와 통계","cols":[{"name":"이야기","items":["사람들이 통계보다 이야기에 더 쉽게 설득된다고 심리학에서 설명","개별 사례에 근거한 일화적 증거(anecdotal evidence)는 쉽게 기억되지만 대표성이 부족할 수 있다"]},{"name":"서사 오류(narrative fallacy)","items":["탈레브(Nassim Taleb)가 말한, 우연한 사건에 이야기를 덧붙여 인과로 해석하는 경향"]}]},{"t":"def","term":"틀 짜기(framing)","text":"같은 정보도 틀 짜기에 따라 다르게 받아들여진다"}],"ebs27sd_g17_2":[{"t":"vs","title":"딥 워크와 얕은 작업","cols":[{"name":"깊은 몰입 작업(deep work)","items":["칼 뉴포트(Cal Newport)가 2016년 『딥 워크』에서 구분한, 방해 없이 인지 능력을 한계까지 쓰는 작업"]},{"name":"얕은 작업(shallow work)","items":["메시지 확인 같은 작업"]}]},{"t":"def","term":"몰입(flow)","text":"칙센트미하이(Csikszentmihalyi)의 몰입과도 관련 · 지식 노동에서는 집중의 희소성이 경쟁력이 된다고 주장"}],"ebs27sd_g17_3":[{"t":"def","term":"상징적 상호작용론(symbolic interactionism)","text":"사회학에서 조지 허버트 미드(Mead)에 기원을 두고 허버트 블루머(Herbert Blumer, 1969)가 체계화 · 사람은 상징에 부여한 의미에 따라 행동한다"},{"t":"def","term":"상황 정의(definition of the situation)","text":"W. I. 토머스(Thomas, 1928)의 개념으로 사람이 어떤 상황을 현실로 정의하면 결과도 현실이 된다"}],"ebs27sd_g17_4":[{"t":"def","term":"우울증(major depressive disorder)","text":"지속적인 슬픔과 흥미 상실이 특징인 정신질환으로 DSM-5로 진단 · 평생 유병률은 상당히 높다"},{"t":"def","term":"반추(rumination)","text":"같은 부정적 생각을 되풀이해 우울을 오래 끈다 · 진화 관점에서는 우울이 어떤 기능을 했는지 논쟁이 있다"}],"ebs27sd_g17_5":[{"t":"def","term":"유비(analogy)","text":"철학에서 비슷한 점을 근거로 설명하거나 논증하는 방식"},{"t":"tree","title":"유비의 예와 논증","root":"유비","branches":[["태양의 비유(sun analogy)","플라톤(Plato)이 『국가』에서 선의 이데아를 태양에 비유"],["유비 논증(argument from analogy)","두 대상의 유사성이 결론을 정당화하는지 따진다"]]}],"ebs27sd_g17_6":[{"t":"def","term":"직무 회복(recovery from work)","text":"산업 심리학에서 업무 스트레스 후 심신 상태를 원래대로 되돌리는 과정"},{"t":"cause","title":"장기 노력-회복 모형","causes":["일의 부담"],"result":"회복 시간을 통해 해소된다고 본다(effort-recovery model, Meijman & Mulder, 1998)","effects":[]},{"t":"def","term":"심리적 분리(psychological detachment)","text":"퇴근 후 일 생각에서 벗어나는 것"}],"ebs27sd_g17_7":[{"t":"def","term":"외상 후 성장(post-traumatic growth)","text":"심리학에서 테데스키와 캘훈(Tedeschi & Calhoun, 1996)이 제시한, 시련 뒤 삶의 의미가 깊어지는 변화"},{"t":"tree","title":"의미와 실존","root":"시련과 의미 있는 삶","branches":[["로고테라피(logotherapy)","빅터 프랭클(Viktor Frankl)이 『죽음의 수용소에서』(1946)에서 제안한 의미 중심 치료"],["실존주의(existentialism)","사르트르(Sartre)가 대표"]]}],"ebs27sd_g18_1":[{"t":"def","term":"현장성(liveness)","text":"공연예술(performing arts)에서 배우와 관객이 같은 시간과 공간에 있다는 특징"},{"t":"tree","title":"현장성 논의","root":"공연예술 논의","branches":[["매체화(mediatization)","필립 아우슬랜더(Philip Auslander)가 녹화, 방송 같은 매체화와 라이브를 대비해 현장성을 논의"],["아우라(aura)","벤야민(Walter Benjamin)은 복제 시대에 작품의 아우라가 약해진다고 보았다"],["기호학(semiotics)","공연을 시간과 공간 속에서 펼쳐지는 기호로 분석"]]}],"ebs27sd_g18_2":[{"t":"def","term":"물건에 대한 애착","text":"심리학자 칙센트미하이(Csikszentmihalyi)와 로치버그홀턴(Rochberg-Halton)이 『물건의 의미』(1981)에서 사람이 오래 쓴 물건에 정서적 애착을 갖는다고 분석"},{"t":"vs","title":"내구재와 계획적 노후화","cols":[{"name":"내구재(durable goods)","items":["오래 쓰는 재화"]},{"name":"계획적 노후화(planned obsolescence)","items":["일부러 수명을 줄이는 것"]}]},{"t":"def","term":"수리할 권리(right to repair)","text":"소비자가 직접 고쳐 쓸 권리"}],"ebs27sd_g18_3":[{"t":"cause","title":"위기 상황의 출처","causes":["재난 때"],"result":"사람들이 신뢰할 수 있는 출처에 의존한다고 위기 커뮤니케이션(crisis communication) 연구는 본다","effects":["출처 신뢰도(source credibility)는 전문성과 신뢰성에 좌우"]},{"t":"def","term":"인포데믹(infodemic)","text":"세계보건기구(WHO)가 2020년 가짜 정보가 넘치는 상황을 이렇게 불렀다"}],"ebs27sd_g18_4":[{"t":"def","term":"초점(focal point)","text":"토머스 셸링(Thomas Schelling)이 『갈등의 전략』(1960)에서 말한, 서로 소통하지 못해도 사람들이 같은 선택에 모이게 하는 눈에 띄는 기준"},{"t":"def","term":"조정 게임(coordination game)","text":"여러 균형(multiple equilibria)이 있고, 작은 계기가 어느 균형으로 갈지를 정한다 · 티핑 포인트(tipping point)는 작은 변화가 큰 변화를 낳는 지점"}],"ebs27sd_g18_5":[{"t":"tree","title":"당연시되는 현재","root":"당연시되는 현재와 문화적 배경","branches":[["에피스테메(episteme)","푸코(Foucault)의 개념으로 한 시대가 당연하게 여기는 지식의 틀"],["현재주의(presentism)","역사학에서 과거를 현재의 기준으로 평가하는 오류"],["영화","만들어진 시대의 가치관이 드러나는 문화적 기록으로 읽히며, 시간이 지나면 낯설어 보이는 부분이 생긴다"]]}],"ebs27sd_g19_1":[{"t":"def","term":"복식사(history of dress)","text":"옷의 변천을 연구하지만 직물 조각은 남아도 완전한 의복은 드물어 연속적 증거를 얻기 어렵다"},{"t":"tree","title":"복식사의 자료와 방법","root":"복식사 연구","branches":[["시각 자료(visual sources)","회화, 조각, 문헌이 직물 연구와 함께 쓰인다"],["사료 비판(source criticism)","그런 자료가 얼마나 믿을 만한지 따지는 역사학의 기본 방법"]]}],"ebs27sd_g19_2":[{"t":"def","term":"복식사(history of dress)","text":"옷의 변천을 연구하지만 직물 조각은 남아도 완전한 의복은 드물어 연속적 증거를 얻기 어렵다"},{"t":"tree","title":"복식사의 자료와 방법","root":"복식사 연구","branches":[["시각 자료(visual sources)","회화, 조각, 문헌이 직물 연구와 함께 쓰인다"],["사료 비판(source criticism)","그런 자료가 얼마나 믿을 만한지 따지는 역사학의 기본 방법"]]}],"ebs27sd_g19_3":[{"t":"cause","title":"옷 뜯어 다시 짓기","causes":["산업화 이전 직물이 비싸고 노동은 상대적으로 쌌다"],"result":"옷을 뜯어 다시 짓는 일이 흔했다","effects":["18세기 여성복은 재단이 단순해 해체해서 재사용하기 쉬웠다"]},{"t":"def","term":"오늘날의 재활용 개념","text":"업사이클링(upcycling)과 순환 경제(circular economy)는 이를 되살리는 개념"}],"ebs27sd_g19_4":[{"t":"cause","title":"옷 뜯어 다시 짓기","causes":["산업화 이전 직물이 비싸고 노동은 상대적으로 쌌다"],"result":"옷을 뜯어 다시 짓는 일이 흔했다","effects":["18세기 여성복은 재단이 단순해 해체해서 재사용하기 쉬웠다"]},{"t":"def","term":"오늘날의 재활용 개념","text":"업사이클링(upcycling)과 순환 경제(circular economy)는 이를 되살리는 개념"}],"ebs27sd_g19_5":[{"t":"def","term":"미디어 리터러시(media literacy)","text":"매체의 정보를 비판적으로 평가하는 능력"},{"t":"tree","title":"뉴스의 신뢰성 평가 방법","root":"뉴스 신뢰성 평가","branches":[["수평 읽기(lateral reading)","스탠퍼드 역사교육 그룹(SHEG)이 제안한, 출처를 직접 검증하는 읽기"],["사실 확인(fact-checking)","핵심 방법"],["출처 신뢰도 평가","핵심 방법"]]}],"ebs27sd_g19_6":[{"t":"def","term":"미디어 리터러시(media literacy)","text":"매체의 정보를 비판적으로 평가하는 능력"},{"t":"tree","title":"뉴스의 신뢰성 평가 방법","root":"뉴스 신뢰성 평가","branches":[["수평 읽기(lateral reading)","스탠퍼드 역사교육 그룹(SHEG)이 제안한, 출처를 직접 검증하는 읽기"],["사실 확인(fact-checking)","핵심 방법"],["출처 신뢰도 평가","핵심 방법"]]}],"ebs27sd_g19_7":[{"t":"vs","title":"노동 시간 논의","cols":[{"name":"케인스(Keynes)","items":["1930년 기술 발전으로 주 15시간 노동이 가능해질 것이라 예측"]},{"name":"줄리엣 쇼어(Juliet Schor)","items":["『과로하는 미국인』(1991)에서 실제 노동 시간이 늘었다고 분석"]}]},{"t":"def","term":"일과 삶의 균형(work-life balance)","text":"서비스 산업(service sector)이 커지면서 쟁점이 되었다"}],"ebs27sd_g19_8":[{"t":"vs","title":"노동 시간 논의","cols":[{"name":"케인스(Keynes)","items":["1930년 기술 발전으로 주 15시간 노동이 가능해질 것이라 예측"]},{"name":"줄리엣 쇼어(Juliet Schor)","items":["『과로하는 미국인』(1991)에서 실제 노동 시간이 늘었다고 분석"]}]},{"t":"def","term":"일과 삶의 균형(work-life balance)","text":"서비스 산업(service sector)이 커지면서 쟁점이 되었다"}],"ebs27sd_g19_9":[{"t":"def","term":"통합적 복잡성(integrative complexity)","text":"정치심리학자 필립 테틀록(Philip Tetlock)이 지도자 발언에서 측정 · 위기에서는 판단이 단순해지는 경향이 있다"},{"t":"def","term":"집단 사고(groupthink, 1972)","text":"어빙 재니스(Irving Janis)의 개념으로 응집력 높은 집단이 반대 의견을 억누르는 현상"}],"ebs27sd_g19_10":[{"t":"def","term":"통합적 복잡성(integrative complexity)","text":"정치심리학자 필립 테틀록(Philip Tetlock)이 지도자 발언에서 측정 · 위기에서는 판단이 단순해지는 경향이 있다"},{"t":"def","term":"집단 사고(groupthink, 1972)","text":"어빙 재니스(Irving Janis)의 개념으로 응집력 높은 집단이 반대 의견을 억누르는 현상"}],"ebs27sd_g21_1":[{"t":"def","term":"지리학(geography)","text":"사물이 지표면 어디에 있는지뿐 아니라 왜 그곳에 있고 그것이 무엇을 의미하는지를 묻는다"},{"t":"def","term":"지리학의 제1법칙(Tobler's first law)","text":"모든 것이 서로 관련 있지만 가까운 것일수록 더 관련 있다 · 핵심 개념은 위치(location), 지역(region), 장소(place)"}],"ebs27sd_g21_2":[{"t":"tree","title":"공간 정보 기술","root":"공간 정보 기술","branches":[["지리정보시스템(GIS)","위치 데이터를 지도 위에 겹쳐 분석하는 기술"],["원격 탐사(remote sensing)와 위성 위치 확인(GPS)","인간과 환경의 상호작용을 넓은 지역에서 측정하게 해 주었다"],["공간 명시적 방법(spatially explicit methods)","자료에 위치 정보를 포함해 분석하는 방식"]]}],"ebs27sd_g21_3":[{"t":"flow","title":"방법적 회의","steps":["데카르트(René Descartes)가 『성찰』(1641)에서 확실한 지식을 찾기 위해 의심 가능한 모든 것을 의심: 방법적 회의(methodological doubt)","꿈과 악마(evil demon)의 가설","결론: \"나는 생각한다, 고로 존재한다\"(cogito)"]},{"t":"def","term":"합리론(rationalism)","text":"감각보다 이성을 앞세우는 입장 · 방법적 회의가 그 출발점으로 평가된다"}],"ebs27sd_g21_4":[{"t":"cause","title":"음식 나눔과 위험 분산","causes":["수렵채집인의 사냥 성과가 불규칙"],"result":"음식을 나누는 것이 보험 역할을 한다고 행동생태학에서 본다","effects":["아체(Ache) 부족을 연구한 킬 캐플런과 힐(Kaplan & Hill)이 대표적"]},{"t":"def","term":"상호 이타성(reciprocal altruism)","text":"로버트 트리버스(Robert Trivers)의 개념으로 나중에 되돌려 받을 것을 기대한 돕기"}],"ebs27sd_g22_1":[{"t":"vs","title":"하천 공학","cols":[{"name":"경성 공학(hard engineering)","items":["제방, 댐처럼 인공 구조물로 물을 통제"]},{"name":"연성 공학(soft engineering)","items":["하천의 자연스러운 흐름과 범람원(floodplain)을 활용","자연과 함께 일하는(working with nature) 접근이며 하천 복원(river restoration)과 연결"]}]}],"ebs27sd_g22_2":[{"t":"tree","title":"경관 연결성과 서식지","root":"보전생물학","branches":[["서식지 파편화(habitat fragmentation)","도로와 개발로 서식지가 쪼개지는 현상"],["생태 통로(wildlife corridor)","조각난 서식지를 잇는다"],["섬 생물지리학(island biogeography)","맥아더와 윌슨(MacArthur & Wilson, 1967)이 면적과 거리가 종 수에 미치는 영향을 설명"]]}],"ebs27sd_g22_3":[{"t":"flow","title":"바이오 에너지","steps":["바이오매스(biomass): 나무와 농업 폐기물 같은 생물 자원","바이오에너지(bioenergy): 이를 연소하거나 가스화해 얻는 재생 에너지","열병합 발전(CHP): 전기와 열을 함께 생산해 에너지 효율을 높인다"]},{"t":"def","term":"탄소 중립(carbon neutrality)","text":"바이오 에너지가 탄소 중립인지 여부는 쟁점"}],"ebs27sd_g22_4":[{"t":"def","term":"핵심종(keystone species)","text":"개체 수에 비해 생태계에 큰 영향을 미치는 종 · 로버트 페인(Robert Paine, 1969)이 불가사리 연구에서 제안"},{"t":"def","term":"생태계 공학자(ecosystem engineer)","text":"코끼리는 나무를 쓰러뜨려 사바나(savanna)의 식생 구조를 바꾸는 생태계 공학자로 불린다"}],"ebs27sd_g23_1":[{"t":"cause","title":"카오스 이론(chaos theory)","causes":["규칙(결정론)을 따르는 계에서도 초기 조건의 아주 작은 차이"],"result":"큰 결과 차이를 낳는 민감한 의존성(sensitive dependence on initial conditions)으로 장기 예측이 어렵다","effects":["에드워드 로렌츠(Edward Lorenz)가 1963년 기상 모형에서 발견했고 나비 효과(butterfly effect)로 대중화","자석 진자는 이를 보여 주는 대표 장치"]}],"ebs27sd_g23_2":[{"t":"def","term":"상대성 원리","text":"갈릴레이(Galileo)가 1632년 설명한, 등속으로 움직이는 배 안의 실험은 정지한 배와 같은 결과라는 주장 · 관성계(inertial frame)에서는 속도가 기준에 따라 상대적으로 정해진다"},{"t":"def","term":"운동량(momentum)","text":"질량과 속도의 곱"}],"ebs27sd_g23_4":[{"t":"def","term":"극한 환경 생물(extremophile)","text":"고온, 고압, 강산 같은 극한 조건에서 사는 생물"},{"t":"flow","title":"화학합성 생태계의 발견","steps":["1977년 심해 열수 분출구(hydrothermal vent) 발견","햇빛 없이 화학 에너지를 쓰는 화학합성(chemosynthesis) 생태계가 알려졌다","외계 생명 탐사인 우주생물학(astrobiology)에 중요"]}],"ebs27sd_g24_2":[{"t":"flow","title":"문화 관광의 변화","steps":["문화 관광(cultural tourism): 박물관과 유적 방문 중심","거리 문화와 일상 체험으로 넓어졌다","그레그 리처즈(Greg Richards)가 참여형 창조 관광(creative tourism)을 제안"]},{"t":"def","term":"변화의 배경","text":"고급 문화(high culture)와 대중 문화(popular culture)의 구분이 약해지는 현상"}],"ebs27sd_g24_3":[{"t":"def","term":"종합 지표","text":"스포츠에서는 여러 기록을 하나의 점수로 합친 지표를 쓴다 · 미식축구의 쿼터백 평점(passer rating)은 성공률과 거리 등을 가중해 계산"},{"t":"tree","title":"점수 통합 방법","root":"점수 통합","branches":[["표준화(z-score)","통계학에서 서로 다른 단위를 같은 척도로 맞춘다"],["가중 지수(weighted index)","항목마다 중요도를 달리한 종합 점수"]]}],"ebs27sd_g25_2":[{"t":"def","term":"학급 경영(classroom management)","text":"교육학에서 수업을 위한 질서를 만드는 일"},{"t":"tree","title":"학급 질서 관련 연구","root":"학급 질서","branches":[["야콥 쿠닌(Jacob Kounin)의 연구","교사의 상황 파악과 수업 흐름이 질서에 영향을 준다고 보았다"],["푸코(Foucault)","『감시와 처벌』(1975)에서 학교를 규율 사회의 한 장치로 분석"]]}],"ebs27sd_g25_3":[{"t":"vs","title":"편도체와 전전두엽","cols":[{"name":"편도체(amygdala)","items":["신경과학에서 위협에 반응하는 뇌 영역"]},{"name":"전전두엽(prefrontal cortex)","items":["판단과 자기 조절을 맡는다"]}]},{"t":"tree","title":"감정 뇌와 양육","root":"감정과 양육","branches":[["편도체 납치(amygdala hijack)","대니얼 골먼(Daniel Goleman)의 개념으로 강한 감정이 이성적 판단을 압도하는 현상"],["감정 코칭(emotion coaching)","존 가트맨(John Gottman)의 방식으로 아이의 감정을 인정하고 지도"]]}],"ebs27sd_g25_4":[{"t":"vs","title":"두 시각 경로","cols":[{"name":"'무엇' 경로(ventral stream)","items":["밀너와 구델(Milner & Goodale)이 설명한, 물체를 알아보는 경로"]},{"name":"'어떻게' 경로(dorsal stream)","items":["행동을 안내하는 경로"]}]},{"t":"def","term":"절차 기억(procedural memory)","text":"자전거 타기처럼 연습으로 몸에 익는 운동 기술이 저장되고 소뇌가 관여한다"}],"ebs27sd_g26_1":[{"t":"def","term":"초허구성(transfictionality)","text":"서사 이론에서 하나의 허구 인물이나 세계가 여러 작품에 걸쳐 나타나는 현상","ex":["셜록 홈즈의 파생작, 팬 픽션(fan fiction), 속편, 스핀오프"]},{"t":"def","term":"상호텍스트성(intertextuality)","text":"텍스트가 다른 텍스트와 맺는 관계"}],"ebs27sd_g26_2":[{"t":"def","term":"작가의 맥락(context)","text":"미술 비평에서 작가의 삶과 작업실 같은 맥락이 작품 해석에 영향을 준다 · 작가의 전체 작품 세계를 오브르(oeuvre)라 부른다"},{"t":"vs","title":"해석의 기준","cols":[{"name":"의도주의(intentionalism)","items":["작가 의도로 해석"]},{"name":"독자 해석","items":["롤랑 바르트(Roland Barthes)의 「저자의 죽음」(1967)이 강조"]}]}],"ebs27sd_g26_3":[{"t":"vs","title":"자연적 의미와 비자연적 의미","cols":[{"name":"자연적 의미(natural meaning)","items":["철학자 폴 그라이스(H. P. Grice, 1957)가 구분, 연기는 불을 알려 주는 것"]},{"name":"비자연적 의미(non-natural meaning)","items":["의도한 메시지"]}]},{"t":"vs","title":"신호와 단서","cols":[{"name":"신호(signal)","items":["동물행동학에서 의도된 것"]},{"name":"단서(cue)","items":["부수적으로 정보를 주는 것"]}]}],"ebs27sd_g26_4":[{"t":"tree","title":"이야기와 인간 이해","root":"서사와 인간 이해","branches":[["서사학","이야기가 인간이 경험을 이해하는 기본 방식이라고 본다"],["단일 신화(monomyth)","조지프 캠벨(Joseph Campbell)이 『천의 얼굴을 가진 영웅』(1949)에서 여러 문화의 신화에 공통 구조가 있다고 주장"],["마음 이론(theory of mind)","이야기를 읽으면 타인의 생각을 추측하는 이 능력이 발달한다는 연구도 있다"]]}],"ebs27sd_g27_1":[{"t":"vs","title":"정보와 의미","cols":[{"name":"정보 이론(information theory, 1948)","items":["섀넌(Claude Shannon)의 이론으로 정보를 사건의 확률로 측정하며 메시지의 의미는 다루지 않는다"]},{"name":"기호학(semiotics)과 의미론(semantics)","items":["신호가 어떤 의미로 해석되는지를 다룬다"]}]},{"t":"def","term":"해석","text":"같은 자료도 해석하는 주체와 맥락에 따라 의미가 달라진다"}],"ebs27sd_g27_2":[{"t":"cause","title":"디지털 시대의 사회운동","causes":["아랍의 봄(2011)과 월가 점령 같은 운동"],"result":"인터넷 네트워크로 조직되었다고 분석","effects":["사회학자 마누엘 카스텔스(Manuel Castells)가 『분노와 희망의 네트워크』(2012)에서 분석","그는 정보 사회를 네트워크 사회(network society)라 불렀다"]},{"t":"def","term":"해시태그 행동주의(hashtag activism)","text":"관련 개념"}],"ebs27sd_g27_3":[{"t":"def","term":"지대 모형(bid-rent, 1964)","text":"도시경제학에서 알론소(Alonso)가 도심에서 멀수록 땅값이 싸다고 설명"},{"t":"cause","title":"자동차와 교외 확산","causes":["자동차가 통근 거리를 늘렸다"],"result":"교외(suburb) 개발이 가능해졌다","effects":["이후 무질서한 도시 확산(urban sprawl)과 자동차 의존이 쟁점이 되었다"]}],"ebs27sd_g28_1":[{"t":"def","term":"사회적 자본(social capital)","text":"사회학자 피에르 부르디외(Pierre Bourdieu)와 로버트 퍼트넘(Robert Putnam)이 발전시킨 개념으로 신뢰와 호혜성에 기반한 관계망이 주는 자원"},{"t":"vs","title":"퍼트넘의 구분","cols":[{"name":"결속형(bonding)","items":["같은 집단 안"]},{"name":"연결형(bridging)","items":["서로 다른 집단을 잇는다"]}]},{"t":"def","term":"소셜 미디어","text":"이런 관계의 형성과 유지를 다룬 연구 주제"}],"ebs27sd_g28_2":[{"t":"tree","title":"풍경 선호 이론","root":"풍경 선호","branches":[["사바나 가설(savanna hypothesis)","진화심리학에서 인류가 사바나에서 진화해 비슷한 풍경을 선호한다고 본다"],["바이오필리아(biophilia, 1984)","에드워드 윌슨(E. O. Wilson)의 개념으로 사람이 자연에 끌리는 성향"],["전망-피난처 이론(prospect-refuge theory, 1975)","애플턴(Appleton)의 이론으로 풍경 선호를 설명"]]}],"ebs27sd_g28_3":[{"t":"tree","title":"출처 감시와 꿈의 기억","root":"기억 연구","branches":[["출처 감시(source monitoring)","기억이 어디서 왔는지 판단하는 과정"],["현실 감시(reality monitoring)","마시아 존슨(Marcia Johnson)의 틀로 실제 경험과 상상한 내용을 구별하는 일을 다룬다"],["꿈","사건이 생생해 현실 기억과 혼동되기 쉽다"]]}],"ebs27sd_g28_4":[{"t":"tree","title":"자기 방어와 긍정적 자아상","root":"사회심리학","branches":[["자기고양 편향(self-serving bias)","성공은 자기 덕, 실패는 상황 탓으로 돌리는 경향"],["인지 부조화(cognitive dissonance) 이론","자기 이미지와 충돌하는 정보를 줄이려는 동기를 설명"],["동기화된 추론(motivated reasoning)","원하는 결론에 맞춰 생각하는 경향"]]}],"ebs27sd_g29_1":[{"t":"def","term":"사회적 선택 이론(social choice theory)","text":"개인의 선호를 하나의 집단 결정으로 모으는 방법을 연구"},{"t":"def","term":"불가능성 정리(impossibility theorem, 1951)","text":"케네스 애로(Kenneth Arrow)가 몇 가지 합리적 조건을 모두 만족하는 투표 방식이 없다고 증명 · 동점 처리, 중립성(neutrality)과 익명성(anonymity)도 쟁점"}],"ebs27sd_g29_2":[{"t":"vs","title":"법의 두 모습","cols":[{"name":"책 속의 법(law in books)","items":["법학에서 로스코 파운드(Roscoe Pound, 1910)가 구분"]},{"name":"현실에서 작동하는 법(law in action)","items":["로스코 파운드가 구분"]}]},{"t":"tree","title":"법의 접근성","root":"법의 접근성","branches":[["영미법(common law)","판례가 쌓여 만들어진다"],["법률 문해력(legal literacy)","일반인이 법을 이해하는 능력, \"법을 몰랐다는 변명은 통하지 않는다\"는 원칙이 자주 인용"]]}],"ebs27sd_g29_3":[{"t":"cause","title":"패션 수요 예측의 어려움","causes":["패션 산업은 유행이 빠르다"],"result":"수요 예측(demand forecasting)이 어렵다","effects":["공급망에서 수요 정보가 왜곡되어 재고가 커지는 현상을 채찍 효과(bullwhip effect)라 한다"]},{"t":"tree","title":"패션 산업의 대응","root":"패션 산업","branches":[["패스트 패션","자라(Zara) 같은 패스트 패션은 짧은 주기로 생산해 대응"],["가격 정보","인터넷으로 투명해져 소비자 선택의 힘이 커졌다"]]}],"ebs27sd_g29_4":[{"t":"def","term":"\"숨 쉴 수 없다\"(I can't breathe)","text":"2014년 에릭 가너(Eric Garner)와 2020년 조지 플로이드(George Floyd)의 사망 때 항의 구호가 되었다 · 아실 음벰베(Achille Mbembe)는 2020년 글에서 모든 사람의 숨 쉴 권리를 논했다"},{"t":"vs","title":"인종주의의 두 형태","cols":[{"name":"구조적 인종주의(systemic racism)","items":["제도 속에 내재한 차별"]},{"name":"환경 인종주의(environmental racism)","items":["오염 시설과 위험이 특정 인종의 거주지에 몰리는 불평등"]}]}],"ebs27sd_g30_2":[{"t":"vs","title":"영양소 밀도와 에너지 밀도","cols":[{"name":"영양소 밀도(nutrient density)","items":["영양학에서 열량에 비해 영양소가 얼마나 많은가"]},{"name":"에너지 밀도(energy density)","items":["높은 음식은 적은 양에도 열량이 많다"]}]},{"t":"def","term":"절제(moderation)","text":"식사 지침은 특정 음식을 금지하기보다 전체 균형을 강조 · 절제는 금지가 아니라 양의 조절"}],"ebs27sd_g30_3":[{"t":"def","term":"식행동의 자동성","text":"행동경제학과 심리학에서 식행동이 환경 단서에 자동으로 반응하는 습관이라고 본다"},{"t":"def","term":"무의식적 식사(mindless eating)","text":"브라이언 완싱크(Brian Wansink)의 연구로 접시 크기와 용기 크기가 섭취량에 영향을 준다고 주장했으나 일부 연구는 철회되었다"},{"t":"def","term":"이중 과정 이론(dual-process theory)","text":"자동적 사고와 통제적 사고를 구분"}],"ebs27sd_g30_4":[{"t":"tree","title":"아이의 미각 선호","root":"아이의 미각","branches":[["선호","발달 연구에 따르면 단맛과 짠맛을 좋아하고 쓴맛을 싫어하는 경향"],["쓴맛 회피","독성 물질을 피하게 하는 진화적 적응으로 설명 · TAS2R 유전자가 쓴맛 인지와 관련"],["반복 노출(repeated exposure)","낯선 음식을 받아들이게 하는 방법"],["식품 신기 공포(food neophobia)","새 음식을 거부하는 성향"]]}],"ebs27sd_t1_3":[{"t":"def","term":"내부자 위협(insider threat)","text":"정보 보안에서 조직 내부 사람의 실수나 악의로 생기는 위험"},{"t":"tree","title":"사람을 노리는 공격과 대응","root":"사람의 심리","branches":[["사회공학(social engineering)과 피싱(phishing)","사람의 심리를 이용한 공격"],["개인정보 문해력(privacy literacy)","개인정보를 보호하는 지식과 태도, 보안 인식 교육(security awareness training)이 이를 높인다"]]}],"ebs27sd_t1_4":[{"t":"tree","title":"마음과 만성 통증","root":"통증 관련 개념","branches":[["긴장성 근육통 증후군(tension myositis syndrome)","존 사노(John Sarno)가 주장한, 만성 통증이 심리적 긴장에서 비롯된다는 증후군"],["반복성 긴장 손상(repetitive strain injury, RSI)","반복 동작으로 생기는 근골격계 질환"],["관련 분야","심신 의학(mind-body medicine)과 조건 형성(conditioning)"]]}],"ebs27sd_t1_5":[{"t":"tree","title":"양육과 자율성","root":"양육 연구","branches":[["권위 있는 양육(authoritative parenting)","다이애나 바움린드(Diana Baumrind)가 설명한, 따뜻함과 한계 설정을 함께 갖는 양육"],["비계 설정(scaffolding)","비고츠키(Vygotsky)의 근접발달영역을 바탕으로 브루너(Bruner) 등이 제시한, 도움을 점차 줄이는 지원"],["자율성 지지(autonomy support)","아이의 선택권을 키운다"]]}],"ebs27sd_t1_6":[{"t":"def","term":"건강 후광 효과(health halo)","text":"식품 심리학에서 한 속성(유기농 표시 등)이 전체 건강성을 높게 느끼게 하는 현상 · 소비자는 건강과 환경 영향을 혼동하는 경우가 많다"},{"t":"tree","title":"육류 소비와 환경","root":"육류 소비의 환경 영향","branches":[["탄소 발자국(carbon footprint)","육류 소비의 환경 영향을 평가"],["식물성 대체육(plant-based meat)","함께 논의"]]}],"ebs27sd_t1_7":[{"t":"cause","title":"감정 라벨링","causes":["감정에 이름을 붙이는 감정 라벨링(affect labeling)"],"result":"편도체(amygdala) 활동이 줄어든다","effects":["UCLA의 매튜 리버먼(Matthew Lieberman) 연구진이 2007년 보고"]},{"t":"tree","title":"불안을 다루는 방법","root":"불안(anxiety) 다루기","branches":[["인지 재평가(cognitive reappraisal)","감정 라벨링과 비교되는 방법"],["피부 전도도(skin conductance)","각성 수준을 측정하는 지표"]]}],"ebs27sd_t1_12":[{"t":"def","term":"시뮬라크르(simulacra)","text":"프랑스 사회이론가 장 보드리야르(Jean Baudrillard)가 『시뮬라시옹』(1981)에서 현대 사회가 실재 없이 기호가 복제되는 시뮬라크르로 가득하다고 주장"},{"t":"def","term":"초현실(hyperreality)","text":"실재와 구별되지 않는 가상 · 보드리야르는 디즈니랜드를 예로 들었다","ex":["디즈니랜드"]}],"ebs27sd_t1_13":[{"t":"cause","title":"스트루프 효과(Stroop effect, 1935)","causes":["글자의 뜻과 글자 색이 다르다"],"result":"색 이름을 말하는 반응이 느려진다","effects":["읽기가 자동 처리(automatic processing)이기 때문에 통제 처리(controlled processing)와 간섭을 일으킨다고 설명"]},{"t":"def","term":"인지 통제(cognitive control)","text":"스트루프 과제는 이를 측정하는 대표 과제"}],"ebs27sd_t1_14":[{"t":"def","term":"태도(attitude)","text":"사회심리학에서 학습으로 형성되며 한 번의 나쁜 경험이 범주 전체로 일반화(generalization)될 수 있다"},{"t":"tree","title":"태도 형성 개념","root":"태도 형성","branches":[["맛 혐오 학습(conditioned taste aversion)","존 가르시아(John Garcia)가 1950년대에 연구"],["범주화(categorization)","서로 다른 대상을 하나의 이름으로 묶는다"]]}],"ebs27sd_t1_15":[{"t":"vs","title":"감정의 보편성","cols":[{"name":"기본 감정(basic emotions) 연구","items":["폴 에크만(Paul Ekman)이 표정이 문화에 걸쳐 보편적이라고 주장"]},{"name":"구성주의(constructionism)","items":["감정이 문화와 언어로 구성된다고 맞선다"]}]},{"t":"def","term":"표현 규칙(display rules)","text":"감정을 어떻게 드러낼지에 대한 문화적 규범"}],"ebs27sd_t1_16":[{"t":"tree","title":"다양한 관점과 사고","root":"여러 관점","branches":[["다중 표상(multiple representations)","인지과학에서 같은 문제를 그림, 식, 말 등 여러 방식으로 나타내는 것"],["삼각 검증(triangulation)","연구 방법론에서 서로 다른 방법으로 같은 결론을 확인하는 일"],["갈릴레이(Galileo)","경사면 실험으로 낙하를 연구해 측정 어려움을 극복"]]}],"ebs27sd_t1_17":[{"t":"def","term":"판촉(promotion)","text":"마케팅에서 구매를 유도하는 유인을 제공"},{"t":"cause","title":"희소성 원리(scarcity principle)","causes":["구하기 어렵다"],"result":"가치가 높게 느껴진다","effects":["로버트 치알디니(Robert Cialdini)의 심리 법칙","한정 판매 같은 방식은 긴급성(urgency)을 만든다"]}],"ebs27sd_t1_18":[{"t":"def","term":"페니 블랙(Penny Black)","text":"1840년 영국의 최초의 근대 우표"},{"t":"tree","title":"우표와 국가 상징","root":"우표의 의미","branches":[["국가 상징","우표는 주화와 지폐처럼 국가의 주권(sovereignty)과 권위를 상징하는 매체로 쓰였다"],["민족 정체성","베네딕트 앤더슨(Benedict Anderson)이 『상상의 공동체』(1983)에서 인쇄물이 민족 정체성을 형성한다고 분석"]]}],"ebs27sd_t1_19":[{"t":"vs","title":"스토리와 플롯","cols":[{"name":"스토리(story)","items":["E. M. Forster가 『소설의 이해』(1927)에서 구분한, 시간 순서의 사건","예: \"왕이 죽었고 왕비도 죽었다\""]},{"name":"플롯(plot)","items":["인과관계로 연결된 사건","예: \"왕이 죽자 슬퍼서 왕비도 죽었다\""]}]},{"t":"def","term":"서사학(narratology)","text":"서술 구조를 연구"}],"ebs27sd_t1_20":[{"t":"def","term":"얼굴 모방(facial mimicry)","text":"심리학에서 타인의 표정을 무의식적으로 따라 하는 현상, 정서 전염(emotional contagion)과 공감에 관여"},{"t":"def","term":"카멜레온 효과(chameleon effect)","text":"샤트랑과 바그(Chartrand & Bargh, 1999)의 연구로 상대를 흉내 내면 호감이 커진다 · 거울 뉴런(mirror neuron)도 논의"}],"ebs27sd_t1_21":[{"t":"def","term":"단일 뉴런 기록(single-neuron recording)","text":"신경과학에서 뉴런 하나하나의 활동을 기록해 뇌가 정보를 어떻게 처리하는지 연구하는 핵심 방법"},{"t":"def","term":"수 감각(number sense)","text":"동물 연구에서 감각의 종류와 상관없이 사건의 개수에 반응하는 뉴런이 보고되었고, 이는 수 감각의 신경 기반으로 논의"}],"ebs27sd_t1_22":[{"t":"def","term":"정보 기술과 공동체","text":"정보 기술은 공동체를 연결하기도 하고 갈라놓기도 한다"},{"t":"tree","title":"공동체를 가르는 환경","root":"정보 기술과 공동체","branches":[["필터 버블(filter bubble)과 반향실(echo chamber)","엘리 패리저(Eli Pariser)의 개념으로 비슷한 의견만 접하게 하는 환경, 집단 극화(group polarization)와 관련"],["사회적 자본(social capital)","로버트 퍼트넘(Robert Putnam)의 관련 개념"]]}],"ebs27sd_t1_23":[{"t":"def","term":"의례화된 과시(ritualized display)","text":"동물행동학에서 싸움을 피하는 과시로 비용을 줄이는 방법"},{"t":"tree","title":"과시 행동 이론","root":"과시 행동 이론","branches":[["매파-비둘기 게임(Hawk-Dove game)","메이너드 스미스(Maynard Smith)의 게임으로 의례화된 과시를 분석"],["핸디캡 원리(handicap principle)","자하비(Zahavi, 1975)가 비용이 드는 신호가 정직하다고 설명"]]}],"ebs27sd_t1_24":[{"t":"vs","title":"디지털 세대 구분","cols":[{"name":"디지털 네이티브(digital native)","items":["마크 프렌스키(Marc Prensky, 2001)가 구분"]},{"name":"디지털 이주민(digital immigrant)","items":["마크 프렌스키가 구분"]}]},{"t":"tree","title":"인지 변화","root":"디지털 시대의 인지","branches":[["구글 효과(Google effect)","스패로우(Sparrow) 등의 연구(2011)로 쉽게 검색할 수 있는 정보를 덜 기억하는 경향"],["인지적 외부 위탁(cognitive offloading)","관련 개념"]]}],"ebs27sd_t1_25":[{"t":"vs","title":"디지털 세대 구분","cols":[{"name":"디지털 네이티브(digital native)","items":["마크 프렌스키(Marc Prensky, 2001)가 구분"]},{"name":"디지털 이주민(digital immigrant)","items":["마크 프렌스키가 구분"]}]},{"t":"tree","title":"인지 변화","root":"디지털 시대의 인지","branches":[["구글 효과(Google effect)","스패로우(Sparrow) 등의 연구(2011)로 쉽게 검색할 수 있는 정보를 덜 기억하는 경향"],["인지적 외부 위탁(cognitive offloading)","관련 개념"]]}],"ebs27sd_t2_3":[{"t":"vs","title":"프레이리의 교육 구분","cols":[{"name":"은행 저금식 교육(banking education)","items":["브라질 교육학자 파울루 프레이리(Paulo Freire)가 『피억압자의 교육학』(1970)에서 비판, 교사가 지식을 채워 넣는 교육"]},{"name":"문제 제기식 교육(problem-posing education)","items":["파울루 프레이리가 제안"]}]},{"t":"def","term":"질문을 중시하는 교육","text":"탐구 기반 학습(inquiry-based learning)과 소크라테스식 문답법(Socratic method)"}],"ebs27sd_t2_4":[{"t":"tree","title":"이집트 미술의 규범","root":"고대 이집트 미술","branches":[["규범","인체 비례를 정한 규범(canon of proportions), 정면성(frontality), 신분에 따라 크기를 달리하는 위계적 크기(hierarchical scale)"],["무덤 벽","부조와 벽화는 사후 세계를 위한 것"],["곰브리치(E. H. Gombrich)","미술사가로 『서양미술사』에서 이집트 미술을 개념적 표현의 사례로 다룬다"]]}],"ebs27sd_t2_5":[{"t":"def","term":"물질문화 연구(material culture studies)","text":"패션 연구와 함께 옷을 단순한 소비재가 아니라 재료와 노동, 의미가 결합된 물건으로 본다"},{"t":"tree","title":"패션과 사물","root":"패션 연구 개념","branches":[["지속 가능한 패션(sustainable fashion)","원료 조달부터 폐기까지의 환경 영향을 따진다"],["사물 이론(thing theory)","사물의 사회적 삶을 다룬다"]]}],"ebs27sd_t2_6":[{"t":"cause","title":"대재배선(great rewiring)","causes":["2010년대 초 스마트폰과 소셜 미디어"],"result":"청소년의 정신 건강을 해쳤다는 조너선 하이트(Jonathan Haidt)의 주장 (『불안 세대』, 2024)","effects":["연구자 사이에서는 인과 관계에 대한 논쟁이 있다"]},{"t":"def","term":"주의 경제(attention economy)","text":"사용자의 주의를 상품으로 삼는 구조"}],"ebs27sd_t2_7":[{"t":"tree","title":"학문하는 사람의 비유","root":"프랜시스 베이컨(Francis Bacon)의 『신기관』(1620)","branches":[["개미","경험만 모으는 사람"],["거미","이성으로 거미줄을 짜는 사람"],["꿀벌","둘을 종합하는 사람"]]},{"t":"vs","title":"경험론과 합리론","cols":[{"name":"경험론(empiricism)","items":["귀납법(induction)은 관찰에서 일반 법칙을 끌어낸다"]},{"name":"합리론(rationalism)","items":["경험론과의 대비와 연결"]}]}],"ebs27sd_t2_12":[{"t":"def","term":"진정한 자아(true self)","text":"심리학에서 사람들이 겉모습 뒤에 있는 본래의 나가 있다고 믿는 일상적 개념 · 스트로밍거(Strohminger), 노브(Knobe), 뉴먼(Newman)은 2017년 진정한 자아를 하나의 독립된 심리적 개념으로 논했다"},{"t":"def","term":"관련 개념","text":"진정성(authenticity)과 본질주의(essentialism)"}],"ebs27sd_t2_13":[{"t":"def","term":"탈진실(post-truth)","text":"옥스퍼드 사전이 2016년 올해의 단어로 선정한 말로 객관적 사실보다 감정과 믿음이 여론에 더 큰 영향을 주는 상황"},{"t":"tree","title":"탈진실 논의","root":"탈진실 논점","branches":[["포스트모더니즘(postmodernism)","진리가 상대적이라고 보는 경향"],["전문가 합의(expert consensus)","권위 약화가 논점"]]}],"ebs27sd_t2_14":[{"t":"def","term":"호손 효과(Hawthorne effect)","text":"1924년부터 1932년까지 웨스턴 일렉트릭의 호손 공장에서 한 조명 실험에서 유래 · 관찰받는다는 사실만으로 노동자의 생산성이 변한다는 현상"},{"t":"def","term":"요구 특성(demand characteristics)","text":"연구방법론에서 호손 효과와 함께 연구 대상 편향으로 다룬다"}],"ebs27sd_t2_15":[{"t":"def","term":"\"매체가 메시지다\"(the medium is the message)","text":"마셜 매클루언(Marshall McLuhan)이 『미디어의 이해』(1964)에서 주장 · 매체의 내용보다 매체가 사회에 가져오는 규모, 속도, 관계의 변화가 중요하다는 뜻"},{"t":"def","term":"지구촌(global village)","text":"그가 제시한, 전자 매체로 세계가 하나로 연결된다는 개념"}],"ebs27sd_t2_16":[{"t":"def","term":"화행 이론(speech act theory)","text":"철학자 J. L. 오스틴(J. L. Austin)이 『말로 행위하는 법』(1962)에서 말이 단지 사실을 기술하는 것이 아니라 행위를 수행한다고 본 이론"},{"t":"tree","title":"화행의 구분","root":"화행 이론의 구분","branches":[["발화 행위","구분되는 행위"],["발화 수반 행위","구분되는 행위"],["발화 효과 행위","구분되는 행위"],["수행문(performative)","약속이나 선언 같은 수행문이 대표적"]]}],"ebs27sd_t2_17":[{"t":"def","term":"자연선택의 단위","text":"진화생물학에서 자연선택이 집단, 개체, 유전자 중 어느 수준에서 작동하는지는 오랜 논쟁"},{"t":"tree","title":"자연선택 수준 논쟁","root":"선택의 수준","branches":[["집단 선택론","윈에드워즈(Wynne-Edwards, 1962)의 이론으로 조지 윌리엄스(George Williams, 1966)에게 비판받았다"],["유전자 중심 관점","리처드 도킨스(Richard Dawkins)가 『이기적 유전자』(1976)로 대중화"]]}],"ebs27sd_t2_18":[{"t":"cause","title":"반품 증가","causes":["전자상거래에서 사이즈를 여러 개 사서 맞는 것만 남기는 브래킷팅(bracketing)"],"result":"반품이 늘어난다","effects":["역물류(reverse logistics): 반품된 상품을 회수해 재판매, 수리, 재활용하는 과정","순환 경제(circular economy)와 이어진다"]}],"ebs27sd_t2_19":[{"t":"vs","title":"자원의 특성","cols":[{"name":"재생 불가능 자원(non-renewable resource)","items":["경제학에서 석유 같은 자원, 한 번 쓰면 사라진다"]},{"name":"물","items":["물의 순환(water cycle)으로 돌아와 소비적 사용(consumptive use)과 비소비적 사용이 구분"]}]},{"t":"def","term":"경합성(rivalry)","text":"자원 관리에서 한 사용자가 쓰면 다른 사용자가 못 쓰는 성질도 따진다"}],"ebs27sd_t2_20":[{"t":"tree","title":"기능에 따른 범주화","root":"범주화 이론","branches":[["임시 범주(ad hoc category)","인지심리학에서 로런스 바살루(Lawrence Barsalou, 1983)가 제안한, 목적에 따라 즉석에서 만드는 범주"],["이론과 기능에 근거한 범주","머피와 메딘(Murphy & Medin, 1985)이 범주가 겉모습의 유사성뿐 아니라 이론과 기능에도 근거한다고 주장"]]},{"t":"vs","title":"유사성의 대비","cols":[{"name":"기능적 유사성(functional similarity)","items":["기능에 따른 유사성"]},{"name":"지각적 유사성(perceptual similarity)","items":["겉모습에 따른 유사성"]}]}],"ebs27sd_t2_21":[{"t":"vs","title":"상관과 인과","cols":[{"name":"상관(correlation)","items":["통계학에서 두 변수가 함께 변하는 관계"]},{"name":"인과(causation)","items":["상관이 곧 인과는 아니다"]}]},{"t":"tree","title":"인과 해석의 함정","root":"상관과 인과","branches":[["역인과(reverse causality)","인과 방향이 반대인 경우"],["교란 변수(confounding variable)","제3의 변수"],["사례","부유함과 건강 같은 관계에서 자주 인용"]]}],"ebs27sd_t2_22":[{"t":"def","term":"다중 문해력(multiliteracies)","text":"뉴 런던 그룹(New London Group, 1996)이 제안해 읽기와 쓰기가 글뿐 아니라 이미지, 소리, 디지털 매체를 포함한다고 본 개념"},{"t":"tree","title":"문해력 관련 개념","root":"문해력","branches":[["디지털 문해력(digital literacy)","기술을 이해하고 활용하는 능력"],["장르(genre)","소통 상황에 따라 달라지는 글의 양식"]]}],"ebs27sd_t2_23":[{"t":"def","term":"억양과 방언(dialect)","text":"사회언어학에서 사회적 정체성과 연결된다"},{"t":"def","term":"언어 태도(language attitude)","text":"특정 말씨에 대해 갖는 평가 · 아이들도 어릴 때부터 자기와 비슷한 말씨를 쓰는 사람을 선호한다는 연구가 있다 · 킨즐러와 데헤수스(Kinzler & DeJesus)가 지역 억양에 대한 아동의 반응을 연구"}],"ebs27sd_t2_24":[{"t":"tree","title":"식물의 형태와 환경 기록","root":"식물과 환경","branches":[["표현형 가소성(phenotypic plasticity)","식물은 환경에 따라 형태가 달라진다"],["연륜 연대학(dendrochronology)","나이테를 분석해 나무가 기후와 사건을 기록한다는 점을 이용"],["다종 민족지(multispecies ethnography)","인류학에서 사람과 식물, 동물이 얽힌 관계를 연구"]]}],"ebs27sd_t2_25":[{"t":"tree","title":"식물의 형태와 환경 기록","root":"식물과 환경","branches":[["표현형 가소성(phenotypic plasticity)","식물은 환경에 따라 형태가 달라진다"],["연륜 연대학(dendrochronology)","나이테를 분석해 나무가 기후와 사건을 기록한다는 점을 이용"],["다종 민족지(multispecies ethnography)","인류학에서 사람과 식물, 동물이 얽힌 관계를 연구"]]}],"ebs27sd_t3_3":[{"t":"def","term":"객관성(objectivity)","text":"저널리즘 이론에서 월터 리프먼(Walter Lippmann)이 1920년대에 사실 검증의 방법으로 강조 · 코바치와 로젠스틸(Kovach & Rosenstiel)의 『저널리즘의 기본 요소』(2001)는 객관성이 중립이 아니라 검증 방식이라고 설명"},{"t":"def","term":"독립성(independence)","text":"권력과 이해관계로부터의 자유"}],"ebs27sd_t3_4":[{"t":"vs","title":"물관과 체관","cols":[{"name":"물관(xylem)","items":["식물 생리학에서 물과 무기염이 위로 올라가는 통로"]},{"name":"체관(phloem)","items":["광합성으로 만든 당이 이동하는 전류(translocation)가 일어나는 통로"]}]},{"t":"cause","title":"환상 박피(girdling)","causes":["나무의 껍질 일부를 둘러 벗긴다"],"result":"체관이 끊어진다","effects":["뿌리로 당이 가지 못하게 한다"]}],"ebs27sd_t3_5":[{"t":"cause","title":"알고리즘 편향(algorithmic bias)","causes":["학습 자료의 편향"],"result":"AI 결과에 반영되는 현상","effects":["아마존은 2018년 여성 지원자에게 불리했던 채용 AI를 폐기했다고 알려졌다"]},{"t":"tree","title":"채용 AI 관련 개념","root":"채용 AI","branches":[["간접 차별(disparate impact)","중립적 기준이 특정 집단에 불리한 결과를 낳는 경우"],["지원자 추적 시스템(ATS)","이력서를 자동 선별"]]}],"ebs27sd_t3_6":[{"t":"def","term":"보상 체계(reward system)","text":"로버트 머튼(Robert Merton)이 분석한, 과학이 금전보다 동료 인정으로 움직이는 체계"},{"t":"tree","title":"과학자의 동기를 움직이는 압박","root":"과학자의 동기와 연구 문화","branches":[["우선권 경쟁(priority)","동기와 연구 문화에 영향"],["출판 압박(publish or perish)","'논문을 내지 않으면 도태된다'는 압박"]]}],"ebs27sd_t3_7":[{"t":"vs","title":"알게 된 정보와 이해","cols":[{"name":"검색으로 '알게 된' 정보","items":["철학자 마이클 린치(Michael Lynch)의 『인터넷의 우리』(2016)가 구분"]},{"name":"진정한 이해","items":["검색 정보와 구분"]}]},{"t":"tree","title":"빅데이터와 인식론","root":"빅데이터와 인식론","branches":[["빅데이터","상관을 찾기 쉽지만 인과를 보장하지 않는다"],["이론의 종말","크리스 앤더슨(Chris Anderson)이 2008년 주장했고 이에 대한 반박이 이어졌다"],["인식론(epistemology)","지식의 본성과 한계를 다룬다"]]}],"ebs27sd_t3_12":[{"t":"vs","title":"생태계 구조와 기능","cols":[{"name":"생태계 구조(ecosystem structure)","items":["구성하는 생물 군집과 비생물 요소(abiotic factors)의 배열","종 풍부도(species richness)와 영양 구조(trophic structure)가 구조의 지표"]},{"name":"생태계 기능(ecosystem function)","items":["에너지 흐름과 물질 순환 같은 과정"]}]}],"ebs27sd_t3_13":[{"t":"def","term":"인지 부하(cognitive load)","text":"작업 기억에 가해지는 부담"},{"t":"tree","title":"창의적 사고와의 연결","root":"인지신경과학","branches":[["마음 방황(mind wandering)과 기본 모드 네트워크(default mode network)","창의적 사고와 연결"],["모셰 바(Moshe Bar)","인지 부하와 사고의 관계를 연구한 신경과학자"]]}],"ebs27sd_t3_14":[{"t":"def","term":"동물의 공정함과 공감","text":"영장류학자 프란스 드 발(Frans de Waal)은 동물에게도 공정함과 공감의 기초가 있다고 주장"},{"t":"cause","title":"불평등 혐오(inequity aversion)","causes":["꼬리감는원숭이가 불공평한 보상에 반응"],"result":"불평등 혐오를 보인다고 보고 (브로스넌과 드 발, 2003)","effects":[]},{"t":"def","term":"친사회적 행동(prosocial behavior)","text":"남에게 이로운 행동"}],"ebs27sd_t3_15":[{"t":"vs","title":"분류와 검색","cols":[{"name":"분류(classification)","items":["정보 관리에서 정해진 범주에 문서를 나누는 방법"]},{"name":"검색(search)","items":["필요한 문서를 찾는 방법"]}]},{"t":"def","term":"초정리법","text":"일본 경제학자 노구치 유키오(野口悠紀雄)가 1993년 분류 대신 시간순으로 봉투에 쌓는 방법으로 제안 · 시간순 정리는 범주 결정 비용을 줄이는 방법"}],"ebs27sd_t3_16":[{"t":"vs","title":"벌린의 두 자유","cols":[{"name":"소극적 자유","items":["이사야 벌린(Isaiah Berlin)이 1958년 강연에서 구분한, 간섭이 없는 자유"]},{"name":"적극적 자유","items":["스스로 목표를 실현하는 자유"]}]},{"t":"def","term":"자유의 상호 제약","text":"한 사람의 자유는 다른 사람의 자유와 부딪칠 수 있어 법과 규범이 이를 조정 · 미국 민권법(1964)과 여성 참정권 운동은 자유와 평등의 문제를 보여 준 사례"}],"ebs27sd_t3_17":[{"t":"def","term":"인간 욕구의 보편성","text":"심리학에서 매슬로(Maslow)의 욕구 위계(hierarchy of needs, 1943)와 자기결정 이론(SDT)의 기본 심리적 욕구(basic psychological needs)는 인간 욕구가 보편적이라고 주장"},{"t":"def","term":"WEIRD","text":"헨릭(Henrich) 등이 2010년 심리학 연구의 대상이 서구, 교육받은, 산업화된, 부유한, 민주적 사람에 치우쳤다고 지적"}],"ebs27sd_t3_18":[{"t":"tree","title":"소셜 미디어와 건강 증진","root":"공중보건","branches":[["건강 증진(health promotion)","사람들이 건강을 스스로 관리하도록 돕는 활동"],["건강 커뮤니케이션(health communication)","정보 전달과 행동 변화(behavior change)를 목표로 한다"],["소셜 미디어","캠페인 확산과 지지 공동체 형성에 쓰이지만 잘못된 정보 확산이라는 위험도 있다"]]}],"ebs27sd_t3_19":[{"t":"def","term":"화용론(pragmatics)","text":"언어학에서 말이 맥락에서 어떻게 쓰이는지 연구"},{"t":"tree","title":"인사와 사회적 규칙","root":"화용론의 이론","branches":[["공손성 이론(politeness theory)","브라운과 레빈슨(Brown & Levinson, 1978)의 이론으로 체면(face)을 지키려는 언어 행동을 설명"],["의사소통 능력(communicative competence)","델 하임스(Dell Hymes)의 개념으로 문법뿐 아니라 사회적 규칙을 아는 능력"]]}],"ebs27sd_t3_20":[{"t":"def","term":"\"숨길 것이 없다\"는 주장","text":"법학자 다니엘 솔로브(Daniel Solove)가 2007년 논문에서 프라이버시를 은폐 문제로만 보는 오해라고 비판"},{"t":"tree","title":"프라이버시 관련 개념","root":"프라이버시","branches":[["감시(surveillance)와 데이터 수집(data collection)","개인 통제권을 약화시킬 수 있다"],["정보 프라이버시(informational privacy)","자기 정보의 흐름을 통제할 권리"]]}],"ebs27sd_t3_21":[{"t":"def","term":"BIRGing(basking in reflected glory)","text":"로버트 치알디니(Robert Cialdini) 등이 1976년 성공한 팀과 자신을 연결 지어 영광을 누리는 현상이라 불렀다"},{"t":"def","term":"대리 성취(vicarious achievement)","text":"팬이 팀의 성공을 자기 일처럼 느끼는 것 · 사회 정체성 이론(social identity theory)이 이를 설명"}],"1526d34fbd90e600_20":[{"t":"tree","title":"도덕 교육","root":"교육학에서는 지식 전달뿐 아니라 가치와 태도를 길러 주는 영역을 중요하게 본다","branches":[["도덕 교육·인성 교육","도덕 교육(moral education)과 인성 교육(character education)"],["잠재적 교육과정","학교가 공식 교과 밖에서 은연중에 가르치는 내용(hidden curriculum)"],["교수법","새로운 교수법(teaching method)이나 기술이 등장할 때마다 교육 문제를 한 번에 해결해 줄 것이라는 기대가 반복되어 왔다"]]}],"1526d34fbd90e600_21":[{"t":"table","title":"협업 과부하","head":["개념","내용"],"rows":[["연결(hyperconnectivity)","현대 조직에서는 사내 메신저와 협업 도구(enterprise social media) 덕분에 구성원이 늘 연결되어 있다"],["협업 과부하(collaboration overload)","연구자들은 회의와 메시지 응답이 지나치게 늘어나는 현상을 협업 과부하라고 부른다"],["집중 업무(deep work)","몰입해서 혼자 하는 작업, 즉 집중 업무와 창의적 시도가 협업과 어떻게 균형을 이루는지는 조직 심리학의 주요 주제다"]]}],"1526d34fbd90e600_22":[{"t":"vs","title":"전문직과 사회","cols":[{"name":"전문직(profession)","items":["의사, 변호사 같은 전문직은 오랜 훈련으로 얻은 전문 지식과 사회적 특권을 갖는다","전문직이 외부 간섭 없이 스스로 판단하는 자율성(autonomy)"]},{"name":"사회","items":["사회학에서는 이를 전문직과 사회 사이의 암묵적 사회적 계약(social contract)으로 설명하기도 한다","그 판단에 대해 사회에 답할 책임인 책무성(accountability)"]}]},{"t":"def","term":"전문직 윤리(professional ethics)","text":"자율성과 책무성은 서로 긴장 관계에 놓이며, 전문직 윤리는 이 긴장을 다루는 규범이다"}],"1526d34fbd90e600_23":[{"t":"vs","title":"아름다움과 숭고","cols":[{"name":"아름다움(the beautiful)","items":["칸트(Immanuel Kant)는 『판단력 비판』에서 아름다움과 숭고를 구분했다","미적 경험에서는 상상력(imagination)과 지성(understanding)이 서로 자유롭게 작용한다고 보았다","고대 그리스인들은 비례와 정밀함을 아름다움의 기준으로 삼았다"]},{"name":"숭고(the sublime)","items":["거대한 폭풍이나 끝없는 바다처럼 우리의 이해 범위를 넘어서는 대상 앞에서 느끼는 감정","두려움과 쾌감이 함께 섞인다"]}]}],"1526d34fbd90e600_24":[{"t":"flow","title":"행정 서비스와 시민 참여","steps":["근대 국가는 세금을 거두어 치안, 소방, 도로, 폐기물 처리 같은 공공 서비스(public services)를 제공하는 행정 체계를 발전시켰다","이 과정에서 시민이 직접 맡던 역할이 정부로 넘어갔다는 비판이 있다","사회과학에서는 시민 참여(civic engagement)와 사회적 자본(social capital)이 공동체의 건강성을 가늠하는 지표로 쓰인다"]}],"1526d34fbd90e600_29":[{"t":"tree","title":"신호 이론","root":"동물행동학, 경제학의 신호 이론(signaling theory): 신호를 보내는 쪽과 받는 쪽의 이해관계가 다를 때 어떻게 신호가 믿을 만한 것으로 유지되는지를 다룬다","branches":[["비용이 드는 신호(costly signal)","공작의 꼬리처럼 흉내 내기 어렵고 비용이 드는 신호는 신뢰도가 높다고 설명된다"],["값싼 대화(cheap talk)","반대로 거짓이어도 비용이 들지 않는 말"],["핵심 논점","수신자가 이득을 보지 못하면 신호를 무시하도록 진화한다는 점"]]}],"1526d34fbd90e600_30":[{"t":"cause","title":"파생 수요","causes":["한 재화의 수요가 다른 재화나 활동의 수요에서 나오는 경우를 파생 수요(derived demand)라 한다","교통 수요는 대표적 예로, 사람들은 이동 자체보다 목적지에서 할 일을 위해 이동한다"],"result":"서비스는 재고로 쌓아 둘 수 없는 소멸성(perishability)이 있어 빈 좌석은 다시 팔 수 없다","effects":["교통지리학에서는 이를 용량(capacity) 관리의 어려움과 연결한다"]}],"1526d34fbd90e600_31":[{"t":"cause","title":"고고학 기록의 불완전성","causes":["고고학(archaeology)은 땅에 남은 유물과 유적으로 과거 문화를 복원한다","나무, 가죽, 직물 같은 유기물(organic materials)은 쉽게 썩어 남지 않는다"],"result":"기록이 한쪽으로 치우친다: 보존 편향(preservation bias)","effects":["석기, 토기처럼 잘 남는 물질문화(material culture)가 상대적으로 과대 대표되는 경향이 있다"]}],"1526d34fbd90e600_32":[{"t":"flow","title":"도피 이론","steps":["심리학자 로이 바우마이스터(Roy Baumeister)는 자기 인식(self-awareness)이 불쾌할 때 사람이 이를 피하려 한다는 도피 이론(escape theory)을 제시했다","실패나 비판 같은 자존감 위협(self-esteem threat) 뒤에는 주의를 돌릴 거리(distraction)를 찾는 경향이 나타난다고 한다","실험에서는 참가자에게 거짓 피드백(false feedback)을 주어 기분과 행동을 비교한다"]}],"1526d34fbd90e600_33":[{"t":"vs","title":"행위와 구조","cols":[{"name":"행위(agency)","items":["개인의 자유로운 행위"]},{"name":"구조(structure)","items":["이를 제약하는 사회, 문화 구조"]}]},{"t":"def","term":"문화 체계의 전제(premise)","text":"사회과학에서는 두 관계가 오래된 쟁점이며, 사람은 이미 내면화한(internalised) 문화 양식 안에서 생각하고 그 체계의 전제에서 논리적 귀결을 끌어낸다는 설명이 가능하다","ex":["수학에서 공리(axiom)로부터 정리를 증명하는 방식과 비교되기도 한다"]}],"1526d34fbd90e600_34":[{"t":"tree","title":"습관화","root":"습관화(habituation): 해롭지 않은 자극이 반복되면 반응이 줄어드는 가장 단순한 학습으로, 연합 없이 일어나는 비연합 학습(non-associative learning)에 속한다","branches":[["신기 공포(neophobia)","많은 동물에게는 낯선 대상을 피하는 신기 공포가 있어 생존에 유리하다"],["반복 노출","반복 노출에도 계속 놀라면 먹이 활동 같은 필요한 행동에 방해가 된다"]]}],"1526d34fbd90e600_35":[{"t":"table","title":"이민 이론","head":["관점","내용"],"rows":[["여러 관점","이민 연구에는 경제학, 사회학 등 여러 관점이 있다"],["경제학","개인을 비용과 이익을 비교하는 합리적 행위자(rational actor)로 보는 합리적 선택(rational choice) 이론을 쓴다"],["이민 요인","떠나게 하는 배출 요인(push factor)과 끌어당기는 흡인 요인(pull factor)으로 나뉜다"],["사회학","이주 네트워크(migrant network)도 중시한다"]]}],"1526d34fbd90e600_36":[{"t":"cause","title":"친환경 제품의 비용","causes":["친환경 제품(green products)은 원료와 설계 제약 때문에 비용이 높을 수 있다","소비자가 적으면 대량 생산의 이점인 규모의 경제(economies of scale)를 얻기 어렵다"],"result":"기업이 새 제품 때문에 기존 주력 제품 판매가 줄어드는 현상은 자기잠식(cannibalization)이라 한다","effects":["소수 고객을 겨냥하는 틈새시장(niche market) 전략도 관련 개념이다"]}],"1526d34fbd90e600_37":[{"t":"vs","title":"사회적 로봇","cols":[{"name":"사회적 로봇(social robot)","items":["눈, 얼굴 같은 요소로 사람과 상호작용하도록 설계된 로봇이다","로봇 공학의 인간-로봇 상호작용(human-robot interaction, HRI) 분야는 사람이 기계에 감정과 의도를 투영하는 의인화(anthropomorphism)를 다룬다"]},{"name":"스마트홈 비서(smart-home assistant)","items":["스마트 스피커 같은 비서와는 사회적 존재감(social presence)에서 차이가 난다"]}]}],"1526d34fbd90e600_38":[{"t":"flow","title":"재료과학","steps":["인류 문명은 석기, 청동기, 철기 시대처럼 쓰는 재료로 구분되기도 한다","재료과학(materials science)은 재료의 내부 구조(microstructure)와 성질(property)의 관계를 다루며, 열처리(heat treatment)나 합금(alloy) 제조로 금속의 강도를 바꿀 수 있음을 설명한다","현대에는 용도에 맞춰 재료를 설계하는 접근이 발달했다"]}],"1526d34fbd90e600_39":[{"t":"flow","title":"시장 세분화","steps":["20세기 대량 생산(mass production)은 표준화된 제품을 싸게 공급했다","이후 개인화(personalization) 요구가 커졌다","마케팅에서 시장 세분화(market segmentation)는 소비자를 취향에 따라 나눠 맞춤 전략을 쓰는 방식이다","사회학에서 나온 신부족(neo-tribes) 개념은 같은 취향을 공유하는 소집단 소비 문화를 설명하는 데 쓰인다"]}],"1526d34fbd90e600_40":[{"t":"flow","title":"DIKW 피라미드","steps":["자료(data)","정보(information)","지식(knowledge)","지혜(wisdom)"]},{"t":"def","term":"정보 과잉(information overload)","text":"정보가 너무 많아 판단이 어려워지는 현상이다","ex":["정보과학은 자료-정보-지식-지혜의 단계를 DIKW 피라미드로 설명한다","정보 접근이 쉬워질수록 무엇이 중요한지 가려내는 판단력이 더 중요해진다는 논의가 있다"]}],"1526d34fbd90e600_41":[{"t":"vs","title":"실험군과 대조군","cols":[{"name":"실험군(experimental group)","items":["과학 실험에서 처치를 받는다"]},{"name":"대조군(control group)","items":["처치를 받지 않아 실험군과 비교한다"]}]},{"t":"table","title":"실험 설계 장치","head":["장치","역할"],"rows":[["무작위화(randomization)","대상을 무작위로 배정하여 두 집단의 차이를 줄이기 위한 방법이다"],["위약(placebo)·이중 맹검(double-blind)","기대 효과와 연구자의 편향을 막는다"],["혼입 변수(confounding variable)","결과를 흐리는 변수로, 통제하는 데 쓰인다"]]}],"1c31688eaa581901_20":[{"t":"tree","title":"허위정보","root":"허위정보는 오정보와 허위조작정보로 나눌 수 있다","branches":[["오정보(misinformation)","의도 없이 퍼진다"],["허위조작정보(disinformation)","의도적으로 퍼뜨린다"],["필터 버블·반향실 효과","소셜 미디어에서는 알고리즘이 비슷한 의견만 보여 주는 필터 버블(filter bubble)과 반향실 효과(echo chamber)가 문제로 지적된다"],["미디어 리터러시(media literacy)","이를 줄이는 역량으로 강조된다"]]}],"1c31688eaa581901_21":[{"t":"flow","title":"민족지와 현지 조사","steps":["20세기 초 인류학은 서재에서 자료만 읽던 안락의자 인류학(armchair anthropology)에서 현지 조사(fieldwork)로 방향을 바꿨다","문화 집단을 직접 기록한 글을 민족지(ethnography)라 하고, 말리노프스키(Malinowski)는 오래 머무는 참여 관찰(participant observation) 방법을 정착시켰다","초기 연구가 식민지 관리, 선교사 같은 현지 중개인에 의존했다는 점은 이후 비판받았다"]}],"1c31688eaa581901_22":[{"t":"table","title":"도덕적 책임","head":["개념","내용"],"rows":[["도덕적 책임(moral responsibility)","철학에서 자유의지(free will)와 도덕적 행위 주체(moral agency)에 관한 논의와 이어진다"],["지각력(sentience)","감각을 느끼는 능력으로 도덕적 판단 능력과 구별된다"],["도덕의 성격","도덕이 보편 진리인지 사회가 만든 구성물(social construct)인지는 도덕 실재론과 상대주의가 맞서는 쟁점이다"]]}],"1c31688eaa581901_23":[{"t":"table","title":"경이감","head":["인물","내용"],"rows":[["플라톤과 아리스토텔레스","철학이 경이(wonder, 그리스어 thaumazein)에서 시작한다고 보았다"],["뉴턴(Isaac Newton)","만유인력의 법칙(law of universal gravitation)으로 사과의 낙하와 천체 운동을 하나의 원리로 설명했다"],["고대 문화","일식, 월식 같은 천체 현상은 신화로 설명되기도 했다"]]}],"1c31688eaa581901_24":[{"t":"flow","title":"사무 공간 설계","steps":["1950년대 독일의 뷔로란트샤프트(Bürolandschaft) 운동에서 시작","1960년대 허먼 밀러(Herman Miller)의 액션 오피스(Action Office)는 이후 칸막이형 책상(cubicle)으로 이어졌다"]},{"t":"vs","title":"개방형 사무실","cols":[{"name":"장점","items":["개방형 사무실(open-plan office)은 벽을 없애 소통을 늘리려는 설계다","협업에는 유리하다"]},{"name":"단점","items":["소음과 집중력 저하가 단점으로 연구된다"]}]}],"1c31688eaa581901_29":[{"t":"vs","title":"빅토리아 시대","cols":[{"name":"번영","items":["빅토리아 시대(Victorian era)는 빅토리아 여왕이 재위한 1837~1901년","산업혁명(Industrial Revolution)과 대영제국의 확장으로 번영"]},{"name":"사회 문제","items":["도시화(urbanization)로 빈민가(slum)와 열악한 노동 조건이 사회 문제가 되었고 찰스 디킨스 같은 작가가 이를 소설에 담았다","계급 사이의 격차가 큰 사회였다"]}]}],"1c31688eaa581901_30":[{"t":"tree","title":"행동경제학","root":"행동경제학(behavioral economics)은 사람이 늘 합리적으로 선택하지 않는다는 점을 연구한다","branches":[["시스템 1·2","대니얼 카너먼(Daniel Kahneman)은 빠르고 직관적인 시스템 1과 느리고 숙고하는 시스템 2로 사고를 설명했다"],["휴리스틱(heuristic)","어림짐작으로 효율적이지만 인지 편향(cognitive bias)과 확증 편향(confirmation bias)을 낳는다"]]}],"1c31688eaa581901_31":[{"t":"cause","title":"주광성","causes":["많은 곤충은 빛을 향해 움직이는 성질인 주광성(phototaxis)을 보이는 것으로 알려져 왔다","나방이 달이나 별처럼 멀리 있는 빛을 기준 삼아 일정한 각도로 날아 방향을 잡는다는 횡방향 정위(transverse orientation) 가설"],"result":"가까운 인공 조명 주변에서는 이 방식이 오히려 항법을 교란한다고 본다","effects":["곤충 감소와 빛 공해(light pollution)가 관련 연구 주제다"]}],"1c31688eaa581901_32":[{"t":"table","title":"커뮤니케이션 기술","head":["개념","내용"],"rows":[["기술 보급","미디어학에서는 어떤 통신 기술이 보급되는지를 기술 자체의 우수성보다 누가 투자하고 무엇을 기대하는가가 좌우한다고 본다"],["커뮤니케이션의 정치경제학","political economy of communication: 이를 다루는 분야"],["정보 격차(digital divide)","기술 접근성과 활용 능력의 차이로 생기는 핵심 개념"]]}],"1c31688eaa581901_33":[{"t":"tree","title":"야외 활동의 유형","root":"덴마크 건축가 얀 겔(Jan Gehl)은 『건물 사이의 삶』에서 도시의 야외 활동을 나눴다","branches":[["필수 활동(necessary)","통학, 출근처럼 환경과 상관없이 일어난다"],["선택 활동(optional)","날씨와 공간이 쾌적할 때 일어난다"],["사회적 활동(social)","도시의 야외 활동의 한 유형"],["머물러 있는 활동(staying activities)","공간의 매력과 연결된다"]]},{"t":"def","term":"도시의 질","text":"따라서 걷는 사람의 수만으로 도시의 질을 판단하기는 어렵다고 본다"}],"1c31688eaa581901_34":[{"t":"table","title":"루소의 인간관","head":["주제","내용"],"rows":[["인간관","루소(Jean-Jacques Rousseau, 1712-1778)는 인간이 본래 선하지만 사회가 이를 변질시킨다고 본 계몽기 사상가다"],["교육","『에밀』에서는 교육이 인간을 만든다고 보았고, 인간이 환경에 따라 변화하는 능력을 가졌다는 의미에서 가변성, 완성 가능성(perfectibility)을 강조했다"],["두 사랑","자기 보존에 대한 자연스러운 사랑(amour de soi)과 타인의 평가에 매이는 자존심(amour-propre)을 구별한 것도 유명하다"]]}],"1c31688eaa581901_37":[{"t":"cause","title":"항상성","causes":["항상성(homeostasis)은 체온, 수분 같은 내부 상태를 일정하게 유지하는 생물의 기능이다","배고픔, 갈증은 이를 회복하려는 동기로 작동한다"],"result":"동물이 무엇을 원하는지(motivation)가 생존과 건강에 연결된다","effects":["동물행동학(ethology)과 동물복지 연구가 다룬다","진화 관점에서는 이런 욕구가 적응적 가치를 갖는 방향으로 형성되었다고 본다"]}],"1c31688eaa581901_38":[{"t":"table","title":"자기-타자 구분","head":["개념","내용"],"rows":[["목표 지향적 행동의 기초","로봇공학과 인지과학에서는 행위 주체가 자신의 몸과 외부 대상을 구별하는 능력을 기초로 본다"],["사람의 경우","고유수용감각(proprioception)과 운동 명령의 복사본(efference copy)이 자기 움직임을 구별하게 돕는다"],["연결","체화된 인지(embodied cognition)와 행위 주체감(sense of agency)과도 연결된다"]]}],"1c31688eaa581901_39":[{"t":"vs","title":"보호구역 관리","cols":[{"name":"개입하지 않음","items":["국립공원 같은 보호구역(protected area)의 관리자는 사람이 개입하지 않고 자연 변화에 맡기는 방식"]},{"name":"적극적 개입","items":["적극적으로 개입하는 방식","생태학에서는 복원(restoration)의 목표를 정할 때 기준이 되는 상태(reference condition)와 자연적 변동성(natural variability)을 따진다","기후변화로 과거 상태를 기준으로 삼기가 어려워졌다는 논의도 있다"]}]}],"1c31688eaa581901_40":[{"t":"tree","title":"설계 특성","root":"언어학자 호켓(Charles Hockett)은 인간 언어를 다른 동물의 의사소통과 구분하는 설계 특성(design features)을 제시했다","branches":[["이중 분절(duality of patterning)","제한된 소리 단위를 조합해 무수한 의미를 만든다"],["자의성(arbitrariness)","소리와 의미 사이에 필연적 관계가 없다"],["생산성(productivity)","새 문장을 끝없이 만든다"],["동물의 의사소통","꿀벌의 춤이나 원숭이의 경고 울음은 고정된 신호 체계라는 점이 자주 비교된다"]]}],"1c31688eaa581901_41":[{"t":"table","title":"시적 언어와 구술 시","head":["개념","내용"],"rows":[["낯설게하기(defamiliarization)","러시아 형식주의(Russian formalism)는 시적 언어가 일상어를 의도적으로 낯설게 만든다는 점에 주목했다"],["시적 장치","두운(alliteration), 유운(assonance), 운율(rhythm), 압운(rhyme) 같은 장치가 이에 쓰인다"],["구술 시(oral poetry)","밀먼 패리(Milman Parry)와 앨버트 로드(Albert Lord)는 호메로스 같은 구술 시가 정형 표현(formulaic expression)에 의존해 암송된다고 연구했다"]]}],"2619638a571bb572_20":[{"t":"flow","title":"언어 혁신","steps":["영어사에서 셰익스피어는 수많은 어휘와 표현을 처음 쓰거나 널리 퍼뜨린 것으로 평가된다","이런 언어적 혁신(linguistic innovation)은 신조어(neologism) 형성과 어휘 확산을 통해 일어난다","2016년 밥 딜런(Bob Dylan)의 노벨 문학상 수상은 가사를 문학으로 볼 수 있느냐는 논쟁을 일으켰다"]}],"2619638a571bb572_21":[{"t":"tree","title":"플랫폼 노동","root":"디지털 플랫폼 노동(platform labour)은 업무를 잘게 쪼개 온라인 시장에서 거래한다","branches":[["아웃소싱(outsourcing)","기업이 업무 일부를 외부에 맡긴다"],["오프쇼어링(offshoring)","해외로 이전한다"],["크라우드워크(crowdwork)","불특정 다수에게 일을 맡긴다"],["지리적 고착성(geographical stickiness)","경제지리학에서 일이 특정 장소에 묶이는 정도를 설명하는 표현"]]}],"2619638a571bb572_22":[{"t":"vs","title":"협력적 경쟁","cols":[{"name":"협력적 경쟁(coopetition)","items":["경영학에서 협력과 경쟁을 동시에 하는 관계","브란덴버거와 네일버프(Brandenburger & Nalebuff)가 1996년 책으로 널리 알렸다","스포츠 산업은 리그, 구단, 후원사가 얽힌 생태계(ecosystem)로 설명된다"]},{"name":"제로섬(zero-sum) 게임","items":["한쪽이 이기면 다른 쪽이 진다","협력적 경쟁은 이런 게임이 아니라는 게임 이론(game theory)의 관점과 이어진다"]}]}],"2619638a571bb572_23":[{"t":"cause","title":"배차 빈도와 접근성","causes":["대중교통 계획에서는 속도 못지않게 배차 간격(headway)과 운행 빈도(frequency)가 중요하다","승객은 이동 시간뿐 아니라 기다리는 시간(waiting time)까지 합쳐 체감한다"],"result":"배차가 잦으면 시간표를 보지 않고도 이용할 수 있어 접근성(accessibility)이 높아진다","effects":["교통계획에서는 빈도와 넓은 노선망 중 무엇을 우선하느냐가 흔한 쟁점이다"]}],"2619638a571bb572_24":[{"t":"vs","title":"문화 관광","cols":[{"name":"문화 관광(cultural tourism)","items":["culturtainment는 문화(culture)와 오락(entertainment)을 합친 말로 문화유산, 공연, 축제를 관광 상품으로 만드는 흐름","지역 경제에 도움을 준다"]},{"name":"상품화(commodification) 비판","items":["지역 문화가 상품처럼 변한다","이때 진정성(authenticity)을 어떻게 보느냐가 학계의 논쟁점이다"]}]}],"2619638a571bb572_29":[{"t":"flow","title":"누적적 문화","steps":["인류학자 조지프 헨릭(Joseph Henrich)은 『성공의 비밀』(2016)에서 문화적 학습(cultural learning)과 누적적 문화를 논했다","사회적 학습(social learning)으로 쌓이는 지식은 세대를 거쳐 전달되며 개인이 혼자 발명하기 어려운 수준에 이른다","이런 누적적 문화(cumulative culture)는 집단 두뇌(collective brain)라는 비유로도 설명된다"]}],"2619638a571bb572_30":[{"t":"vs","title":"윤리 이론의 대비","cols":[{"name":"결과주의·절대주의","items":["행위의 결과를 중시하는 결과주의(consequentialism)","절대적 기준이 있다고 보는 도덕적 절대주의(moral absolutism)"]},{"name":"의무론·상대주의","items":["규칙, 의무를 중시하는 의무론(deontology)","문화, 상황에 따라 다르다고 보는 상대주의(relativism)"]}]},{"t":"def","term":"상황 윤리(situational ethics)","text":"신학자 조지프 플레처(Joseph Fletcher)가 1966년 책으로 널리 알린 이론이다"}],"2619638a571bb572_31":[{"t":"table","title":"곡물 무역","head":["개념","내용"],"rows":[["상품 거래(commodity trading)","곡물 거래는 가격 변동이 큰 상품 거래의 대표적 분야"],["차익거래(arbitrage)","지역 간 가격 차이를 이용하는 거래가 이윤의 원천이 된다"],["정보 비대칭(information asymmetry)","경제학에서 거래 당사자 중 한쪽이 더 많은 정보를 가진 상황"],["대형 곡물 업체","20세기에는 카길(Cargill) 등 소수의 대형 곡물 업체가 국제 시장에서 큰 비중을 차지했다"]]}],"2619638a571bb572_32":[{"t":"tree","title":"협력 원리","root":"언어철학자 폴 그라이스(H. P. Grice)는 대화가 서로 협력한다는 전제 아래 이루어진다고 보고 협력 원리(cooperative principle)를 제시했다","branches":[["양(quantity)","격률(maxims)"],["질(quality)","격률(maxims)"],["관련성(relation)","격률(maxims)"],["태도(manner)","격률(maxims)"],["글쓰기 교육","독자의 기대에 맞추는 명료한 문체(style)가 이 원리와 연결되어 논의된다"]]}],"2619638a571bb572_33":[{"t":"vs","title":"건축주와 사용자","cols":[{"name":"건축주(client)","items":["건물을 사 주는 사람"]},{"name":"사용자(user)","items":["실제로 쓰는 사람","참여 설계(participatory design)는 사용자를 설계 과정에 참여시키는 방식","사후 사용 평가(post-occupancy evaluation)는 건물이 지어진 뒤 사용자 만족도와 성능을 점검하는 절차"]}]}],"2619638a571bb572_34":[{"t":"cause","title":"영구평화론","causes":["칸트(Immanuel Kant)는 『영구평화론』(1795)에서 공화적 헌법과 국제 질서가 평화의 조건이라고 주장했다","자유를 제멋대로 하는 것이 아니라 모든 사람의 자유가 공존할 수 있게 하는 법(rule of law) 아래에서 가능한 것으로 보았다"],"result":"이성(reason)에 따라 보편적 법칙을 세운다","effects":["정언명령(categorical imperative)과도 이어진다"]}],"2619638a571bb572_37":[{"t":"tree","title":"인지과학","root":"인지과학(cognitive science)은 철학, 심리학, 신경과학, 언어학, 컴퓨터과학이 함께 마음을 연구하는 학제 간 분야다","branches":[["심리철학(philosophy of mind)","철학은 마음이 무엇인가를 묻는 심리철학을 통해 기여해 왔다"],["대표적 주제","심신 문제(mind-body problem)와 의식(consciousness)"],["철학의 역할","여러 분야의 개념을 정리하는 철학의 역할은 학제 간 연구에서 자주 강조된다"]]}],"2619638a571bb572_38":[{"t":"table","title":"이야기의 설득력","head":["개념","내용"],"rows":[["이야기와 통계","심리학에서는 사람들이 통계보다 이야기에 더 쉽게 설득된다고 설명한다"],["일화적 증거(anecdotal evidence)","개별 사례에 근거하여 쉽게 기억되지만 대표성이 부족할 수 있다"],["서사 오류(narrative fallacy)","탈레브(Nassim Taleb)가 말한 우연한 사건에 이야기를 덧붙여 인과로 해석하는 경향"],["틀 짜기(framing)","같은 정보도 틀 짜기에 따라 다르게 받아들여진다"]]}],"2619638a571bb572_39":[{"t":"table","title":"비디오 게임과 아바타","head":["개념","내용"],"rows":[["게임 연구(game studies)","플레이어가 화면 속 인물인 아바타(avatar)를 통해 가상 세계에 개입하는 방식을 다룬다"],["몰입(immersion)","가상 세계에 깊이 빠져드는 경험"],["마법의 원(magic circle)","하위징아(Johan Huizinga)가 말한, 놀이가 일상과 구분된 규칙의 공간이라는 개념"],["체화(embodiment) 연구","아바타의 몸과 플레이어의 몸이 어떻게 연결되는지 묻는다"]]}],"2619638a571bb572_40":[{"t":"table","title":"공연예술의 현장성","head":["인물·분야","내용"],"rows":[["공연예술(performing arts)","배우와 관객이 같은 시간과 공간에 있다는 현장성(liveness)이 특징이다"],["필립 아우슬랜더(Philip Auslander)","녹화, 방송 같은 매체화(mediatization)와 라이브를 대비해 이 개념을 논의했다"],["벤야민(Walter Benjamin)","복제 시대에 작품의 아우라(aura)가 약해진다고 보았다"],["기호학(semiotics)","공연을 시간과 공간 속에서 펼쳐지는 기호로 분석한다"]]}],"2619638a571bb572_41":[{"t":"cause","title":"복식사의 증거","causes":["복식사(history of dress)는 옷의 변천을 연구하지만 직물 조각은 남아도 완전한 의복은 드물다"],"result":"연속적 증거를 얻기 어렵다","effects":["회화, 조각, 문헌 같은 시각 자료(visual sources)와 직물 연구가 함께 쓰인다","사료 비판(source criticism)은 그런 자료가 얼마나 믿을 만한지 따지는 역사학의 기본 방법이다"]}],"442bb3463db2c18c_20":[{"t":"table","title":"인공지능과 의사결정","head":["개념","내용"],"rows":[["알고리즘 의사결정(algorithmic decision-making)","인공지능(AI)이 의사결정에 쓰이면서 인간 판단의 역할이 논쟁이 되고 있다"],["자동화 편향(automation bias)","사람이 기계의 판단을 지나치게 신뢰하는 경향"],["인간 개입 체계(human-in-the-loop)","중요한 결정에 사람이 꼭 관여하는 설계"]]}],"442bb3463db2c18c_21":[{"t":"vs","title":"이분법과 스펙트럼","cols":[{"name":"이분법(binary)","items":["어떤 현상을 있다/없다로 나눈다"]},{"name":"스펙트럼(spectrum)","items":["연속선이며 이분법과 대비되는 개념","번아웃(burnout)은 2019년 세계보건기구(WHO)가 질병분류(ICD-11)에 직업 관련 현상으로 포함했다","크리스티나 마슬라크(Christina Maslach)는 번아웃을 소진(exhaustion), 냉소(cynicism), 효능감 저하(reduced efficacy)의 세 요소로 설명했다"]}]}],"442bb3463db2c18c_22":[{"t":"table","title":"구술 문화와 평등","head":["관점","내용"],"rows":[["월터 옹과 매클루언","구술성과 문자성을 연구한 월터 옹(Walter Ong)과 마셜 매클루언(Marshall McLuhan)은 의사소통 매체가 사회 구조와 사고방식에 영향을 준다고 보았다"],["인류학","수렵채집 사회가 위계가 약하고 평등주의(egalitarianism)적이라는 점이 자주 언급된다"],["정치 이론","발언권의 분배가 규범과 권력 관계를 만든다는 점은 정치 이론에서도 논의된다"]]}],"442bb3463db2c18c_23":[{"t":"cause","title":"단어의 의미 변화","causes":["프랑스 사회학자 앙리 르페브르(Henri Lefebvre)는 자본주의 아래에서 단어가 본래의 지시 대상에서 떨어져 나간다고 비판했다","비슷한 맥락에서 보드리야르(Jean Baudrillard)의 시뮬라크르(simulacrum) 개념도 자주 인용된다"],"result":"그린워싱(greenwashing)처럼 광고가 자연 같은 이미지를 상품에 붙이는 방식","effects":["소비문화 연구의 주제다"]}],"442bb3463db2c18c_24":[{"t":"tree","title":"그림자 표현","root":"회화에서 그림자 표현은 입체감과 공간감을 주는 핵심 기법이다","branches":[["스키아그라피아(skiagraphia)","고대 그리스에서는 화가 아폴로도로스(Apollodorus)가 명암 효과를 쓴 그림을 그렸다고 전하며, 이를 그림자 그림이라 부른다"],["르네상스 이후","명암법(chiaroscuro)과 원근법(perspective)이 발달했다"],["그림자의 구별","몸에 붙은 그림자(attached shadow)와 물체가 던지는 그림자(cast shadow)는 구별되는 용어다"]]}],"442bb3463db2c18c_29":[{"t":"table","title":"인출 연습","head":["개념","내용"],"rows":[["인출 연습(retrieval practice)","인지심리학에서는 배운 내용을 다시 꺼내 보는 연습이 단순 재독보다 장기 기억에 효과적이라는 시험 효과(testing effect)가 알려져 있다"],["바람직한 어려움(desirable difficulty)","로버트 비요크(Robert Bjork)가 제안한, 학습 중 겪는 적절한 어려움이 오히려 장기적 학습을 돕는다는 개념"],["유창성의 착각(illusion of fluency)","반복해서 읽으면 익숙해져 안다고 착각하는 것"]]}],"442bb3463db2c18c_30":[{"t":"vs","title":"내재적 동기와 외재적 동기","cols":[{"name":"내재적 동기(intrinsic motivation)","items":["활동 자체가 즐거워서 한다","에드워드 데시(Edward Deci)와 리처드 라이언(Richard Ryan)의 자기결정 이론(self-determination theory)은 자율성(autonomy), 유능감(competence), 관계성(relatedness)이 동기의 핵심이라고 설명한다"]},{"name":"외재적 동기(extrinsic motivation)","items":["보상, 벌 때문에 한다","외적 보상과 내재적 흥미의 관계를 다룬 과잉정당화 효과(overjustification effect)도 연구된다","행동주의의 조작적 조건형성(operant conditioning)은 보상과 벌로 행동을 바꾼다고 설명한다"]}]}],"442bb3463db2c18c_31":[{"t":"cause","title":"기술 노후화","causes":["디지털 보존(digital preservation)은 디지털 자료를 오랜 기간 접근 가능하게 유지하는 활동이다","종이책과 달리 파일은 저장 매체와 형식이 빠르게 바뀐다"],"result":"기술 노후화(obsolescence)가 문제가 된다","effects":["새 형식으로 옮기는 마이그레이션(migration)","옛 환경을 재현하는 에뮬레이션(emulation)","자료 설명 정보인 메타데이터(metadata) 관리"]}],"442bb3463db2c18c_32":[{"t":"vs","title":"확산적 사고와 수렴적 사고","cols":[{"name":"확산적 사고(divergent thinking)","items":["길포드(J. P. Guilford)가 구분한, 하나의 문제에서 여러 해결책을 내는 사고"]},{"name":"수렴적 사고(convergent thinking)","items":["하나의 답을 찾는 사고","심리학에서 창의성(creativity)은 보통 새로움(novelty)과 유용성(usefulness)을 모두 갖춘 산출물로 정의된다","연구에서는 창의성을 개인의 특성, 과정, 산출물, 환경의 측면에서 나눠 보기도 한다"]}]}],"442bb3463db2c18c_34":[{"t":"table","title":"음악 인지","head":["개념","내용"],"rows":[["음악 인지(music cognition)","사람이 음정, 리듬, 조성(tonality)을 어떻게 지각하는지 심리 실험으로 탐구한다"],["문화와 훈련","음악 지각은 문화와 훈련에 따라 달라지는 면이 있다"],["공통성의 쟁점","박자(meter)와 조성(key)처럼 기본적인 지각이 청자 사이에 얼마나 공통적인지는 연구에서 쟁점이 된다"]]}],"442bb3463db2c18c_35":[{"t":"flow","title":"새의 노래 학습","steps":["명금류(songbird)는 어린 시기에 어른 새의 노래를 듣고 기억하는 감각 단계(sensory phase)를 거침","따라 부르며 연습하는 감각운동 단계(sensorimotor phase)를 거침","피터 말러(Peter Marler) 등은 새가 기억한 노래의 틀인 주형(template)과 자기 소리를 비교하며 교정한다고 설명","이 학습은 사람의 언어 습득과 자주 비교되며 결정적 시기(critical period)도 논의된다"]}],"442bb3463db2c18c_36":[{"t":"tree","title":"불 관리","root":"호주 원주민은 수천 년 동안 의도적으로 불을 놓아 풀밭을 관리하는 전통적 불 관리(cultural burning)를 해 왔다","branches":[["화재 체제(fire regime)","생태학에서 화재의 빈도, 강도, 계절을 합쳐 부르는 말"],["계획 소각(prescribed burning)","규모가 작은 소각으로 큰 산불(bushfire)의 위험을 줄이는 방법으로 쓰인다"]]}],"442bb3463db2c18c_37":[{"t":"vs","title":"형식지와 암묵지","cols":[{"name":"형식지(explicit knowledge)","items":["말로 옮기기 쉬운 지식"]},{"name":"암묵지(tacit knowledge)","items":["경험에 깃든 지식"]}]},{"t":"table","title":"조직 학습","head":["개념","내용"],"rows":[["조직 학습(organizational learning)","크리스 아지리스와 도널드 숀(Argyris & Schön)이 체계화한 개념으로, 조직이 경험으로부터 지식을 쌓고 행동을 고치는 과정"],["학습 조직(learning organization)","피터 센게(Peter Senge)의 개념도 유명하다"],["인적자원관리(HRM)","평가, 보상, 교육으로 학습을 지원한다"]]}],"442bb3463db2c18c_38":[{"t":"cause","title":"외부효과","causes":["환경경제학에서는 오염처럼 시장 거래 밖에서 제3자에게 비용을 미치는 현상을 외부효과(externality)라 한다"],"result":"아서 피구(Arthur Pigou)가 제안한 피구세(Pigouvian tax)는 오염자에게 비용을 부담시켜 이를 내부화하려는 세금이다","effects":["배출량에 직접 부과하는 배출세(emissions tax)와 기술 기준을 정하는 규제를 비교하는 것이 정책 논쟁의 핵심이다"]}],"442bb3463db2c18c_39":[{"t":"vs","title":"재현과 추상","cols":[{"name":"재현적(representational) 작품","items":["대상을 현실처럼 보여 준다","재현 예술은 관객이 그럴듯한 세계를 마음속에 그리는 심성 모형(mental model) 형성을 돕는다"]},{"name":"추상적(abstract) 작품","items":["형태, 색 자체를 강조한다","형식주의(formalism)는 내용보다 양식(style)과 형식을 중시하는 관점이다"]}]}],"442bb3463db2c18c_40":[{"t":"cause","title":"기근의 원인","causes":["경제학자 아마르티아 센(Amartya Sen)은 1981년 저서에서 기근이 식량 부족뿐 아니라 사람들이 식량에 접근하는 권리(entitlement) 문제에서 비롯된다고 주장했다"],"result":"개발학의 취약성(vulnerability)은 위기에 노출되고 대처하기 어려운 정도를 가리킨다","effects":["생계 다각화(livelihood diversification)","식량 안보(food security)"]}],"442bb3463db2c18c_41":[{"t":"tree","title":"윤리적 사고","root":"윤리학은 메타윤리(meta-ethics), 규범윤리(normative ethics), 응용윤리(applied ethics)로 나눈다","branches":[["비판적 사고(critical thinking)","주장과 증거를 평가해 판단하는 능력이다"],["공리주의(utilitarianism)","윤리적 문제를 다양한 관점에서 보는 대표 틀"],["의무론(deontology)","윤리적 문제를 다양한 관점에서 보는 대표 틀"],["덕 윤리(virtue ethics)","윤리적 문제를 다양한 관점에서 보는 대표 틀"]]}],"6eed40db54bbebb9_20":[{"t":"table","title":"게임과 학습","head":["개념","내용"],"rows":[["게임 기반 학습·게이미피케이션","교육학에서는 게임 요소를 학습에 활용하는 게임 기반 학습(game-based learning)과 게이미피케이션(gamification)이 연구된다"],["몰입(flow)","심리학자 칙센트미하이(Mihaly Csikszentmihalyi)가 도전과 능력이 균형을 이룰 때의 몰입 상태를 몰입이라 불렀다"],["내재적 동기(intrinsic motivation)","게임이 주의를 사로잡는 능력과도 연결된다"]]}],"6eed40db54bbebb9_21":[{"t":"tree","title":"비트루비우스의 건축 조건","root":"비트루비우스(Marcus Vitruvius Pollio)는 아우구스투스 시대에 활동한 로마 건축가로, 건축 이론서 『건축십서(De architectura)』를 썼다","branches":[["견고함","firmitas"],["유용함","utilitas"],["아름다움","venustas"],["영향","이 책은 르네상스 건축가들에게 큰 영향을 주었다"]]}],"6eed40db54bbebb9_23":[{"t":"cause","title":"시간 규율","causes":["산업혁명 이후 공장은 기계를 오래 돌릴수록 생산이 늘어나는 구조를 만들었다"],"result":"역사학자 E. P. 톰슨(E. P. Thompson)은 1967년 논문에서 산업 자본주의가 시계 중심의 시간 규율(time discipline)을 노동자에게 부과했다고 분석했다","effects":["교대 근무(shift work)와 노동, 자본(labor and capital)의 관계도 중요한 주제다"]}],"6eed40db54bbebb9_24":[{"t":"flow","title":"자화상과 셀카","steps":["자화상(self-portrait)은 거울이 보급되고 개인의 정체성이 중시된 르네상스 이후 널리 퍼진 장르다","알브레히트 뒤러(Albrecht Dürer)와 렘브란트(Rembrandt)는 여러 자화상을 남겼다","초상화는 인물의 지위와 이미지를 드러내는 수단이었고, 오늘날의 셀카(selfie)는 이를 대중화했다는 해석이 있다"]}],"6eed40db54bbebb9_29":[{"t":"vs","title":"자동 처리와 통제 처리","cols":[{"name":"자동 처리(automatic processing)","items":["연습으로 의식 없이도 수행된다","숙련된 움직임은 절차 기억(procedural memory)에 저장되며, 작은 동작들이 하나의 덩어리로 묶이는 청킹(chunking)이 일어난다"]},{"name":"통제 처리(controlled processing)","items":["주의를 요한다","신경과학에서는 소뇌와 기저핵이 운동 학습에 관여한다고 본다"]}]}],"6eed40db54bbebb9_30":[{"t":"vs","title":"경쟁이 동기에 미치는 영향","cols":[{"name":"경쟁이 노력을 끌어낸다","items":["라지어와 로젠(Lazear & Rosen, 1981)의 토너먼트 이론(tournament theory)은 순위에 따른 보상이 노력을 끌어낸다고 본다"]},{"name":"내재적 동기를 약화시킨다","items":["사회 비교(social comparison)와 외재적 보상(extrinsic reward)이 내재적 동기를 약화시킬 수 있다는 연구도 있다"]}]}],"6eed40db54bbebb9_31":[{"t":"table","title":"외국어 학습","head":["개념","내용"],"rows":[["강조점","외국어 교육에서는 의사소통 중심 접근(communicative approach)과 실제 자료(authentic materials) 사용이 강조된다"],["입력 가설(input hypothesis)","스티븐 크라셴(Stephen Krashen)은 이해 가능한 입력(comprehensible input)이 습득을 이끈다고 제안했다"],["정의적 여과(affective filter)","정서가 학습을 방해할 수 있다는 개념"]]}],"6eed40db54bbebb9_32":[{"t":"table","title":"비판적 사고","head":["개념","내용"],"rows":[["비판적 사고(critical thinking)","감정에 휩쓸리지 않고 근거를 따지는 능력"],["확증 편향(confirmation bias)","인지심리학은 이런 오류가 판단에 영향을 준다고 본다"],["계몽(Enlightenment)","칸트는 스스로 생각하는 용기(Sapere aude)로 설명했다"],["선전(propaganda)","감정에 호소해 판단을 흐리는 방식으로 연구된다"]]}],"6eed40db54bbebb9_33":[{"t":"cause","title":"주의 경제","causes":["허버트 사이먼(Herbert Simon)은 1971년 정보가 풍부해지면 주의(attention)가 부족해진다고 지적했다"],"result":"주의 경제(attention economy) 개념의 토대가 되었다","effects":["인간의 주의는 시간과 마찬가지로 한정된 자원이며 이를 둘러싼 경쟁이 디지털 산업의 핵심 쟁점이다"]}],"6eed40db54bbebb9_34":[{"t":"vs","title":"제도의 규칙","cols":[{"name":"공식적(formal) 규칙","items":["법처럼 공식적인 것","제도경제학자 더글러스 노스(Douglass North)는 제도(institution)를 사회의 게임 규칙으로 정의했다"]},{"name":"비공식적(informal) 규칙","items":["관습, 규범 같은 것","철학자 존 설(John Searle)은 사회적 실재(social reality)를 규칙과 약속이 만든다고 분석했다","중앙 집중적(centralized) 규칙과 분산된 자율적 질서의 대비도 흔한 논의다"]}]}],"6eed40db54bbebb9_35":[{"t":"flow","title":"관광과 교통수단","steps":["관광학에서 교통수단의 발달은 대중 관광의 성장 요인으로 꼽힌다","1841년 토머스 쿡(Thomas Cook)이 철도를 이용한 단체 여행을 조직한 것이 근대 관광의 시작으로 자주 언급된다","20세기에는 자동차(automobile)가 개인 이동의 자유를 넓혀 관광과 스포츠 관람 방식을 바꿨다"]}],"6eed40db54bbebb9_36":[{"t":"cause","title":"평판과 계약","causes":["제도경제학에서는 계약을 법원이 강제하기 어려운 곳에서 평판(reputation)이 계약 이행을 뒷받침한다고 본다","반복해서 거래하는 관계에서는 신뢰를 잃는 비용이 있다"],"result":"약속을 지킬 유인이 커진다","effects":["거래비용(transaction costs)과 계약 집행(contract enforcement)은 이 분야의 핵심 개념이다"]}],"6eed40db54bbebb9_37":[{"t":"table","title":"정서 전염과 경계","head":["개념","내용"],"rows":[["정서 전염(emotional contagion)","한 개체의 감정이 다른 개체에게 퍼지는 현상"],["포식자 경계(antipredator vigilance)","동물행동학에서는 포식자를 경계하는 행동이 집단에서 어떻게 나타나는지 연구한다"],["다수의 눈 효과(many-eyes effect)","무리가 클수록 개체가 경계에 쓰는 시간이 줄어드는 대표적 가설"]]}],"6eed40db54bbebb9_38":[{"t":"vs","title":"특허와 영업비밀","cols":[{"name":"특허(patent)","items":["발명을 공개하는 대가로 일정 기간 독점권을 주는 제도다"]},{"name":"영업비밀(trade secret)","items":["코카콜라 제조법처럼 비밀로 유지하는 정보를 보호하며 기간 제한이 없다","기업은 비용, 공개 부담, 보호 기간을 비교해 두 방식 중 하나를 고른다"]}]}],"6eed40db54bbebb9_39":[{"t":"table","title":"유지와 수리 연구","head":["개념","내용"],"rows":[["유지·수리 연구","기술사학과 과학기술학(STS)에서는 새 발명에만 쏠리던 관심을 비판하고 유지(maintenance)와 수리(repair)를 연구하는 흐름이 생겼다"],["대표 글","러셀과 빈셀(Russell & Vinsel)의 2016년 글 「유지하는 사람들을 칭송하라」"],["관련 개념","제품 수명주기(lifecycle), 계획적 노후화(planned obsolescence), 수리할 권리(right to repair)"]]}],"6eed40db54bbebb9_41":[{"t":"vs","title":"쥐기의 구분","cols":[{"name":"힘 쥐기(power grip)","items":["영장류학자 존 네이피어(John Napier)가 1956년 손의 쥐기를 나눈 것 중 힘으로 쥐는 쥐기"]},{"name":"정밀 쥐기(precision grip)","items":["손가락 끝으로 집는 쥐기","마주 보는 엄지(opposable thumb)와 정밀 쥐기는 도구 사용과 연결되어 인류 진화(human evolution)의 중요한 특징으로 논의된다","영장류(primates)는 종마다 쥐는 방식이 다르다"]}]}],"742da2dca0255ea5_20":[{"t":"cause","title":"조기 전문화","causes":["창의성 연구에서는 한 분야의 능력이 다른 분야로 전이되는지가 쟁점이다"],"result":"데이비드 엡스타인(David Epstein)은 2019년 책 『Range』에서 너무 일찍 한 분야로 좁히는 조기 전문화(early specialization)의 한계를 논했다","effects":["여러 분야에 걸친 박학가(polymath)나 학습 전이(transfer)도 관련 개념이다"]}],"742da2dca0255ea5_22":[{"t":"table","title":"인터넷과 정보 검증","head":["개념","내용"],"rows":[["익명성(anonymity)","인터넷에서는 익명성 때문에 정보와 상대의 신원을 확인하기 어렵다"],["피싱(phishing)","믿을 만한 곳인 척하며 개인정보를 빼내는 수법"],["사회공학(social engineering)","사람의 심리를 이용한 공격"],["정보 리터러시(information literacy)","출처를 비판적으로 평가하는 중요한 역량"]]}],"742da2dca0255ea5_23":[{"t":"tree","title":"박물관","root":"박물관은 관람객이 보는 전시실뿐 아니라 수장고(storage), 보존 처리(conservation), 연구(research) 같은 보이지 않는 영역을 갖는다","branches":[["큐레이터(curator)","소장품을 관리하고 전시를 기획한다"],["특별전","재정 압박 때문에 인기 있는 특별전(blockbuster exhibition)을 선호한다는 비판도 있다"]]}],"742da2dca0255ea5_24":[{"t":"vs","title":"이동성과 접근성","cols":[{"name":"이동성(mobility)","items":["이동 거리와 속도를 늘리는 것이 접근성을 높이는 유일한 방법은 아니다"]},{"name":"접근성(accessibility)","items":["목적지를 가까이 두는 근접성(proximity) 전략도 있다","도로를 넓히면 오히려 교통량이 늘어나는 유발 수요(induced demand)","지속 가능한 교통(sustainable transport)도 핵심 개념이다"]}]}],"742da2dca0255ea5_29":[{"t":"table","title":"동기 이론","head":["이론","내용"],"rows":[["기대 이론(expectancy theory)","심리학에서 사람이 노력할 때 성공 가능성과 보상의 가치를 계산한다고 제시한다"],["자기효능감(self-efficacy)","앨버트 밴두라(Albert Bandura)가 말한 자신이 과제를 해낼 수 있다는 믿음"],["끈기(persistence)","능력에 대한 믿음이 실제 노력과 끈기에 영향을 준다고 본다"]]}],"742da2dca0255ea5_31":[{"t":"vs","title":"가치의 구분","cols":[{"name":"생존 가치(survival values)","items":["경제적, 신체적 안전이 확보되지 않은 사회에서 중시된다"]},{"name":"자기표현 가치(self-expression values)","items":["정치학자 로널드 잉글하트(Ronald Inglehart)는 1977년 탈물질주의(postmaterialism) 이론을 제시해 경제적, 신체적 안전이 확보된 사회에서 자기표현, 삶의 질 같은 가치가 중시된다고 보았다","지식 경제(knowledge economy)에서는 일의 의미와 자율성이 중요해진다"]}]}],"742da2dca0255ea5_33":[{"t":"vs","title":"객관성과 주관성","cols":[{"name":"객관성","items":["과학은 개인의 느낌을 걷어 내고 수량화(quantification)할 수 있는 측정값으로 세계를 기술하려는 경향이 있다"]},{"name":"주관성","items":["철학에서는 개인의 경험에 속하는 주관성(subjectivity)과 여러 사람이 공유할 수 있는 상호주관성(intersubjectivity)을 구별한다","붉은색을 볼 때의 느낌처럼 개인만 직접 느끼는 질적 경험을 감각질(qualia)이라 부르며, 이런 경험을 측정으로 환원할 수 있는지가 논쟁거리다"]}]}],"742da2dca0255ea5_34":[{"t":"vs","title":"합리론과 경험론","cols":[{"name":"합리론(rationalism)","items":["서양 철학에서 이성을 지식의 근원으로 본다","플라톤(Plato)은 『국가』에서 눈에 보이는 세계보다 이성으로 파악하는 이데아(Form)의 세계를 참된 지식의 대상으로 보았고 동굴의 비유(allegory of the cave)로 이를 설명했다"]},{"name":"경험론(empiricism)","items":["감각 경험을 지식의 근원으로 본다","감각이 우리를 속일 수 있다는 점도 자주 언급된다"]}]}],"742da2dca0255ea5_35":[{"t":"cause","title":"자동화된 기술","causes":["인지심리학에서 작업 기억(working memory)은 용량이 제한되어 있다","연습으로 숙달된 기술은 자동화(automaticity)되어 작업 기억을 덜 쓴다"],"result":"인지 부하(cognitive load)가 줄어든다","effects":["동시에 두 과제를 하면 서로 방해하는 이중 과제 간섭(dual-task interference)이 생기지만, 전문가는 이를 덜 겪는다고 설명된다"]}],"742da2dca0255ea5_36":[{"t":"table","title":"사이버 물리 시스템","head":["개념","내용"],"rows":[["사이버 물리 시스템(cyber-physical system)","자동차, 항공기, 의료기기처럼 소프트웨어가 내장된 물리 시스템"],["오류와 취약점","코드가 복잡해질수록 오류(bug)와 보안 취약점(vulnerability)이 늘 수 있으며, 이는 사이버 보안(cybersecurity)과 안전 공학(safety engineering)의 핵심 주제다"],["임베디드 시스템(embedded system)","기기 안에 들어가 특정 기능을 제어하는 컴퓨터"]]}],"742da2dca0255ea5_37":[{"t":"table","title":"다윈과 감정","head":["개념","내용"],"rows":[["감정 표현의 진화","다윈(Charles Darwin)은 1872년 『인간과 동물의 감정 표현』에서 감정 표현을 진화의 관점에서 연구했다"],["자의식적 감정(self-conscious emotions)","당혹감, 수치심처럼 타인의 평가를 의식할 때 생기는 감정"],["사회적 감정(social emotions)","이런 감정은 사회적 규범 유지와 연결되어 논의된다"]]}],"742da2dca0255ea5_38":[{"t":"cause","title":"제도화","causes":["사회학에서 반복되는 행동이 공유된 규범과 틀로 굳어진다","피터 버거와 토마스 루크만(Berger & Luckmann)의 『실재의 사회적 구성』(1966)은 습관화된 행동이 제도로 굳어지는 과정을 설명했다"],"result":"제도화(institutionalization)","effects":["제도는 법, 규칙처럼 공식적(formal)일 수도, 관습처럼 비공식적(informal)일 수도 있다"]}],"742da2dca0255ea5_39":[{"t":"vs","title":"숲의 공생과 경쟁","cols":[{"name":"경쟁(competition)","items":["생태학에서 숲은 나무끼리의 경쟁뿐 아니라 협력도 나타나는 곳으로 연구된다"]},{"name":"균근(mycorrhiza) 네트워크","items":["나무뿌리와 균류가 공생하며 영양분을 나눈다는 주장은 우드 와이드 웹이라는 비유로 대중화되었고, 페터 볼레벤(Peter Wohlleben)의 『나무 수업』(2015)이 널리 알렸다","다만 그 범위와 의미는 학계에서 논쟁 중이다"]}]}],"742da2dca0255ea5_40":[{"t":"cause","title":"자연선택의 한계","causes":["자연선택(natural selection)은 이미 존재하는 유전적 변이(genetic variation) 중에서 작동한다"],"result":"이상적인 개체가 만들어지지는 않는다","effects":["생물학에서는 이를 진화적 제약(evolutionary constraint)과 절충(trade-off)으로 설명한다","적합도(fitness)는 절대적 최적이 아니라 특정 환경에서 번식에 성공하는 정도다"]}],"742da2dca0255ea5_41":[{"t":"vs","title":"분배적 협상과 통합적 협상","cols":[{"name":"분배적 협상(distributive negotiation)","items":["한쪽 이익이 다른 쪽 손해가 된다","이익이 모두 대립한다고 믿는 오류를 고정 파이 편향(fixed-pie bias)이라 부른다"]},{"name":"통합적 협상(integrative negotiation)","items":["쌍방 이익을 키운다","피셔와 유리(Fisher & Ury)의 『Getting to Yes』는 입장(position)이 아니라 이익(interest)에 주목할 것을 강조한다"]}]}],"98817bd6cb54dc06_20":[{"t":"table","title":"과학의 대중화","head":["개념","내용"],"rows":[["과학 커뮤니케이션(science communication)","과학 지식을 일반 대중에게 전달하는 활동"],["과학자의 이미지(stereotype)","소설, 영화, 드라마 같은 대중매체가 그리는 이미지는 대중이 과학을 바라보는 태도에 영향을 준다고 논의된다"],["결핍 모델(deficit model)","과학 지식 부족이 반대의 원인이라는 모델로 최근 비판받고 있다"]]}],"98817bd6cb54dc06_22":[{"t":"flow","title":"프로젝트 관리","steps":["프로젝트 관리(project management)는 범위, 일정, 비용을 관리해 목표를 달성하는 활동이다","프로젝트 관리 지식체계(PMBOK)는 착수, 계획, 실행, 감시, 종료의 과정으로 나눈다","계획 단계에서 다양한 방법론(methodology)을 비교한다","시공사(contractor)는 설계가 확정된 뒤 공사를 맡는 주체로 설계자와 역할이 다르다"]}],"98817bd6cb54dc06_23":[{"t":"table","title":"놀이와 역할","head":["인물","내용"],"rows":[["비고츠키(Lev Vygotsky)","발달심리학에서 상상 놀이(pretend play)가 아동 발달에서 중요하다고 보았다"],["조지 허버트 미드(George Herbert Mead)","아이가 놀이로 타인의 역할을 맡는 역할 취득(role-taking)을 통해 자아를 형성한다고 설명했다"],["서사 몰입(narrative transportation)","이야기에 깊이 빠져드는 개념으로 이와 연결된다"]]}],"98817bd6cb54dc06_24":[{"t":"cause","title":"사회정서 선택성 이론","causes":["심리학에서 로라 카스텐센(Laura Carstensen)의 사회정서 선택성 이론(socioemotional selectivity theory)은 남은 시간이 짧다고 느낀다"],"result":"정서적으로 의미 있는 목표를 우선한다","effects":["노년층이 부정 정보보다 긍정 정보에 주목하는 경향을 긍정성 효과(positivity effect)라 부른다","인지 기능 저하와 정서 조절(emotion regulation)의 변화가 함께 논의된다"]}],"98817bd6cb54dc06_29":[{"t":"vs","title":"태음력과 태양력","cols":[{"name":"태음력(lunar calendar)","items":["달의 주기를 따른다"]},{"name":"태양력(solar calendar)","items":["태양의 움직임을 따른다","고대 메소포타미아와 이집트에서 천체 관측이 발달했다"]}]},{"t":"def","term":"천문학(astronomy)","text":"역사학에서는 천문학의 시작을 농사 시기를 알려 주는 달력(calendar)의 필요와 연결해 설명하며, 점성술(astrology)은 천문학과 구분되는 별 점치기다"}],"98817bd6cb54dc06_30":[{"t":"cause","title":"팬 동일시","causes":["스포츠 마케팅(sport marketing)은 팬이 팀과 느끼는 감정적 일체감을 핵심 자원으로 본다","팬 동일시(fan identification)는 팀의 성공을 자신의 일처럼 느끼는 심리"],"result":"성공한 팀과 자신을 연결 짓는 영광 누리기(BIRGing)가 대표적 현상","effects":["이런 충성도(loyalty)는 은행, 보험 같은 일반 상품에서는 드물다"]}],"98817bd6cb54dc06_31":[{"t":"flow","title":"박물관과 수집","steps":["근대 박물관의 전신은 16~17세기 유럽 귀족의 호기심의 방(cabinet of curiosities, Wunderkammer)이다","미술사, 고생물학 같은 학문이 체계화되면서 분류(taxonomy)와 목록화(cataloguing)의 원칙이 생겼다","감정가(connoisseur)는 작품의 진위와 가치를 판단하는 전문가다"]}],"98817bd6cb54dc06_32":[{"t":"table","title":"현재 편향","head":["개념","내용"],"rows":[["현재 편향(present bias)","행동경제학에서 사람이 미래 이익보다 당장의 만족을 지나치게 중시하는 경향"],["쌍곡 할인(hyperbolic discounting)","이를 수학적으로 설명한다"],["정보 회피(information avoidance)","불편한 정보를 일부러 피하는 것으로 타조 효과(ostrich effect)로도 불린다"]]}],"98817bd6cb54dc06_33":[{"t":"cause","title":"원시 자연의 구성","causes":["환경사에서 윌리엄 크로논(William Cronon)은 1995년 「황야의 문제」에서 원시 자연(wilderness)이라는 관념이 사람이 만든 문화적 구성물이라고 주장했다","유럽 이주민은 아메리카, 호주를 사람 손이 닿지 않은 땅으로 여겼지만 원주민은 이미 그곳을 관리해 왔다"],"result":"이를 부정하는 법 개념으로 무주지(terra nullius)가 비판받는다","effects":[]}],"98817bd6cb54dc06_34":[{"t":"table","title":"새의 영역 행동","head":["개념","내용"],"rows":[["지저귐(song)","조류학에서 짝을 유혹하고 영역(territory)을 지키는 기능을 한다"],["친근한 적 효과(dear enemy effect)","이웃 개체는 위협이 낮고 낯선 개체는 위협이 높아 다르게 반응하는 현상"],["플레이백 실험(playback experiment)","녹음한 노래를 들려주는 대표적 검증 방법"]]}],"98817bd6cb54dc06_35":[{"t":"vs","title":"핵가족과 확대가족","cols":[{"name":"핵가족(nuclear family)","items":["사회학에서 부부와 자녀로 이루어진 가족","산업화로 핵가족이 늘었다는 통념"]},{"name":"확대가족(extended family)","items":["친척까지 포함하는 가족","유진 리트워크(Eugene Litwak)는 1960년 현대 사회에서도 친척 간 교류와 도움이 유지되는 수정 확대가족(modified extended family)을 제안했다 · 통념에 대한 반론이다"]}]}],"98817bd6cb54dc06_36":[{"t":"tree","title":"도시의 이미지","root":"케빈 린치(Kevin Lynch)는 『도시의 이미지』(1960)에서 사람들이 도시를 다섯 요소로 인식한다고 분석했다","branches":[["길(paths)","도시 인식의 요소"],["경계(edges)","도시 인식의 요소"],["구역(districts)","도시 인식의 요소"],["결절점(nodes)","도시 인식의 요소"],["랜드마크(landmarks)","도시 인식의 요소"],["인지 지도(cognitive map)","심리학자 톨먼(Edward Tolman)이 제안한 머릿속에 그린 공간 표상"]]}],"98817bd6cb54dc06_37":[{"t":"cause","title":"조정 실패","causes":["개발경제학에서는 여러 산업이 서로를 필요로 할 때 한쪽이 먼저 움직이지 않으면 모두 투자하지 않는다"],"result":"조정 실패(coordination failure)가 일어날 수 있다","effects":["로젠슈타인로단(Rosenstein-Rodan)의 빅 푸시(big push) 이론은 동시 투자가 필요하다고 주장했다","이런 상황에서는 서로 다른 균형이 존재하는 다중 균형(multiple equilibria)이 나타난다"]}],"98817bd6cb54dc06_38":[{"t":"table","title":"성과 평가","head":["개념","내용"],"rows":[["성과 평가(performance appraisal)","인사관리(HRM)에서 직원의 업무 성과를 판단하는 제도"],["360도 피드백(360-degree feedback)","상사 외에 동료, 부하, 고객까지 평가에 참여하는 방식"],["평가의 신뢰성","평가자의 편향(rater bias)과 정보 부족은 평가의 신뢰성을 떨어뜨리는 요인이다"]]}],"98817bd6cb54dc06_39":[{"t":"table","title":"수면의 진화적 기능","head":["개념","내용"],"rows":[["적응적 비활동 이론(adaptive inactivity theory)","수면의 진화적 기능에 대한 가설 중 하나로, 수면이 에너지를 절약하고 위험을 피하는 이점이 있다고 본다"],["비교","신진대사(metabolism)가 낮아지는 동면(hibernation)과 휴면 상태(torpor)와 비교되기도 한다"],["수면의 구분","렘수면(REM)과 비렘수면으로 나뉘며 일주기 리듬(circadian rhythm)이 이를 조절한다"]]}],"98817bd6cb54dc06_40":[{"t":"flow","title":"풍경 정원","steps":["영국에서는 17~18세기 귀족이 영지에 나무를 심고 경관을 꾸미는 풍경 정원(landscape garden)을 발전시켰다","역사학자 키스 토머스(Keith Thomas)는 『인간과 자연 세계』(1983)에서 자연에 대한 태도의 변화를 분석했다","땅과 나무는 소유와 지위를 드러내는 상징 경관(symbolic landscape)의 역할도 했다"]}],"98817bd6cb54dc06_41":[{"t":"tree","title":"프라이버시와 표현의 자유","root":"법학에서는 권리가 충돌할 수 있어 권리 간 형량(balancing)이 필요하다고 본다","branches":[["프라이버시권(right to privacy)","충돌하는 권리"],["표현의 자유(freedom of expression)","충돌하는 권리"],["알 권리(right to information)","충돌하는 권리"],["공익(public interest)","이 균형을 판단하는 중요한 기준"],["잊힐 권리(right to be forgotten)","유럽의 GDPR이 포함한다"]]}],"9a7f2faa2e99e669_20":[{"t":"tree","title":"스포츠 심리학","root":"스포츠 심리학(sport psychology)은 동기, 태도, 집중이 운동 수행에 미치는 영향을 연구한다","branches":[["심신 이원론(mind-body dualism)","이를 비판하고 몸과 마음을 함께 본다는 관점이 이를 뒷받침한다"],["자기효능감(self-efficacy)","노력과 끈기를 높이는 요인으로 꼽힌다"]]}],"9a7f2faa2e99e669_21":[{"t":"flow","title":"동물 의식 연구","steps":["도널드 그리핀(Donald Griffin)은 1976년 『동물 의식의 문제』를 통해 인지 동물행동학(cognitive ethology)을 열었다","행동주의(behaviorism)는 마음 대신 관찰 가능한 행동만 연구했고, 모건의 공준(Morgan's canon)은 낮은 수준의 설명으로 충분하면 높은 수준의 정신 능력을 가정하지 말라고 요구했다","2012년에는 케임브리지 의식 선언이 동물의 의식 가능성을 인정했다"]}],"9a7f2faa2e99e669_22":[{"t":"table","title":"얼굴 지각","head":["개념","내용"],"rows":[["파레이돌리아(pareidolia)","사람은 얼굴에 민감해 구름, 벽의 얼룩에서도 얼굴을 찾아낸다"],["방추상회(fusiform face area)","얼굴 인식에 관여하는 뇌 영역"],["의인화(anthropomorphism)","사물에 인간적 특성을 부여하며 제품 디자인과 마케팅에서 활용된다"]]}],"9a7f2faa2e99e669_23":[{"t":"cause","title":"몸 크기와 대사율","causes":["생물학의 비례 성장(allometry) 연구는 몸 크기에 따라 생리, 행동이 일정한 규칙으로 달라진다고 본다","몸집이 작을수록 체중당 대사율(metabolic rate)이 높다는 클라이버 법칙(Kleiber's law)이 대표적이다"],"result":"시각이 깜박임을 구별하는 임계 깜박임 융합률(flicker fusion rate)도 종마다 달라 시간 지각 차이를 설명하는 데 쓰인다","effects":[]}],"9a7f2faa2e99e669_24":[{"t":"flow","title":"관광산업의 통합","steps":["호텔, 항공사, 여행사가 따로 운영되던 구조에서 점차 통합되는 흐름","한 기업이 공급 사슬의 여러 단계를 소유하는 것을 수직 통합(vertical integration)이라 한다","항공권, 숙박을 묶은 패키지 여행(package tour)과 제트 여객기 도입으로 1950년대 후반부터 대중 관광(mass tourism)이 커졌다"]}],"9a7f2faa2e99e669_29":[{"t":"table","title":"유럽 복식","head":["개념","내용"],"rows":[["의복","중세 유럽에서 의복은 신분과 부를 드러내는 수단이었고, 직물 기술과 무역이 발달하면서 복식이 화려해졌다"],["사치 금지법(sumptuary laws)","신분에 따라 입을 수 있는 옷감과 색을 제한했다"],["유행","패션 연구에서는 모방과 구별 짓기를 통해 유행이 퍼진다는 이론이 자주 쓰인다"]]}],"9a7f2faa2e99e669_30":[{"t":"table","title":"표현 관습","head":["관습","내용"],"rows":[["표현 관습(convention)","희곡과 시에는 현실과 다른 표현 관습이 있다"],["독백(soliloquy)·방백(aside)","셰익스피어 극에서 인물이 생각을 관객에게 직접 드러내는 장치"],["코러스(chorus)","고대 그리스 비극에서 사건을 해설했다"],["불신의 자발적 중지(suspension of disbelief)","관객이 허구를 믿어 주는 것"]]}],"9a7f2faa2e99e669_31":[{"t":"vs","title":"보존과 보전","cols":[{"name":"보존(preservation)","items":["환경사에서 구별되어 쓰인다","존 뮤어(John Muir)는 자연을 인간의 이용에서 보호하는 쪽을 주장했다"]},{"name":"보전(conservation)","items":["기퍼드 핀쇼(Gifford Pinchot)는 지속 가능한 이용을 뜻하는 현명한 이용(wise use)을 주장했다","문화유산 분야에서는 보존, 복원(restoration), 수리의 윤리가 별도로 논의된다"]}]}],"9a7f2faa2e99e669_32":[{"t":"table","title":"비언어적 의사소통","head":["개념","내용"],"rows":[["비언어적 신호","의사소통 연구에서는 목소리의 높낮이, 크기 같은 준언어(paralanguage)와 몸짓, 표정(kinesics)을 비언어적 신호로 분류한다"],["고맥락·저맥락","에드워드 홀(Edward Hall)은 문화를 고맥락(high-context)과 저맥락(low-context)으로 나누어, 말보다 상황과 비언어 신호에 의존하는 정도가 다르다고 설명했다"],["메라비언의 법칙","메라비언(Mehrabian)의 7-38-55 법칙은 자주 오해된다"]]}],"9a7f2faa2e99e669_33":[{"t":"table","title":"상상력과 지각","head":["관점","내용"],"rows":[["아리스토텔레스(Aristotle)","『영혼에 관하여』에서 환상 능력(phantasia)을 감각 지각과 사고 사이의 능력으로 보았다"],["현대 심리학","정서가 지각을 편향시킨다고 연구하며, 두려움이 위협 자극을 더 쉽게 알아차리게 한다는 증거가 있다"],["감정 이론(theories of emotion)","정서와 지각의 관계는 핵심이다"]]}],"9a7f2faa2e99e669_34":[{"t":"table","title":"미술 시장과 제도","head":["개념","내용"],"rows":[["미술의 가치","작품 자체뿐 아니라 미술사의 맥락과 제도에도 좌우된다"],["제도론(institutional theory of art)","아서 단토(Arthur Danto)와 조지 디키(George Dickie)는 미술계(artworld)가 무엇이 예술인지 정한다고 설명했다"],["출처(provenance)","작품의 소장 이력으로 진위와 가치 판단에 중요하다"]]}],"9a7f2faa2e99e669_35":[{"t":"cause","title":"제곱-세제곱 법칙","causes":["갈릴레오(Galileo)는 크기가 커지면 부피가 길이의 세제곱, 단면적이 제곱으로 커진다는 제곱-세제곱 법칙(square-cube law)을 밝혔다","생물학자 홀데인(J. B. S. Haldane)의 1926년 글 「적절한 크기에 대하여」는 이 원리로 동물 크기와 낙하 충격을 설명했다"],"result":"동물이 클수록 체중에 비해 뼈가 약해진다","effects":[]}],"9a7f2faa2e99e669_36":[{"t":"vs","title":"식물의 방어","cols":[{"name":"화학적 방어","items":["식물은 곤충, 초식동물에게 먹히는 것을 막기 위해 이차 대사산물(secondary metabolite)로 독이나 쓴맛 물질을 만든다"]},{"name":"구조적 방어(structural defense)","items":["가시, 털 같은 구조","에를리히와 레이븐(Ehrlich & Raven, 1964)은 식물과 곤충이 서로 영향을 주며 진화하는 공진화(coevolution)를 제안했다"]}]}],"9a7f2faa2e99e669_37":[{"t":"cause","title":"스펙터클의 사회","causes":["기 드보르(Guy Debord)는 『스펙터클의 사회』(1967)에서 현대 사회가 이미지, 구경거리 중심으로 관계를 맺는다고 비판했다"],"result":"문화이론에서는 구경거리를 어떻게 인식하는지가 시대와 문화에 따라 다르다고 본다","effects":["지각 양식(mode of perception)은 문화적 틀에 따라 형성된다"]}],"9a7f2faa2e99e669_38":[{"t":"flow","title":"와류 방출","steps":["고층 건물은 바람이 건물 옆면에서 번갈아 소용돌이를 만드는 와류 방출(vortex shedding)로 흔들릴 수 있다","건축공학은 이를 줄이기 위해 모서리를 깎거나 비틀고, 건물 꼭대기에 동조 질량 감쇠기(tuned mass damper)를 설치한다","타이베이 101의 거대한 추가 대표적 예다"]}],"9a7f2faa2e99e669_39":[{"t":"table","title":"색의 역사","head":["연구","내용"],"rows":[["미셸 파스투로(Michel Pastoureau)","색채사 연구는 색의 의미와 위계가 시대마다 달랐음을 보여 준다"],["버린과 케이(Berlin & Kay)","인류학자로 1969년 연구에서 언어마다 기본 색 이름의 수와 등장 순서에 규칙이 있다고 주장했다"],["빨강","서양에서 빨강은 권력, 열정, 위험을 상징해 왔다"]]}],"9a7f2faa2e99e669_40":[{"t":"table","title":"의약 연구와 알고리즘","head":["개념","내용"],"rows":[["희귀 질환(rare disease)","제약 산업에서는 환자가 적어 연구 투자가 적은 질환과 방치된 질환이 문제다"],["신약 개발(drug discovery)","머신러닝(machine learning)은 약물 후보를 찾는 데 쓰이고 있다"],["10/90 격차(10/90 gap)","연구비가 부유한 나라의 질환에 편중되는 것으로 알고리즘 편향(algorithmic bias)과 함께 논의된다"]]}],"9a7f2faa2e99e669_41":[{"t":"vs","title":"결정질 고체와 비정질 고체","cols":[{"name":"결정질(crystalline) 고체","items":["원자가 규칙적으로 배열된다"]},{"name":"비정질(amorphous) 고체","items":["배열이 무질서하다","유리는 대표적인 비정질 고체로, 액체가 결정화되지 않고 빠르게 식어 굳은 과냉각 액체(supercooled liquid)로 설명되기도 한다","유리 전이(glass transition)는 액체가 유리처럼 굳어 가는 온도 구간을 가리킨다"]}]}],"a095e14b4f06cd05_20":[{"t":"vs","title":"두려움과 불안","cols":[{"name":"두려움(fear)","items":["눈앞의 위험에 대한 반응이다","위험에 대한 투쟁-도피 반응(fight-or-flight response)은 생존에 도움이 되도록 진화했다"]},{"name":"불안(anxiety)","items":["앞으로 닥칠 불확실한 위협을 예상할 때의 반응이다","걱정이 지나쳐 일상을 방해하면 범불안장애(generalized anxiety disorder)로 분류되며 인지행동치료(CBT)가 대표적 치료다"]}]}],"a095e14b4f06cd05_21":[{"t":"cause","title":"조건부 자기가치","causes":["심리학자 제니퍼 크로커(Jennifer Crocker)는 자기가치를 특정 영역의 성취에 두는 것을 조건부 자기가치(contingent self-worth)라 불렀다"],"result":"이런 사람은 결과에 따라 자존감(self-esteem)이 크게 흔들린다","effects":["사회 비교(social comparison)는 타인과 비교해 자신을 평가하는 경향이며, 외적 인정(external validation)에 의존하면 평가가 왜곡되기 쉽다"]}],"a095e14b4f06cd05_22":[{"t":"vs","title":"정보와 의미","cols":[{"name":"정보 이론(information theory)","items":["섀넌(Claude Shannon)이 1948년 제시했다","정보를 사건의 확률로 측정하며 메시지의 의미는 다루지 않는다"]},{"name":"기호학과 의미론","items":["기호학(semiotics)과 의미론(semantics)은 신호가 어떤 의미로 해석되는지를 다룬다","같은 자료도 해석하는 주체와 맥락에 따라 의미가 달라진다"]}]}],"a095e14b4f06cd05_24":[{"t":"flow","title":"외식 산업의 탄생","steps":["식품 산업은 전통적으로 생산, 보존, 유통에 초점을 두었다","18세기 후반 프랑스에서 레스토랑(restaurant)이라는 제도가 나타나 식사가 사교와 취향의 대상이 되었다","브리야사바랭(Brillat-Savarin)의 『미식 예찬』(1825)은 미식학(gastronomy)의 고전이다","오늘날에는 음식을 목적으로 한 미식 관광(culinary tourism)도 성장했다"]}],"a095e14b4f06cd05_29":[{"t":"cause","title":"해석 수준 이론","causes":["해석 수준 이론(construal level theory)은 시간, 공간, 사회적으로 가까운 대상일수록 구체적으로, 멀수록 추상적으로 해석한다고 설명한다"],"result":"이러한 심리적 거리(psychological distance)는 감정의 강도를 좌우한다","effects":["사람이 미디어 인물에게 느끼는 일방적 친밀감은 준사회적 관계(parasocial relationship)라 부른다"]}],"a095e14b4f06cd05_31":[{"t":"table","title":"동물의 사회적 학습","head":["개념","내용"],"rows":[["사회적 학습(social learning)","동물행동학에서 다른 개체를 보고 배우는 학습"],["가르침(teaching)","캐로와 하우저(Caro & Hauser, 1992)가 지식 있는 개체가 비용을 감수하며 학습자의 학습을 촉진하는 행동으로 정의했다"],["모방과 에뮬레이션","모방(imitation)과 모방 없이 결과만 따라 하는 에뮬레이션(emulation)도 구별된다"],["사례","미어캣이 새끼에게 먹이 다루는 법을 가르치는 사례가 자주 언급된다"]]}],"a095e14b4f06cd05_33":[{"t":"cause","title":"결핍과 터널 시야","causes":["인지심리학에서 주의(attention)와 작업 기억은 처리 용량이 제한된 인지 자원(cognitive resources)이다","센딜 멀레이너선과 엘다 샤퍼(Mullainathan & Shafir)의 『결핍의 경제학』은 결핍이 정신적 대역폭(bandwidth)을 줄인다고 설명했다"],"result":"주의를 좁히면 한 과제에는 유리하지만 주변 정보를 놓칠 수 있는 터널 시야(tunnel vision)가 생긴다","effects":[]}],"a095e14b4f06cd05_34":[{"t":"tree","title":"지리학","root":"지리학(geography)은 사물이 지표면 어디에 있는지뿐 아니라 왜 그곳에 있고 그것이 무엇을 의미하는지를 묻는다","branches":[["지리학의 제1법칙(Tobler's first law)","모든 것이 서로 관련 있지만 가까운 것일수록 더 관련 있다"],["핵심 개념","위치(location), 지역(region), 장소(place)"]]}],"a095e14b4f06cd05_35":[{"t":"table","title":"빙하와 물질 수지","head":["개념","내용"],"rows":[["빙하","빙하학(glaciology)에서 눈이 쌓여 다져진 얼음이 중력으로 흐르는 영속적 얼음 덩어리"],["축적(accumulation)","겨울에 쌓이는 적설"],["소모(ablation)","여름철 녹는 양"],["물질 수지(mass balance)","축적과 소모의 차이"],["빙상(ice sheet)","대륙 규모의 얼음으로 빙하와 구분한다"]]}],"a095e14b4f06cd05_36":[{"t":"cause","title":"진화적 불일치","causes":["인류가 수렵채집 시기에 많이 움직이도록 진화했다","오늘날의 좌식 생활(sedentary lifestyle)과 맞지 않는다"],"result":"진화의학이 논하는 진화적 불일치(evolutionary mismatch)","effects":["세계보건기구(WHO)는 신체 활동 부족을 만성질환의 위험 요인으로 본다","심혈관질환과 비만이 대표적이다"]}],"a095e14b4f06cd05_37":[{"t":"cause","title":"카오스 이론","causes":["규칙(결정론)을 따르는 계에서도 초기 조건의 아주 작은 차이가 큰 결과 차이를 낳는 민감한 의존성(sensitive dependence on initial conditions)이 있다"],"result":"장기 예측이 어렵다","effects":["에드워드 로렌츠(Edward Lorenz)가 1963년 기상 모형에서 발견했고 나비 효과(butterfly effect)로 대중화되었다","자석 진자는 이를 보여 주는 대표 장치다"]}],"a095e14b4f06cd05_38":[{"t":"cause","title":"아기 도식","causes":["콘라트 로렌츠(Konrad Lorenz)는 둥근 얼굴과 큰 눈 같은 아기의 특징이 보호하고 싶은 반응을 일으킨다는 아기 도식(Kindchenschema)을 제안했다"],"result":"이런 반응은 양육 동기(nurturing motivation)로 이어진다","effects":["감성 디자인(affective design)과 미학(aesthetics)은 형태가 소비자의 감정과 행동에 미치는 영향을 연구한다"]}],"a095e14b4f06cd05_40":[{"t":"cause","title":"기술적 실업","causes":["경제학자 케인스(John Maynard Keynes)는 1930년 기술 발전이 일자리를 줄이는 기술적 실업(technological unemployment)을 언급했다","오늘날 자동화(automation)와 인공지능은 노동 소득 분배에 영향을 준다고 논의된다"],"result":"기본소득(universal basic income) 같은 대안이 거론된다","effects":["일자리는 소득 분배와 삶의 의미의 기반으로 여겨진다"]}],"a095e14b4f06cd05_41":[{"t":"vs","title":"심리스 기술과 시임풀 디자인","cols":[{"name":"차분한 기술(calm technology)","items":["마크 와이저(Mark Weiser)는 1991년 유비쿼터스 컴퓨팅(ubiquitous computing)에서 최고의 기술은 일상에 스며들어 보이지 않는다고 주장했다","이 흐름이 차분한 기술이다"]},{"name":"시임풀 디자인(seamful design)","items":["반대로 시스템의 이음매를 드러내는 디자인도 연구된다","이들은 인간-컴퓨터 상호작용(HCI)의 주요 논쟁점이다"]}]}],"b2aae23e4f084ebb_20":[{"t":"vs","title":"시스템 1과 시스템 2","cols":[{"name":"시스템 1(직관)","items":["대니얼 카너먼(Daniel Kahneman)이 구분한 빠르고 자동적인 사고","직관은 효율적이지만 휴리스틱(heuristic)에 따른 체계적 오류를 낳을 수 있다"]},{"name":"시스템 2","items":["느리고 숙고적인 사고","불확실한 상황(uncertainty)에서 직관을 믿는 것이 좋은지는 심리학의 오랜 쟁점이다"]}]}],"b2aae23e4f084ebb_21":[{"t":"flow","title":"공론장의 형성","steps":["18~19세기 유럽에서 일기는 개인이 이성(reason)으로 자신을 성찰하는 도구였다","하버마스(Jürgen Habermas)의 『공론장의 구조변동』(1962)은 시민 계층이 편지, 일기, 살롱 같은 사적 영역에서 공론장(public sphere)을 형성했다고 설명했다","푸코(Michel Foucault)의 자기 기술(technologies of the self)도 자기 성찰 글쓰기를 다룬다"]}],"b2aae23e4f084ebb_22":[{"t":"cause","title":"라스트마일","causes":["라스트마일(last-mile) 배송은 물류 허브에서 최종 수취인에게 닿는 마지막 구간으로 비용 비중이 큰 단계로 꼽힌다","전자상거래(e-commerce) 성장"],"result":"도시 물류(urban logistics)의 혼잡과 배출이 문제가 되었다","effects":["화물 자전거(cargo bike)와 마이크로 허브(micro-hub)가 대안으로 논의된다"]}],"b2aae23e4f084ebb_23":[{"t":"vs","title":"명령 통제와 공시 규제","cols":[{"name":"명령 통제(command-and-control)","items":["행위를 직접 금지, 강제한다"]},{"name":"공시 규제(disclosure regulation)","items":["정보를 알리게 한다","캐스 선스타인(Cass Sunstein)은 넛지(nudge)처럼 선택의 자유를 유지하는 방식을 옹호했다","일부 학자는 공시가 소비자에게 정보 과잉만 준다고 비판했다"]}]}],"b2aae23e4f084ebb_24":[{"t":"vs","title":"시각 경로","cols":[{"name":"배쪽 경로(ventral stream)","items":["무엇인가","신경과학에서 밀너와 구델(Milner & Goodale)이 설명한 시각 정보 처리 경로"]},{"name":"등쪽 경로(dorsal stream)","items":["어떻게 행동할까","각 영역이 특정 기능에 특화되는 기능적 전문화(functional specialization)와 모듈성(modularity)은 뇌과학의 핵심 개념이다"]}]}],"b2aae23e4f084ebb_29":[{"t":"flow","title":"유행의 낙수 효과","steps":["사회학자 게오르크 짐멜(Georg Simmel)은 1904년 유행이 상류층이 먼저 입고 하층이 모방하면 다시 구별되는 낙수 효과(trickle-down)로 변한다고 설명했다","어빙 고프먼(Erving Goffman)의 자기 연출(self-presentation)은 사람이 상황에 맞게 이미지를 연출한다는 개념이다","유행은 정체성(identity) 표현의 수단이 된다"]}],"b2aae23e4f084ebb_30":[{"t":"table","title":"사이버 공간과 기술 과장","head":["개념","내용"],"rows":[["사이버 공간(cyberspace)","윌리엄 깁슨(William Gibson)이 1984년 소설 『뉴로맨서』에서 널리 알렸다"],["가상 현실(virtual reality)","1990년대에 큰 기대를 받았다"],["하이프 사이클(hype cycle)","가트너의 개념으로 신기술이 기대 과열과 환멸을 거쳐 안정에 이른다고 설명한다"],["기술 낙관론","산업혁명 때의 기술 낙관론과 비교되기도 한다"]]}],"b2aae23e4f084ebb_31":[{"t":"vs","title":"경성 뉴스와 연성 뉴스","cols":[{"name":"경성 뉴스(hard news)","items":["정치, 경제 같은 뉴스","저널리즘 연구에서는 더 높은 지위를 갖는 위계가 있다고 본다"]},{"name":"연성 뉴스(soft news)","items":["스포츠, 연예 같은 뉴스","스포츠 섹션이 신문사에서 장난감 가게(toy department)로 불리며 낮게 평가된 적이 있지만 독자 수는 많다 · 이를 지위의 역설(paradox of status)이라 한다"]}]}],"b2aae23e4f084ebb_32":[{"t":"cause","title":"약한 연결","causes":["사회언어학(sociolinguistics)은 언어 변화가 사회 연결망을 따라 확산된다고 본다","마크 그래노베터(Mark Granovetter)의 약한 연결(weak ties) 이론은 느슨한 인맥이 정보 확산에 중요하다고 설명한다"],"result":"도시에서는 다양한 사람이 접촉해 속어(slang)와 어휘 혁신(lexical innovation)이 빠르게 나타난다","effects":[]}],"b2aae23e4f084ebb_33":[{"t":"flow","title":"꿀벌 춤","steps":["꿀벌은 먹이 위치를 동료에게 알리는 8자 춤인 꿀벌 춤(waggle dance)을 춘다","카를 폰 프리슈(Karl von Frisch)는 이를 해독해 1973년 노벨상을 받았다","연구자들은 군집이 개별 구성원의 단순한 상호작용으로 의사결정을 한다는 점에서 집단 지능(swarm intelligence)과 집단 의사결정(collective decision-making)을 논한다"]}],"b2aae23e4f084ebb_34":[{"t":"vs","title":"A계열과 B계열","cols":[{"name":"A계열(A-series)","items":["시간을 과거, 현재, 미래로 나눈다","시간 철학에서 맥타가트(J. M. E. McTaggart, 1908)가 구분했다"]},{"name":"B계열(B-series)","items":["앞서다, 뒤서다로 나눈다","영원주의(eternalism)는 모든 시점이 똑같이 실재한다고 보는 입장이며 블록 우주(block universe)와 연결된다","우리의 시간 의식이 허구일 수 있다는 주장도 있다"]}]}],"b2aae23e4f084ebb_35":[{"t":"table","title":"운율","head":["개념","내용"],"rows":[["운율(prosody)","언어학에서 억양, 강세, 속도, 높낮이처럼 말에 얹히는 소리의 특성"],["억양","같은 문장도 억양에 따라 질문이나 비꼼으로 달라진다"],["준언어(paralanguage)","의사소통 연구에서 말투와 목소리가 전달하는 정보를 가리키며 연설과 연기 훈련에서 중요시된다"]]}],"b2aae23e4f084ebb_37":[{"t":"cause","title":"성공 보수","causes":["성과 기반 가격 책정(results-based pricing)은 결과가 나올 때만 대가를 받는 방식이다","변호사의 성공 보수(contingency fee)가 대표적이다"],"result":"의뢰인의 위험을 줄이고 변호사의 유인을 맞춘다","effects":["경제학의 주인-대리인 문제(principal-agent problem)는 이해관계가 다른 두 당사자 사이의 유인 설계를 다룬다"]}],"b2aae23e4f084ebb_38":[{"t":"flow","title":"근대 도시 공원","steps":["근대 도시 공원은 19세기 산업 도시의 위생과 사회 개혁 요구에서 생겼다","프레더릭 로 옴스테드(Frederick Law Olmsted)가 설계한 뉴욕 센트럴파크(1858 착공)가 대표적이다","공원의 형태는 당대의 자연관, 계급 갈등, 여가 문화를 반영해 왔고 공공 공간(public space)의 의미를 두고 논쟁이 이어졌다"]}],"b2aae23e4f084ebb_40":[{"t":"table","title":"장인 정신","head":["인물","내용"],"rows":[["리처드 세넷(Richard Sennett)","사회학자로 『장인』(2008)에서 장인 정신을 일 자체를 잘 해내려는 인간의 기본 충동으로 정의했다"],["한나 아렌트(Hannah Arendt)","호모 파베르(homo faber)는 도구를 만들어 세계를 짓는 인간을 가리킨다"],["공예 운동","19세기 말 영국의 공예 운동(Arts and Crafts movement)은 산업화에 맞서 수공예를 되살리려 했다"]]}],"b2aae23e4f084ebb_41":[{"t":"flow","title":"알고리즘 혐오","steps":["심리학자 폴 밀(Paul Meehl)은 1954년 임상적 판단과 통계적 예측을 비교해 단순한 통계 모형이 전문가 판단보다 정확한 경우가 많다고 보고했다","이후 연구자들은 사람이 알고리즘의 실수를 본 뒤 알고리즘을 더 불신하는 알고리즘 혐오(algorithm aversion, Dietvorst 2015)를 확인했다"]}],"c6827ae7014cbcff_20":[{"t":"cause","title":"기본적 귀인 오류","causes":["사회심리학에서 기본적 귀인 오류(fundamental attribution error)는 타인의 행동을 상황보다 성격 탓으로 돌리는 경향이다","필립 짐바르도(Philip Zimbardo)의 스탠퍼드 감옥 실험(1971)은 상황이 행동에 미치는 힘을 보여 준 사례로 인용된다"],"result":"조직 행동 연구에서는 개인의 문제와 조직 문화(organizational culture)의 영향을 구별한다","effects":[]}],"c6827ae7014cbcff_21":[{"t":"cause","title":"옥타브 등가성","causes":["음악 음향학에서 주파수가 두 배가 되면 한 옥타브(octave) 위의 음이 되며 같은 음 이름으로 불린다"],"result":"이를 옥타브 등가성(octave equivalence)이라 한다","effects":["서양 음악의 12음 음계는 한 옥타브를 12개로 나눈 체계다","피타고라스(Pythagoras)는 현의 길이 비율과 음정의 관계를 연구했다고 전해진다"]}],"c6827ae7014cbcff_22":[{"t":"vs","title":"사회적 자본","cols":[{"name":"결속형(bonding)","items":["퍼트넘이 구분한 같은 집단 안의 사회적 자본"]},{"name":"연결형(bridging)","items":["서로 다른 집단을 잇는 사회적 자본"]}]},{"t":"def","term":"사회적 자본(social capital)","text":"사회학자 피에르 부르디외(Pierre Bourdieu)와 로버트 퍼트넘(Robert Putnam)이 발전시킨 개념으로 신뢰와 호혜성에 기반한 관계망이 주는 자원이며, 소셜 미디어는 이런 관계의 형성과 유지를 다룬 연구 주제다"}],"c6827ae7014cbcff_23":[{"t":"table","title":"전기와 자서전","head":["개념","내용"],"rows":[["전기(biography)","문학에서 타인의 삶을 쓴 글"],["자서전(autobiography)","자신이 쓴 글이며 둘을 합쳐 삶의 글쓰기(life writing)라 한다"],["1차 자료(primary source)","전기 작가는 문서, 인터뷰, 기록 같은 자료를 비판적으로 검증한다"],["서술자(narrator)","시점과 기억의 신뢰성도 쟁점이다"]]}],"c6827ae7014cbcff_24":[{"t":"tree","title":"중세 수도원","root":"중세 수도원은 베네딕토 규칙(Rule of St. Benedict)을 따라 기도와 노동을 병행(ora et labora)하는 공동체였다","branches":[["필사실(scriptorium)","수도사들이 고대 문헌을 베껴 지식을 보존했다"],["담당 일","농업, 의료, 교육, 구호를 담당했다"],["평가","유럽 중세 사회의 지적, 경제적 중심으로 평가된다"]]}],"c6827ae7014cbcff_30":[{"t":"vs","title":"경성 공학과 연성 공학","cols":[{"name":"경성 공학(hard engineering)","items":["하천 공학에서 제방, 댐처럼 인공 구조물로 물을 통제한다"]},{"name":"연성 공학(soft engineering)","items":["하천의 자연스러운 흐름과 범람원(floodplain)을 활용한다","자연과 함께 일하는(working with nature) 접근이며 하천 복원(river restoration)과 연결된다"]}]}],"c6827ae7014cbcff_31":[{"t":"table","title":"감각 편향과 속임","head":["개념","내용"],"rows":[["감각 편향(sensory bias)","동물행동학의 가설로 수컷의 신호가 암컷의 기존 지각 편향을 이용해 진화했다고 본다"],["바우어새","정자(bower)를 지어 암컷의 지각을 이용하며 원근법을 이용한 착시(forced perspective)를 만든다는 연구가 있다"],["위장·의태","위장(camouflage)과 의태(mimicry)도 포식자의 지각을 속이는 방법이다"]]}],"c6827ae7014cbcff_32":[{"t":"tree","title":"공감의 구분","root":"폴 블룸(Paul Bloom)은 『공감에 반대한다』(2016)에서 공감이 편향적이라고 비판했다","branches":[["정서적 공감(affective empathy)","상대 감정을 함께 느낀다"],["인지적 공감(cognitive empathy)","상대 입장을 이해한다"],["연민(compassion)","상대를 돕고자 한다"],["내집단 편향(in-group bias)","도 논점이다"]]}],"c6827ae7014cbcff_33":[{"t":"table","title":"조림과 생태계","head":["개념","내용"],"rows":[["조림(afforestation)","숲이 없던 곳에 나무를 심는 일"],["비산림 생태계","기후 대책으로 숲 확대가 권장되지만 초원, 습지 같은 비산림 생태계도 고유한 생물 다양성(biodiversity)과 탄소 저장 기능을 가진다"],["생태계 서비스(ecosystem services)","생태계가 인간에게 주는 혜택"]]}],"c6827ae7014cbcff_34":[{"t":"cause","title":"불가능성 정리","causes":["사회적 선택 이론(social choice theory)은 개인의 선호를 하나의 집단 결정으로 모으는 방법을 연구한다"],"result":"케네스 애로(Kenneth Arrow)의 불가능성 정리(impossibility theorem, 1951)는 몇 가지 합리적 조건을 모두 만족하는 투표 방식이 없다고 증명했다","effects":["동점 처리, 중립성(neutrality)과 익명성(anonymity)도 쟁점이다"]}],"c6827ae7014cbcff_35":[{"t":"vs","title":"멘토의 기능","cols":[{"name":"경력 기능(career functions)","items":["승진, 직무 지원 같은 기능","캐시 크램(Kathy Kram, 1985)이 나눈 멘토의 기능"]},{"name":"심리사회적 기능(psychosocial functions)","items":["조언, 정서 지원 같은 기능","다양한 멘토를 두는 다중 멘토링은 정보와 사회적 자본(social capital)을 넓힌다고 본다"]}]}],"c6827ae7014cbcff_36":[{"t":"vs","title":"쓰기 교육의 접근","cols":[{"name":"결과 중심(product approach)","items":["완성된 글을 평가한다"]},{"name":"과정 중심(process approach)","items":["계획, 초안, 수정, 편집을 거친다","피드백(feedback)과 동료 평가(peer review)가 중요하며 브레인스토밍(brainstorming)은 계획 단계의 대표 활동이다"]}]}],"c6827ae7014cbcff_37":[{"t":"tree","title":"수학 글쓰기","root":"수학 글은 흔히 정의(definition), 정리(theorem), 증명(proof)의 형식으로 짜인다","branches":[["기호 표기법(notation)","수학의 역사에서 비교적 뒤늦게 발달했다"],["엄밀함(rigor)","모든 주장을 논리로 뒷받침하려는 수학의 태도다"]]}],"c6827ae7014cbcff_38":[{"t":"flow","title":"노쇠와 낙엽","steps":["식물생리학에서 잎이 떨어지는 현상은 단순한 죽음이 아니라 노쇠(senescence)라는 능동적 과정이다","가을에 엽록소(chlorophyll)가 분해되면서 영양분이 줄기로 재흡수된다","잎자루에 떨켜(abscission layer)가 생겨 잎이 떨어진다","낙엽수(deciduous tree)는 이렇게 겨울의 에너지 소모와 수분 손실을 줄인다"]}],"c6827ae7014cbcff_39":[{"t":"vs","title":"1차 사료와 2차 사료","cols":[{"name":"1차 사료(primary source)","items":["역사학에서 직접 증거","건축사에서는 건물 유구뿐 아니라 설계도, 일기, 기록이 증거로 쓰인다"]},{"name":"2차 사료(secondary source)","items":["후대 해석","역사를 어떻게 쓰는지 연구하는 사학사(historiography)는 증거의 신뢰도를 따지는 데 기반이 된다"]}]}],"c6827ae7014cbcff_40":[{"t":"table","title":"초허구성","head":["개념","내용"],"rows":[["초허구성(transfictionality)","서사 이론에서 하나의 허구 인물이나 세계가 여러 작품에 걸쳐 나타나는 현상"],["예","셜록 홈즈의 파생작과 팬 픽션(fan fiction), 속편, 스핀오프"],["상호텍스트성(intertextuality)","텍스트가 다른 텍스트와 맺는 관계"]]}],"ce57f02ce782bac3_20":[{"t":"table","title":"자신감과 불편함","head":["개념","내용"],"rows":[["자기효능감(self-efficacy)","심리학에서 자신이 과제를 해낼 수 있다는 믿음"],["노출 치료(exposure therapy)","불안을 줄이는 치료 방식으로 두려운 대상에 점진적으로 직면하게 한다"],["안전지대(comfort zone)","편안한 영역을 벗어날 때 성장한다는 관점으로 흔히 설명된다"]]}],"ce57f02ce782bac3_21":[{"t":"table","title":"프로젝트 관리의 함정","head":["개념","내용"],"rows":[["범위 확대(scope creep)","프로젝트 관리에서 요구되지 않은 작업이 슬금슬금 늘어나는 현상"],["골드 플레이팅(gold plating)","요구 이상의 기능을 덧붙이는 행동"],["비용 대비 효익(cost-benefit)","따지지 않으면 자원이 낭비된다"],["삼중 제약(triple constraint)","프로젝트의 범위, 비용, 일정"]]}],"ce57f02ce782bac3_22":[{"t":"table","title":"문화 적응","head":["개념","내용"],"rows":[["문화 적응(acculturation) 모형","이주민이 새 사회에 적응하는 방식은 동화(assimilation), 통합(integration), 분리, 주변화로 구분되는데, 존 베리(John Berry)의 모형이 대표적이다"],["용광로(melting pot)","하나로 녹아든다는 뜻의 모델"],["샐러드 볼(salad bowl)","각자의 정체성을 유지한다는 은유"],["다문화주의(multiculturalism)","후자와 가깝다"]]}],"ce57f02ce782bac3_23":[{"t":"cause","title":"청중 상품론","causes":["미디어 경제학에서 달라스 스마이드(Dallas Smythe, 1977)는 상업 방송이 프로그램을 팔기보다 청중(audience)을 광고주에게 판다는 청중 상품론(audience commodity)을 제시했다"],"result":"청취율(ratings)이 광고 단가를 결정한다","effects":["방송은 음악 장르별 포맷(format)으로 청중을 확보한다"]}],"ce57f02ce782bac3_24":[{"t":"table","title":"웹과 기록의 수명","head":["개념","내용"],"rows":[["신문 기록(newspaper archive)","웹 이전에는 전문 연구자의 영역이었다"],["롱테일(long tail, 2004)","크리스 앤더슨(Chris Anderson)의 이론으로 인터넷이 비인기 콘텐츠의 소비를 가능하게 한다"],["잊힐 권리(right to be forgotten)","기사가 오래 남는 환경은 유럽의 논쟁과도 연결된다"]]}],"ce57f02ce782bac3_29":[{"t":"vs","title":"위협 반응과 도전 반응","cols":[{"name":"위협(threat) 반응","items":["심리학에서 스트레스 반응의 한 구분","교감신경계가 활성화되는 투쟁-도피 반응(fight-or-flight)은 아드레날린과 코르티솔 분비를 동반한다"]},{"name":"도전(challenge) 반응","items":["제러미 제이미슨(Jeremy Jamieson) 연구는 스트레스를 도움이 되는 자원으로 해석하면 수행이 향상될 수 있음을 보여 주었다"]}]}],"ce57f02ce782bac3_30":[{"t":"table","title":"장소의 가치","head":["개념","내용"],"rows":[["장소","경제지리학에서 상품의 가치를 높이는 요소"],["지리적 표시(geographical indication)","샴페인(Champagne)처럼 특정 지역에서만 쓸 수 있는 상품 명칭"],["테루아르(terroir)","토양, 기후가 만드는 고유 특성"],["원산지(country of origin)","소비자가 원산지에 따라 품질을 판단하는 현상도 연구된다"]]}],"ce57f02ce782bac3_31":[{"t":"flow","title":"교외화","steps":["2차 세계대전 후 미국에서는 도시 중심에서 교외(suburb)로 인구가 이동하는 교외화(suburbanization)가 크게 일어났다","레빗타운(Levittown) 같은 대량 주택 단지와 제대군인 지원법(GI Bill)이 이를 뒷받침했다","자동차 의존(car dependency)과 도시 확산(urban sprawl)은 이후 도시계획의 쟁점이 되었다"]}],"ce57f02ce782bac3_32":[{"t":"vs","title":"이미지 검색 방식","cols":[{"name":"메타데이터 기반","items":["파일에 붙은 메타데이터(metadata)와 태그(tag)로 찾는다"]},{"name":"내용 기반 이미지 검색(CBIR)","items":["이미지 내용을 직접 분석한다","컴퓨터가 읽는 저수준 특징과 사람이 이해하는 의미 사이의 간극을 의미 격차(semantic gap)라 하며 컴퓨터 비전(computer vision)이 이를 줄이려 한다"]}]}]};
